css:
.asm-rooms {
  /* re-theme with these four */
  --asm-rooms-paper: oklch(0.966 0.012 82);
  --asm-rooms-ink: oklch(0.26 0.024 58);
  --asm-rooms-accent: oklch(0.76 0.15 72);
  --asm-rooms-night: oklch(0.235 0.014 62);
  /* derived */
  --asm-rooms-card: color-mix(in oklch, white 62%, var(--asm-rooms-paper));
  --asm-rooms-side: color-mix(in oklch, var(--asm-rooms-ink) 4%, var(--asm-rooms-paper));
  --asm-rooms-line: color-mix(in oklch, var(--asm-rooms-ink) 11%, transparent);
  --asm-rooms-line2: color-mix(in oklch, var(--asm-rooms-ink) 19%, transparent);
  --asm-rooms-mute: color-mix(in oklch, var(--asm-rooms-ink) 62%, var(--asm-rooms-paper));
  --asm-rooms-faint: color-mix(in oklch, var(--asm-rooms-ink) 42%, var(--asm-rooms-paper));
  --asm-rooms-hover: color-mix(in oklch, var(--asm-rooms-ink) 5%, transparent);
  --asm-rooms-tint: color-mix(in oklch, var(--asm-rooms-accent) 18%, var(--asm-rooms-card));
  --asm-rooms-deep: color-mix(in oklch, var(--asm-rooms-accent) 55%, var(--asm-rooms-ink));
  --asm-rooms-ease: cubic-bezier(.2, .8, .2, 1);
  --asm-rooms-spring: linear(0, 0.12 4%, 0.42 10%, 0.78 17%, 0.98 24%, 1.06 30%, 1.07 36%, 1.035 45%, 1.005 56%, 0.997 70%, 1);

  position: relative; width: 100%; height: var(--asm-rooms-h, 680px); box-sizing: border-box;
  container-type: inline-size; container-name: asm-rooms; overflow: clip; isolation: isolate;
  background: var(--asm-rooms-paper); color: var(--asm-rooms-ink); color-scheme: light;
  accent-color: var(--asm-rooms-deep); border-radius: 16px;
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  box-shadow: inset 0 0 0 1px var(--asm-rooms-line); -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--asm-rooms-deep); outline-offset: 2px; }
  & button { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
  & button:disabled { cursor: not-allowed; opacity: .42; }
  & h2, & h3, & p, & ul { margin: 0; padding: 0; }
  & ul { list-style: none; }
  & [hidden] { display: none !important; }
  & svg { fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { font: 600 10px/1 ui-monospace, Menlo, monospace; min-width: 17px; padding: 3px 4px; text-align: center; border-radius: 5px;
    color: var(--asm-rooms-mute); background: var(--asm-rooms-card); box-shadow: inset 0 0 0 1px var(--asm-rooms-line2), inset 0 -1.5px 0 var(--asm-rooms-line2); }
}

.asm-rooms .asm-rooms-app {
  height: 100%; display: grid;
  grid-template-columns: 212px minmax(0, 1fr) 328px;
  grid-template-rows: auto minmax(0, 1fr) auto;
  grid-template-areas: "top top top" "list plan panel" "keys keys keys";
}

.asm-rooms .asm-rooms-eyebrow {
  font-size: 10.5px; font-weight: 650; letter-spacing: .09em; text-transform: uppercase; color: var(--asm-rooms-faint);
}

/* ── top bar ───────────────────────────── */
.asm-rooms .asm-rooms-top {
  grid-area: top; display: flex; align-items: center; gap: 14px; padding: 12px 16px;
  border-bottom: 1px solid var(--asm-rooms-line);
}
.asm-rooms .asm-rooms-brand {
  display: flex; align-items: center; gap: 10px; min-width: 0;
  & > svg { width: 30px; height: 30px; padding: 6px; border-radius: 9px; background: var(--asm-rooms-ink); color: var(--asm-rooms-accent); stroke-width: 2; }
  & b { display: block; font-size: 14.5px; letter-spacing: -.01em; }
  & small { display: block; font-size: 11.5px; color: var(--asm-rooms-mute); white-space: nowrap; }
}
.asm-rooms .asm-rooms-sum {
  margin-left: auto; font-size: 12.5px; color: var(--asm-rooms-mute); font-variant-numeric: tabular-nums; white-space: nowrap;
  & b { color: var(--asm-rooms-ink); font-weight: 650; }
}
.asm-rooms .asm-rooms-acts { display: flex; gap: 8px; }
.asm-rooms .asm-rooms-btn {
  display: inline-flex; align-items: center; gap: 7px; height: 32px; padding: 0 11px; border-radius: 9px; font-weight: 560;
  background: var(--asm-rooms-card); box-shadow: inset 0 0 0 1px var(--asm-rooms-line2);
  transition: background .2s, box-shadow .2s, transform .25s var(--asm-rooms-spring);
  & svg { width: 15px; height: 15px; }
  &:hover:not(:disabled) { background: color-mix(in oklch, var(--asm-rooms-ink) 4%, var(--asm-rooms-card)); }
  &:active:not(:disabled) { transform: scale(.96); }
  &.is-strong { background: var(--asm-rooms-ink); color: var(--asm-rooms-paper); box-shadow: none; }
  &.is-strong:hover:not(:disabled) { background: color-mix(in oklch, var(--asm-rooms-ink) 86%, var(--asm-rooms-accent)); }
}
.asm-rooms .asm-rooms-tabs { display: none; }

/* ── room list ─────────────────────────── */
.asm-rooms .asm-rooms-list {
  grid-area: list; min-height: 0; overflow: auto; padding: 16px 10px 16px 12px; background: var(--asm-rooms-side);
  border-right: 1px solid var(--asm-rooms-line); scrollbar-width: thin;
  & > h2 { padding: 0 8px 8px; }
  & ul { display: grid; gap: 2px; }
}
.asm-rooms .asm-rooms-room {
  position: relative; display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; gap: 2px 10px;
  padding: 9px 10px 10px; border-radius: 10px; cursor: pointer; outline-offset: -2px;
  transition: background .2s var(--asm-rooms-ease);
  & b { font-weight: 600; font-size: 13px; }
  & .t { font-size: 12px; color: var(--asm-rooms-mute); font-variant-numeric: tabular-nums; }
  & .s { grid-column: 1 / -1; font-size: 11.5px; color: var(--asm-rooms-faint); font-variant-numeric: tabular-nums; }
  & .g { grid-column: 1 / -1; height: 3px; border-radius: 3px; background: var(--asm-rooms-line); overflow: hidden; margin-top: 4px; }
  & .g i { display: block; height: 100%; width: 100%; transform-origin: left; transform: scaleX(var(--lv, 0));
    background: linear-gradient(90deg, color-mix(in oklch, var(--asm-rooms-accent) 60%, white), var(--asm-rooms-accent));
    transition: transform .6s var(--asm-rooms-ease); }
  &:hover { background: var(--asm-rooms-hover); }
  &[aria-selected="true"] { background: var(--asm-rooms-card); box-shadow: 0 1px 2px color-mix(in oklch, var(--asm-rooms-ink) 9%, transparent), inset 0 0 0 1px var(--asm-rooms-line); cursor: default; }
  &[aria-selected="true"]::before { content: ""; position: absolute; left: -6px; top: 12px; bottom: 12px; width: 3px; border-radius: 3px; background: var(--asm-rooms-accent); }
}

/* ── plan ──────────────────────────────── */
.asm-rooms .asm-rooms-plan {
  grid-area: plan; min-width: 0; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr) auto; gap: 10px; padding: 16px 18px 14px;
}
.asm-rooms .asm-rooms-planbar { display: flex; align-items: end; justify-content: space-between; gap: 12px; }
.asm-rooms .asm-rooms-live {
  font-size: 12.5px; color: var(--asm-rooms-mute); margin-top: 2px; display: flex; align-items: center; gap: 7px;
  & i { width: 7px; height: 7px; border-radius: 50%; background: oklch(0.68 0.16 145); box-shadow: 0 0 0 3px color-mix(in oklch, oklch(0.68 0.16 145) 22%, transparent); animation: asm-rooms-pulse 2.4s ease-in-out infinite; }
}
.asm-rooms .asm-rooms-seg {
  display: inline-flex; padding: 3px; border-radius: 10px; background: var(--asm-rooms-side); box-shadow: inset 0 0 0 1px var(--asm-rooms-line);
  & button { height: 26px; padding: 0 12px; border-radius: 7px; font-size: 12px; font-weight: 560; color: var(--asm-rooms-mute); transition: background .2s, color .2s; }
  & button[aria-checked="true"] { background: var(--asm-rooms-card); color: var(--asm-rooms-ink); box-shadow: 0 1px 2px color-mix(in oklch, var(--asm-rooms-ink) 14%, transparent); cursor: default; }
}
.asm-rooms .asm-rooms-planwrap {
  min-height: 0; position: relative; border-radius: 14px; overflow: hidden;
  background:
    radial-gradient(120% 80% at 50% 0%, color-mix(in oklch, var(--asm-rooms-night) 80%, white) 0%, transparent 70%),
    var(--asm-rooms-night);
  box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--asm-rooms-night) 70%, black), 0 18px 40px -24px color-mix(in oklch, var(--asm-rooms-ink) 70%, transparent);
  display: grid; place-items: center;
}
.asm-rooms .asm-rooms-svg {
  width: 100%; height: 100%; max-height: 100%; display: block; stroke-linecap: butt;
  --wall: oklch(0.72 0.012 70); --floor: color-mix(in oklch, var(--asm-rooms-night) 88%, white); --fur: oklch(0.44 0.014 65);
  & .pool, & .heat rect { stroke: none; }
  & .floor { fill: var(--floor); stroke: none; transition: fill .45s var(--asm-rooms-ease); }
  & .floor.is-out { fill: color-mix(in oklch, var(--asm-rooms-night) 94%, white); }
  & .hit { fill: transparent; stroke: none; cursor: pointer; }
  & .hit[aria-current="true"] { cursor: default; }
  & .hit:focus-visible { outline: none; stroke: var(--asm-rooms-accent); stroke-width: 3; }
  & .sel { fill: none; stroke: var(--asm-rooms-accent); stroke-width: 2.5; stroke-dasharray: 6 5; opacity: 0; transition: opacity .3s; pointer-events: none; animation: asm-rooms-march 1.6s linear infinite; }
  & .sel.is-on { opacity: .95; }
  & .walls { fill: none; stroke: var(--wall); stroke-width: 4; pointer-events: none; }
  & .walls .out { stroke-dasharray: 3 5; stroke-width: 2; opacity: .7; }
  & .door { stroke: var(--floor); stroke-width: 6; }
  & .doorarc { stroke: var(--wall); stroke-width: 1; opacity: .5; stroke-dasharray: 2 3; }
  & .fur { fill: none; stroke: var(--fur); stroke-width: 1.3; pointer-events: none; }
  & .pools { mix-blend-mode: screen; pointer-events: none; }
  & .pool { transform-box: fill-box; transform-origin: center; transition: opacity .55s var(--asm-rooms-ease), transform .8s var(--asm-rooms-spring); }
  & .pool stop { transition: stop-color .5s var(--asm-rooms-ease); }
  & .heat { pointer-events: none; transition: opacity .5s var(--asm-rooms-ease); opacity: 0; }
  & .win { stroke-width: 5; stroke-linecap: butt; pointer-events: none; }
  & .win .glass { stroke: oklch(0.62 0.05 235); }
  & .win .slat { stroke: oklch(0.86 0.02 80); transition: stroke-dashoffset .6s var(--asm-rooms-ease); }
  & .lbl { font: 600 11px system-ui, sans-serif; fill: oklch(0.9 0.01 80); letter-spacing: .02em; pointer-events: none; paint-order: stroke; stroke: var(--asm-rooms-night); stroke-width: 3px; stroke-linejoin: round; }
  & .lbl2 { font: 500 10px ui-monospace, Menlo, monospace; fill: oklch(0.72 0.02 80); pointer-events: none; paint-order: stroke; stroke: var(--asm-rooms-night); stroke-width: 3px; }
  & .lamp { cursor: pointer; }
  & .lamp .ring { fill: var(--asm-rooms-night); stroke: oklch(0.6 0.01 70); stroke-width: 1.5; transition: fill .3s, stroke .3s, transform .4s var(--asm-rooms-spring); transform-box: fill-box; transform-origin: center; }
  & .lamp .dot { fill: oklch(0.6 0.01 70); transition: fill .3s; }
  & .lamp[aria-pressed="true"] .ring { fill: color-mix(in oklch, var(--asm-rooms-accent) 30%, var(--asm-rooms-night)); stroke: var(--asm-rooms-accent); }
  & .lamp[aria-pressed="true"] .dot { fill: oklch(0.97 0.05 90); }
  & .lamp:hover .ring { transform: scale(1.25); }
  & .lamp:focus-visible { outline: none; }
  & .lamp:focus-visible .ring { stroke: white; stroke-width: 2.5; }
  & .dev { pointer-events: none; }
  & .dev .plug { fill: var(--asm-rooms-night); stroke: oklch(0.55 0.01 70); stroke-width: 1.2; }
  & .dev.is-on .plug { stroke: oklch(0.78 0.14 145); }
  & .dev .wave { fill: none; stroke: oklch(0.8 0.08 80); stroke-width: 1.4; opacity: 0; transform-box: fill-box; transform-origin: left center; }
  & .dev.is-on .wave { animation: asm-rooms-wave 1.8s var(--asm-rooms-ease) infinite; animation-delay: calc(var(--i) * 300ms); }
}
.asm-rooms[data-overlay="climate"] .asm-rooms-svg {
  & .pools { opacity: .18; transition: opacity .5s; }
  & .heat { opacity: .72; }
}
.asm-rooms .asm-rooms-svg .pools { transition: opacity .5s var(--asm-rooms-ease); }
.asm-rooms .asm-rooms-legend {
  display: flex; flex-wrap: wrap; gap: 6px 16px; font-size: 11.5px; color: var(--asm-rooms-mute); font-variant-numeric: tabular-nums;
  & span { display: inline-flex; align-items: center; gap: 6px; }
  & i { width: 22px; height: 8px; border-radius: 4px; }
}

/* ── panel ─────────────────────────────── */
.asm-rooms .asm-rooms-panel {
  grid-area: panel; min-height: 0; overflow: auto; border-left: 1px solid var(--asm-rooms-line); background: var(--asm-rooms-side);
  padding: 16px 16px 20px; scrollbar-width: thin; display: flex; flex-direction: column; gap: 14px;
}
.asm-rooms .asm-rooms-phead {
  display: grid; grid-template-columns: auto minmax(0, 1fr); align-items: center; gap: 2px 10px;
  & h2 { grid-column: 2; font-size: clamp(17px, 1.2cqi + 6px, 21px); font-weight: 680; letter-spacing: -.02em; text-wrap: balance; line-height: 1.15; }
  & p { grid-column: 2; font-size: 12px; color: var(--asm-rooms-mute); font-variant-numeric: tabular-nums; }
  & .back { grid-row: 1 / 3; display: none; width: 30px; height: 30px; border-radius: 8px; place-items: center; box-shadow: inset 0 0 0 1px var(--asm-rooms-line2); }
  & .back svg { width: 16px; height: 16px; }
}
.asm-rooms .asm-rooms-scenes {
  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 6px;
  & button {
    display: grid; justify-items: center; gap: 5px; padding: 9px 4px 8px; border-radius: 11px; font-size: 11.5px; font-weight: 600;
    background: var(--asm-rooms-card); box-shadow: inset 0 0 0 1px var(--asm-rooms-line);
    transition: background .2s, box-shadow .2s, transform .3s var(--asm-rooms-spring);
  }
  & button:hover { box-shadow: inset 0 0 0 1px var(--asm-rooms-line2); }
  & button:active { transform: scale(.95); }
  & button[aria-pressed="true"] { background: var(--asm-rooms-tint); box-shadow: inset 0 0 0 1.5px var(--asm-rooms-accent); }
  & svg { width: 18px; height: 18px; }
  & kbd { min-width: 15px; padding: 2px 3px; font-size: 9px; }
}
.asm-rooms .asm-rooms-devs { display: grid; gap: 8px; }
.asm-rooms .asm-rooms-dev {
  display: grid; grid-template-columns: 34px minmax(0, 1fr) auto; align-items: center; gap: 4px 11px; padding: 11px 12px;
  border-radius: 13px; background: var(--asm-rooms-card); box-shadow: inset 0 0 0 1px var(--asm-rooms-line);
  transition: box-shadow .25s, background .25s;
  &.is-in { animation: asm-rooms-in .5s var(--asm-rooms-ease) both; animation-delay: calc(var(--i) * 45ms); }
  & .ic { width: 34px; height: 34px; border-radius: 10px; display: grid; place-items: center; background: var(--asm-rooms-side); color: var(--asm-rooms-mute); transition: background .3s, color .3s; }
  & .ic svg { width: 18px; height: 18px; }
  & b { display: block; font-weight: 600; font-size: 13px; line-height: 1.25; text-wrap: balance; }
  & small { display: block; font-size: 11.5px; color: var(--asm-rooms-mute); font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .more { grid-column: 1 / -1; display: grid; gap: 8px; padding-top: 6px; }
  &.is-on { box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--asm-rooms-accent) 45%, var(--asm-rooms-line)); }
  &.is-on .ic { background: color-mix(in oklch, var(--glow, var(--asm-rooms-accent)) 34%, var(--asm-rooms-card)); color: var(--asm-rooms-ink); }
}
.asm-rooms .asm-rooms-range {
  display: grid; grid-template-columns: 74px minmax(0, 1fr) 46px; align-items: center; gap: 8px; font-size: 11.5px; color: var(--asm-rooms-mute);
  & output { text-align: right; font: 500 11px ui-monospace, Menlo, monospace; color: var(--asm-rooms-ink); font-variant-numeric: tabular-nums; }
  & input { width: 100%; margin: 0; height: 18px; }
  & input.k { appearance: none; height: 6px; border-radius: 4px; background: linear-gradient(90deg, oklch(0.8 0.13 62), oklch(0.95 0.03 95), oklch(0.86 0.05 240)); }
  & input.k::-webkit-slider-thumb { appearance: none; width: 16px; height: 16px; border-radius: 50%; background: white; box-shadow: 0 0 0 1px var(--asm-rooms-line2), 0 1px 4px color-mix(in oklch, var(--asm-rooms-ink) 30%, transparent); }
  & input.k::-moz-range-thumb { width: 16px; height: 16px; border: 0; border-radius: 50%; background: white; box-shadow: 0 0 0 1px var(--asm-rooms-line2); }
}
.asm-rooms .asm-rooms-switch {
  position: relative; width: 38px; height: 22px; border-radius: 99px; background: var(--asm-rooms-line2); transition: background .25s var(--asm-rooms-ease);
  &::after { content: ""; position: absolute; left: 3px; top: 3px; width: 16px; height: 16px; border-radius: 50%; background: white;
    box-shadow: 0 1px 3px color-mix(in oklch, var(--asm-rooms-ink) 35%, transparent); transition: transform .45s var(--asm-rooms-spring); }
  &[aria-checked="true"] { background: var(--asm-rooms-deep); }
  &[aria-checked="true"]::after { transform: translateX(16px); }
}
.asm-rooms .asm-rooms-mini {
  display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 10px; border-radius: 8px; font-size: 12px; font-weight: 560;
  box-shadow: inset 0 0 0 1px var(--asm-rooms-line2); background: var(--asm-rooms-card); transition: background .2s;
  &:hover:not(:disabled) { background: var(--asm-rooms-hover); }
  & svg { width: 14px; height: 14px; }
}
.asm-rooms .asm-rooms-row { display: flex; gap: 6px; align-items: center; }
.asm-rooms .asm-rooms-sensor {
  display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 6px; margin-top: auto;
  & div { padding: 9px 10px; border-radius: 11px; box-shadow: inset 0 0 0 1px var(--asm-rooms-line); }
  & dt { font-size: 10.5px; letter-spacing: .06em; text-transform: uppercase; color: var(--asm-rooms-faint); font-weight: 600; }
  & dd { margin: 2px 0 0; font-size: 15px; font-weight: 650; font-variant-numeric: tabular-nums; letter-spacing: -.01em; }
}

/* ── footer, toast ─────────────────────── */
.asm-rooms .asm-rooms-keys {
  grid-area: keys; display: flex; flex-wrap: wrap; gap: 4px 18px; padding: 8px 16px; border-top: 1px solid var(--asm-rooms-line);
  font-size: 11.5px; color: var(--asm-rooms-mute);
  & span { display: inline-flex; align-items: center; gap: 4px; }
}
.asm-rooms .asm-rooms-toast {
  position: absolute; left: 50%; bottom: 46px; z-index: 5; display: flex; align-items: center; gap: 14px; max-width: calc(100% - 32px);
  padding: 9px 9px 9px 14px; border-radius: 12px; background: var(--asm-rooms-ink); color: var(--asm-rooms-paper); font-size: 12.5px;
  box-shadow: 0 14px 34px -10px color-mix(in oklch, var(--asm-rooms-ink) 60%, transparent);
  translate: -50% 0; transition: opacity .3s var(--asm-rooms-ease), translate .45s var(--asm-rooms-spring);
  @starting-style { opacity: 0; translate: -50% 14px; }
  & span { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  & button { flex: none; height: 26px; padding: 0 10px; border-radius: 7px; font-weight: 650; color: var(--asm-rooms-accent); background: color-mix(in oklch, var(--asm-rooms-paper) 10%, transparent); }
  & button:hover { background: color-mix(in oklch, var(--asm-rooms-paper) 18%, transparent); }
}

@keyframes asm-rooms-in { from { opacity: 0; transform: translateY(8px) scale(.985); } }
@keyframes asm-rooms-pulse { 50% { box-shadow: 0 0 0 6px color-mix(in oklch, oklch(0.68 0.16 145) 0%, transparent); } }
@keyframes asm-rooms-march { to { stroke-dashoffset: -22; } }
@keyframes asm-rooms-wave { 0% { opacity: 0; transform: scale(.6); } 30% { opacity: .9; } 100% { opacity: 0; transform: scale(1.5); } }

/* ── responsive ────────────────────────── */
@container asm-rooms (width < 960px) {
  .asm-rooms .asm-rooms-app {
    grid-template-columns: minmax(0, 1fr) 300px;
    grid-template-rows: auto auto minmax(0, 1fr) auto;
    grid-template-areas: "top top" "list list" "plan panel" "keys keys";
  }
  .asm-rooms .asm-rooms-list {
    border-right: 0; border-bottom: 1px solid var(--asm-rooms-line); padding: 8px 12px; overflow-x: auto; overflow-y: hidden;
    & > h2 { display: none; }
    & ul { display: flex; gap: 6px; }
  }
  .asm-rooms .asm-rooms-room { flex: none; min-width: 132px; padding: 7px 10px 8px;
    & .s { display: none; }
    &[aria-selected="true"]::before { left: 10px; right: 10px; top: auto; bottom: 2px; width: auto; height: 2px; }
  }
}
@container asm-rooms (width < 760px) {
  .asm-rooms .asm-rooms-app {
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: auto minmax(0, 1fr) auto;
    grid-template-areas: "top" "main" "keys";
  }
  .asm-rooms .asm-rooms-top { flex-wrap: wrap; gap: 10px; padding: 10px 12px; }
  .asm-rooms .asm-rooms-brand small { display: none; }
  .asm-rooms .asm-rooms-tabs {
    display: inline-flex; order: 3; width: 100%; padding: 3px; border-radius: 10px; background: var(--asm-rooms-side); box-shadow: inset 0 0 0 1px var(--asm-rooms-line);
    & button { flex: 1; height: 30px; border-radius: 7px; font-weight: 600; font-size: 12.5px; color: var(--asm-rooms-mute); }
    & button[aria-selected="true"] { background: var(--asm-rooms-card); color: var(--asm-rooms-ink); box-shadow: 0 1px 2px color-mix(in oklch, var(--asm-rooms-ink) 14%, transparent); }
  }
