  { id: 'p2', room: 'kitchen', type: 'plug', name: 'Kettle', on: false, w: 2200, x: 452, y: 40 },
  { id: 'l6', room: 'balcony', type: 'light', name: 'String lights', on: true, bri: 0.5, k: 2200, w: 5, x: 525, y: 85, r: 85 },
  { id: 'l7', room: 'hall', type: 'light', name: 'Ceiling spots', on: false, bri: 0.8, k: 3000, w: 12, x: 395, y: 195, r: 95 },
  { id: 'l8', room: 'hall', type: 'light', name: 'Entry lamp', on: true, bri: 0.25, k: 2400, w: 5, x: 450, y: 222, r: 62 },
  { id: 'l9', room: 'bath', type: 'light', name: 'Mirror light', on: false, bri: 1, k: 4000, w: 10, x: 525, y: 190, r: 95 },
  { id: 'p3', room: 'bath', type: 'plug', name: 'Towel rail', on: true, w: 120, x: 560, y: 360 },
