  { id: 'l10', room: 'study', type: 'light', name: 'Desk lamp', on: true, bri: 0.85, k: 4000, w: 7, x: 42, y: 322, r: 96 },
  { id: 'p4', room: 'study', type: 'plug', name: 'Workstation', on: true, w: 64, x: 140, y: 384 },
  { id: 'b2', room: 'study', type: 'blind', name: 'Study blind', pos: 0.55, win: [20, 290, 20, 370] },
  { id: 'l11', room: 'bed', type: 'light', name: 'Bedside, left', on: false, bri: 0.3, k: 2200, w: 4, x: 290, y: 256, r: 74 },
  { id: 'l12', room: 'bed', type: 'light', name: 'Bedside, right', on: false, bri: 0.3, k: 2200, w: 4, x: 290, y: 384, r: 74 },
  { id: 'b3', room: 'bed', type: 'blind', name: 'Blackout blind', pos: 0, win: [250, 400, 420, 400] },
  { id: 'p5', room: 'bed', type: 'plug', name: 'Air purifier', on: true, w: 18, x: 450, y: 384 }
];
const TRACKS = [
  ['Low Tide Radio', 'Hour 3 · ambient'],
  ['Kettle & Keys', 'Sunday Lieder · live'],
  ['Wren Alder', 'Small Hours, side B'],
  ['North Sea Shipping', 'Late forecast']
];
const SCENES = [
  { id: 'bright', name: 'Bright', key: '1', icon: '<circle cx="12" cy="12" r="4"/><path d="M12 2.5v2M12 19.5v2M2.5 12h2M19.5 12h2M5.3 5.3l1.4 1.4M17.3 17.3l1.4 1.4M5.3 18.7l1.4-1.4M17.3 6.7l1.4-1.4"/>' },
  { id: 'relax', name: 'Relax', key: '2', icon: '<path d="M4 15.5c2.5 0 3-3 5.5-3s3 3 5.5 3 3-3 5-3"/><path d="M4 10c2.5 0 3-3 5.5-3s3 3 5.5 3 3-3 5-3"/>' },
  { id: 'night', name: 'Night', key: '3', icon: '<path d="M19 14.5A7.5 7.5 0 0 1 9.5 5a7.5 7.5 0 1 0 9.5 9.5Z"/>' },
  { id: 'off', name: 'Off', key: '4', icon: '<path d="M12 3v8"/><path d="M7.2 6.2a7.5 7.5 0 1 0 9.6 0"/>' }
];
const ICON = {
  light: '<path d="M9 18h6M10 21h4"/><path d="M12 3a6 6 0 0 0-3.5 10.9c.6.5 1 1.2 1 2.1h5c0-.9.4-1.6 1-2.1A6 6 0 0 0 12 3Z"/>',
  blind: '<path d="M4 4h16M5 4v13M19 4v13"/><path d="M5 8h14M5 12h14M5 16h14"/><path d="M12 16v4"/>',
  plug: '<path d="M9 3v5M15 3v5"/><path d="M6.5 8h11v3.5a5.5 5.5 0 0 1-11 0Z"/><path d="M12 17v4"/>',
  speaker: '<rect x="6" y="3" width="12" height="18" rx="2.5"/><circle cx="12" cy="14" r="3"/><circle cx="12" cy="7.5" r=".6"/>'
};
const ic = (p) => '<svg viewBox="0 0 24 24" aria-hidden="true">' + p + '</svg>';

const state = {
  room: 'living',
  overlay: 'light',
  dev: START.map((d) => Object.assign({}, d)),
  undo: []
};
const byId = (id) => state.dev.find((d) => d.id === id);
const inRoom = (rid) => state.dev.filter((d) => d.room === rid);
const lightsOf = (rid) => inRoom(rid).filter((d) => d.type === 'light');

/* ── derived numbers ── */
function draw(d) {
  if (d.type === 'light') return d.on ? d.w * (0.12 + 0.88 * d.bri) : 0;
  if (d.type === 'plug') return d.on ? d.w : 0;
  if (d.type === 'speaker') return d.on ? d.w : 1.5;
  return 0;
}
const fmtW = (w) => (w >= 1000 ? (w / 1000).toFixed(2) + ' kW' : Math.round(w) + ' W');
function kColor(k) {
  /* 2200 K amber → 4000 K neutral → 6500 K cool, mixed in oklch */
  if (k <= 4000) {
    const p = Math.round(((k - 2200) / 1800) * 100);
    return 'color-mix(in oklch, oklch(0.93 0.035 92) ' + p + '%, oklch(0.78 0.16 60))';
  }
  const p = Math.round(((k - 4000) / 2500) * 100);
  return 'color-mix(in oklab, oklch(0.9 0.05 240) ' + p + '%, oklch(0.93 0.035 92))';
}
function tempColor(t) {
  /* cool slate below 20°, sand at 20°, terracotta toward 24°; mixed in oklab so no hue detour */
  if (t <= 20) {
    const p = Math.max(0, Math.min(100, Math.round(((t - 12) / 8) * 100)));
    return 'color-mix(in oklab, oklch(0.72 0.05 88) ' + p + '%, oklch(0.56 0.09 238))';
  }
  const p = Math.max(0, Math.min(100, Math.round(((t - 20) / 4) * 100)));
  return 'color-mix(in oklab, oklch(0.64 0.15 38) ' + p + '%, oklch(0.72 0.05 88))';
}
function roomLevel(rid) {
  const ls = lightsOf(rid);
  if (!ls.length) return 0;
  return ls.reduce((s, d) => s + (d.on ? d.bri : 0), 0) / ls.length;
}

/* ── undo ── */
function snapshot() { return state.dev.map((d) => Object.assign({}, d)); }
function commit(label, before) {
  state.undo.push({ label: label, dev: before });
  if (state.undo.length > 40) state.undo.shift();
  toast(label, true);
}
function undo() {
  const u = state.undo.pop();
  if (!u) return;
  state.dev = u.dev;
  renderAll();
  toast('Undone: ' + u.label, false);
}

/* ── toast ── */
let toastT = 0;
function toast(msg, withUndo) {
  const t = $('[data-toast]');
  $('[data-toast-msg]').textContent = msg;
  $('[data-act="undo-toast"]', t).hidden = !withUndo;
  t.hidden = false;
  clearTimeout(toastT);
  toastT = setTimeout(() => { if (root.isConnected) t.hidden = true; }, 4200);
}

/* ── plan (built once, painted on every change) ── */
const svg = $('[data-plan]');
function el(tag, attrs, parent) {
  const n = document.createElementNS(NS, tag);
  for (const k in attrs) n.setAttribute(k, attrs[k]);
  if (parent) parent.appendChild(n);
  return n;
}
function buildPlan() {
  const defs = el('defs', {}, svg);
  ROOMS.forEach((r) => {
    const cp = el('clipPath', { id: uid + '-c-' + r.id }, defs);
    el('rect', { x: r.x, y: r.y, width: r.w, height: r.h }, cp);
  });
  state.dev.filter((d) => d.type === 'light').forEach((d) => {
    const g = el('radialGradient', { id: uid + '-g-' + d.id }, defs);
    el('stop', { offset: '0', 'data-s0': d.id }, g);
    el('stop', { offset: '.45', 'data-s1': d.id }, g);
    el('stop', { offset: '1', style: 'stop-color: transparent' }, g);
  });
  const floors = el('g', {}, svg);
  ROOMS.forEach((r) => el('rect', { class: 'floor' + (r.out ? ' is-out' : ''), x: r.x, y: r.y, width: r.w, height: r.h, 'data-floor': r.id }, floors));
  const heat = el('g', { class: 'heat' }, svg);
  ROOMS.forEach((r) => el('rect', { x: r.x + 2, y: r.y + 2, width: r.w - 4, height: r.h - 4, 'data-heat': r.id, rx: 3 }, heat));
  /* furniture, drawn on the same 600×420 grid */
  const fur = el('g', { class: 'fur' }, svg);
  [
    'M58 168h150v34H58z', 'M58 168v-8h150v8', 'M96 120h74v30H96z', 'M210 70m-30 0a30 18 0 1 0 60 0a30 18 0 1 0-60 0',
    'M326 26h138v20H326z', 'M372 82h46v34h-46z', 'M300 266h92v108h-92z', 'M300 266h14v108h-14', 'M330 280h48v80h-48', 'M180 352h44v40h-44z',
    'M30 300h22v70H30z', 'M60 360h90v30H60z', 'M486 300h80v92h-80z', 'M496 310h60v72a8 8 0 0 1-8 0h-44z', 'M486 160h40v28h-40z',
    'M480 32l90 0M480 60l90 0', 'M406 380h50v14h-50z'
  ].forEach((d) => el('path', { d: d }, fur));
  const pools = el('g', { class: 'pools' }, svg);
  state.dev.filter((d) => d.type === 'light').forEach((d) => {
    el('circle', { class: 'pool', cx: d.x, cy: d.y, r: d.r, fill: 'url(#' + uid + '-g-' + d.id + ')', 'clip-path': 'url(#' + uid + '-c-' + d.room + ')', 'data-pool': d.id }, pools);
  });
  /* windows and blinds */
  const wins = el('g', { class: 'win' }, svg);
  state.dev.filter((d) => d.type === 'blind').forEach((d) => {
    const [x1, y1, x2, y2] = d.win;
    const len = Math.hypot(x2 - x1, y2 - y1);
    el('line', { class: 'glass', x1, y1, x2, y2 }, wins);
    el('line', { class: 'slat', x1, y1, x2, y2, 'stroke-dasharray': len + ' ' + len, 'data-slat': d.id, 'data-len': len }, wins);
  });
  const walls = el('g', { class: 'walls' }, svg);
  el('path', { d: 'M20 20H470M470 150V400H20V20M320 20V240M170 240V400M320 150H470M320 240H470M470 150H580V400H470', class: 'in' }, walls);
  el('path', { d: 'M470 20H580V150', class: 'out' }, walls);
  /* door openings: a floor-coloured gap with a swing arc */
  [[320, 172, 320, 204, 'M320 204a32 32 0 0 1 32-32'], [358, 150, 390, 150, 'M358 150a32 32 0 0 0 32 32'],
   [470, 168, 470, 198, 'M470 198a30 30 0 0 0-30-30'], [402, 240, 432, 240, 'M402 240a30 30 0 0 0 30 30'],
   [170, 300, 170, 330, 'M170 300a30 30 0 0 1 30 30'], [470, 86, 470, 122, '']].forEach((a) => {
    el('line', { class: 'door', x1: a[0], y1: a[1], x2: a[2], y2: a[3] }, walls);
    if (a[4]) el('path', { class: 'doorarc', d: a[4] }, walls);
  });
  const sels = el('g', {}, svg);
  ROOMS.forEach((r) => el('rect', { class: 'sel', x: r.x + 3, y: r.y + 3, width: r.w - 6, height: r.h - 6, rx: 4, 'data-sel': r.id }, sels));
  const hits = el('g', {}, svg);
  ROOMS.forEach((r) => {
    const h = el('rect', { class: 'hit', x: r.x, y: r.y, width: r.w, height: r.h, role: 'button', tabindex: '-1', 'data-hit': r.id, 'aria-label': 'Select ' + r.name }, hits);
    h.addEventListener('keydown', (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); selectRoom(r.id); } });
  });
  const labels = el('g', {}, svg);
  ROOMS.forEach((r) => {
    const t = el('text', { class: 'lbl', x: r.x + 10, y: r.y + 20 }, labels);
    t.textContent = r.name;
    el('text', { class: 'lbl2', x: r.x + 10, y: r.y + 34, 'data-lbl2': r.id }, labels);
  });
  /* plugs and speakers are shown, not controlled, on the plan */
  const devs = el('g', {}, svg);
  state.dev.filter((d) => d.type === 'plug' || d.type === 'speaker').forEach((d, i) => {
    const g = el('g', { class: 'dev', 'data-pdev': d.id, style: '--i:' + (i % 3) }, devs);
    el('rect', { class: 'plug', x: d.x - 6, y: d.y - 6, width: 12, height: 12, rx: 3 }, g);
    if (d.type === 'speaker') {
      el('path', { class: 'wave', d: 'M' + (d.x - 18) + ' ' + (d.y - 8) + 'a10 10 0 0 0 0 16' }, g);
      el('path', { class: 'wave', d: 'M' + (d.x - 24) + ' ' + (d.y - 12) + 'a15 15 0 0 0 0 24', style: '--i:1' }, g);
    }
  });
  const lamps = el('g', {}, svg);
  state.dev.filter((d) => d.type === 'light').forEach((d) => {
    const g = el('g', { class: 'lamp', role: 'button', tabindex: '0', 'data-lamp': d.id }, lamps);
    el('circle', { class: 'ring', cx: d.x, cy: d.y, r: 8 }, g);
    el('circle', { class: 'dot', cx: d.x, cy: d.y, r: 3 }, g);
    g.addEventListener('keydown', (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); toggleDev(d.id); } });
  });
}

function paintPlan() {
  state.dev.forEach((d) => {
    if (d.type === 'light') {
      const p = $('[data-pool="' + d.id + '"]');
      const c = kColor(d.k);
      $('[data-s0="' + d.id + '"]').style.stopColor = c;
      $('[data-s1="' + d.id + '"]').style.stopColor = 'color-mix(in oklch, ' + c + ' 55%, transparent)';
      p.style.opacity = d.on ? (0.3 + 0.7 * d.bri).toFixed(3) : '0';
      p.style.transform = 'scale(' + (d.on ? 0.5 + 0.55 * d.bri : 0.35).toFixed(3) + ')';
      const l = $('[data-lamp="' + d.id + '"]');
      l.setAttribute('aria-pressed', String(d.on));
      l.setAttribute('aria-label', d.name + ', ' + roomById[d.room].name + (d.on ? ', on at ' + Math.round(d.bri * 100) + '%' : ', off') + '. Toggle');
    } else if (d.type === 'blind') {
      const s = $('[data-slat="' + d.id + '"]');
      const len = +s.dataset.len;
      s.style.strokeDashoffset = String(len * d.pos);
    } else {
      $('[data-pdev="' + d.id + '"]').classList.toggle('is-on', !!d.on);
    }
  });
  ROOMS.forEach((r) => {
    const sel = r.id === state.room;
    $('[data-sel="' + r.id + '"]').classList.toggle('is-on', sel);
    const h = $('[data-hit="' + r.id + '"]');
    if (sel) h.setAttribute('aria-current', 'true'); else h.removeAttribute('aria-current');
    $('[data-heat="' + r.id + '"]').style.fill = tempColor(r.temp);
    const on = lightsOf(r.id).filter((d) => d.on).length;
    $('[data-lbl2="' + r.id + '"]').textContent = state.overlay === 'climate'
      ? r.temp.toFixed(1) + '° · ' + r.hum + '%'
      : (on ? on + ' on · ' + Math.round(roomLevel(r.id) * 100) + '%' : 'dark');
  });
  root.dataset.overlay = state.overlay;
  $$('[data-overlay]').forEach((b) => b.setAttribute('aria-checked', String(b.dataset.overlay === state.overlay)));
  const lg = $('[data-legend]');
  lg.innerHTML = state.overlay === 'climate'
    ? '<span><i style="background:linear-gradient(90deg,' + tempColor(12) + ',' + tempColor(20) + ',' + tempColor(24) + ')"></i>12° · 20° · 24°</span><span>Outdoor 11.8° · balcony sensor</span>'
    : '<span><i style="background:linear-gradient(90deg,' + kColor(2200) + ',' + kColor(4000) + ',' + kColor(6500) + ')"></i>2200 K to 6500 K</span><span>Pool size and glow follow brightness</span><span>Click a lamp to toggle it</span>';
}

/* ── rooms list ── */
function renderRooms() {
  const ul = $('[data-rooms]');
  ul.innerHTML = ROOMS.map((r) => {
    const ls = lightsOf(r.id), on = ls.filter((d) => d.on).length;
    const w = inRoom(r.id).reduce((s, d) => s + draw(d), 0);
    return '<li class="asm-rooms-room" role="option" tabindex="' + (r.id === state.room ? 0 : -1) + '" data-room="' + r.id + '" aria-selected="' + (r.id === state.room) + '">' +
      '<b>' + r.name + '</b><span class="t">' + r.temp.toFixed(1) + '°</span>' +
      '<span class="s">' + (on ? on + ' of ' + ls.length + ' lights on' : 'Lights off') + ' · ' + fmtW(w) + '</span>' +
      '<span class="g" aria-hidden="true"><i style="--lv:' + roomLevel(r.id).toFixed(3) + '"></i></span></li>';
  }).join('');
}

/* ── controls panel ── */
function sceneMatch(rid) {
  const ls = lightsOf(rid);
  if (ls.every((d) => !d.on)) return 'off';
  if (ls.every((d) => d.on && d.bri === 1 && d.k === 4000)) return 'bright';
  if (ls.every((d) => d.on && d.bri === 0.45 && d.k === 2500)) return 'relax';
  if (ls[0].on && ls[0].bri === 0.08 && ls.slice(1).every((d) => !d.on)) return 'night';
  return '';
}
function devCard(d, i, enter) {
  const cls = 'asm-rooms-dev' + (d.on || (d.type === 'blind' && d.pos > 0) ? ' is-on' : '') + (enter ? ' is-in' : '');
  let sub = '', ctrl = '', more = '';
  if (d.type === 'light') {
    sub = d.on ? Math.round(d.bri * 100) + '% · ' + d.k + ' K · ' + fmtW(draw(d)) : 'Off';
    ctrl = '<button type="button" class="asm-rooms-switch" role="switch" aria-checked="' + d.on + '" data-act="toggle" data-id="' + d.id + '" aria-label="' + d.name + '"></button>';
    if (d.on) more = '<div class="more">' +
      '<label class="asm-rooms-range"><span>Brightness</span><input type="range" min="1" max="100" value="' + Math.round(d.bri * 100) + '" data-bri="' + d.id + '"><output data-obri="' + d.id + '">' + Math.round(d.bri * 100) + '%</output></label>' +
      '<label class="asm-rooms-range"><span>Warmth</span><input type="range" class="k" min="2200" max="6500" step="100" value="' + d.k + '" data-k="' + d.id + '"><output data-ok="' + d.id + '">' + d.k + ' K</output></label></div>';
  } else if (d.type === 'blind') {
    sub = d.pos === 0 ? 'Closed' : d.pos === 1 ? 'Fully open' : 'Open ' + Math.round(d.pos * 100) + '%';
    ctrl = '<span class="asm-rooms-row">' +
      '<button type="button" class="asm-rooms-mini" data-act="blind" data-to="1" data-id="' + d.id + '"' + (d.pos === 1 ? ' disabled title="Already fully open"' : '') + '>Open</button>' +
      '<button type="button" class="asm-rooms-mini" data-act="blind" data-to="0" data-id="' + d.id + '"' + (d.pos === 0 ? ' disabled title="Already closed"' : '') + '>Close</button></span>';
    more = '<div class="more"><label class="asm-rooms-range"><span>Position</span><input type="range" min="0" max="100" step="5" value="' + Math.round(d.pos * 100) + '" data-pos="' + d.id + '"><output data-opos="' + d.id + '">' + Math.round(d.pos * 100) + '%</output></label></div>';
  } else if (d.type === 'plug') {
    sub = d.on ? 'Drawing ' + fmtW(d.w) : 'Off · 0 W';
    ctrl = '<button type="button" class="asm-rooms-switch" role="switch" aria-checked="' + d.on + '" data-act="toggle" data-id="' + d.id + '" aria-label="' + d.name + '"></button>';
  } else if (d.type === 'speaker') {
    const t = TRACKS[d.track];
    sub = (d.on ? 'Playing · ' : 'Paused · ') + t[0];
    ctrl = '<span class="asm-rooms-row">' +
      '<button type="button" class="asm-rooms-mini" data-act="play" data-id="' + d.id + '" aria-label="' + (d.on ? 'Pause' : 'Play') + ' ' + d.name + '">' + ic(d.on ? '<path d="M9 6v12M15 6v12"/>' : '<path d="M8 5.5v13l10-6.5Z"/>') + '</button>' +
      '<button type="button" class="asm-rooms-mini" data-act="next" data-id="' + d.id + '" aria-label="Next station">' + ic('<path d="M6 5.5v13l8.5-6.5Z"/><path d="M18 6v12"/>') + '</button></span>';
    more = '<div class="more"><small style="white-space:normal">' + t[1] + '</small><label class="asm-rooms-range"><span>Volume</span><input type="range" min="0" max="100" value="' + Math.round(d.vol * 100) + '" data-vol="' + d.id + '"><output data-ovol="' + d.id + '">' + Math.round(d.vol * 100) + '%</output></label></div>';
  }
  const glow = d.type === 'light' ? ' style="--i:' + i + ';--glow:' + kColor(d.k) + '"' : ' style="--i:' + i + '"';
  return '<li class="' + cls + '" data-card="' + d.id + '"' + glow + '><span class="ic">' + ic(ICON[d.type]) + '</span>' +
    '<span><b>' + d.name + '</b><small data-sub="' + d.id + '">' + sub + '</small></span>' + ctrl + more + '</li>';
}
function renderPanel(enter) {
  const r = roomById[state.room];
  const devs = inRoom(r.id);
  const on = devs.filter((d) => d.type === 'light' && d.on).length;
  const match = sceneMatch(r.id);
  const w = devs.reduce((s, d) => s + draw(d), 0);
  const focusKey = document.activeElement && root.contains(document.activeElement) ? (document.activeElement.dataset.act || '') + ':' + (document.activeElement.dataset.id || document.activeElement.dataset.scene || '') + ':' + (document.activeElement.dataset.to || '') : '';
  $('[data-panel]').innerHTML =
    '<div class="asm-rooms-phead"><button type="button" class="back" data-act="back" aria-label="Back to rooms">' + ic('<path d="M14.5 6 8.5 12l6 6"/>') + '</button>' +
    '<h2>' + r.name + '</h2><p>' + on + ' of ' + lightsOf(r.id).length + ' lights on · ' + fmtW(w) + ' now</p></div>' +
    '<div class="asm-rooms-scenes" role="group" aria-label="Scenes for ' + r.name + '">' +
    SCENES.map((s) => '<button type="button" data-act="scene" data-scene="' + s.id + '" aria-pressed="' + (match === s.id) + '">' + ic(s.icon) + s.name + '<kbd>' + s.key + '</kbd></button>').join('') + '</div>' +
    '<ul class="asm-rooms-devs">' + devs.map((d, i) => devCard(d, i, enter)).join('') + '</ul>' +
    '<dl class="asm-rooms-sensor"><div><dt>Temp</dt><dd>' + r.temp.toFixed(1) + '°</dd></div><div><dt>Humidity</dt><dd>' + r.hum + '%</dd></div><div><dt>' + (r.out ? 'Wind' : 'CO₂') + '</dt><dd>' + (r.out ? '9 km/h' : r.co2 + '') + '</dd></div></dl>';
  if (focusKey) {
    const [a, id, to] = focusKey.split(':');
    const n = $$('[data-panel] [data-act]').find((b) => b.dataset.act === a && (b.dataset.id || b.dataset.scene || '') === id && (b.dataset.to || '') === to);
    if (n && !n.disabled) n.focus({ preventScroll: true });
  }
}
function renderSum() {
  const lightsOn = state.dev.filter((d) => d.type === 'light' && d.on).length;
  const w = state.dev.reduce((s, d) => s + draw(d), 0);
  $('[data-sum]').innerHTML = '<b>' + lightsOn + '</b> lights on · <b>' + fmtW(w) + '</b> now';
  const ub = $('[data-act="undo"]');
  ub.disabled = !state.undo.length;
  ub.title = state.undo.length ? 'Undo: ' + state.undo[state.undo.length - 1].label + ' (Z)' : 'Nothing to undo yet';
  const ao = $('[data-act="alloff"]');
  ao.disabled = !lightsOn;
  ao.title = lightsOn ? 'Turn off all ' + lightsOn + ' lights' : 'Every light is already off';
}
function renderAll(enter) { renderRooms(); renderPanel(enter); paintPlan(); renderSum(); }

/* ── actions ── */
function selectRoom(rid, toPanel) {
  if (!roomById[rid]) return;
  state.room = rid;
  renderRooms(); renderPanel(true); paintPlan();
  if (toPanel && root.clientWidth < 760) setView('panel');
}
function setView(v) {
  root.dataset.view = v;
  $$('[data-tab]').forEach((t) => t.setAttribute('aria-selected', String(t.dataset.tab === v)));
}
function toggleDev(id) {
  const d = byId(id), before = snapshot();
  d.on = !d.on;
  renderAll();
  commit(d.name + (d.on ? ' on' : ' off'), before);
  renderSum();
}
function applyScene(sid) {
  const r = roomById[state.room], before = snapshot(), ls = lightsOf(r.id);
  ls.forEach((d, i) => {
    if (sid === 'bright') Object.assign(d, { on: true, bri: 1, k: 4000 });
    if (sid === 'relax') Object.assign(d, { on: true, bri: 0.45, k: 2500 });
    if (sid === 'night') Object.assign(d, i === 0 ? { on: true, bri: 0.08, k: 2200 } : { on: false });
    if (sid === 'off') d.on = false;
  });
  if (sid === 'night') inRoom(r.id).filter((d) => d.type === 'blind').forEach((d) => { d.pos = 0; });
  renderAll();
  commit(SCENES.find((s) => s.id === sid).name + ' scene in ' + r.name, before);
  renderSum();
}
function roomLights() {
  const ls = lightsOf(state.room), before = snapshot();
  const any = ls.some((d) => d.on);
  ls.forEach((d) => { d.on = !any; });
  renderAll();
  commit(roomById[state.room].name + ' lights ' + (any ? 'off' : 'on'), before);
  renderSum();
}
function allOff() {
  const before = snapshot();
  const n = state.dev.filter((d) => d.type === 'light' && d.on).length;
  if (!n) return;
  state.dev.forEach((d) => { if (d.type === 'light') d.on = false; });
  renderAll();
  commit(n + ' lights turned off', before);
  renderSum();
}

root.addEventListener('click', (e) => {
  const t = e.target.closest('button, [data-room], [data-hit], [data-lamp]');
  if (!t || !root.contains(t)) return;
  if (t.dataset.room) return selectRoom(t.dataset.room, true);
  if (t.dataset.hit) return selectRoom(t.dataset.hit);
  if (t.dataset.lamp) return toggleDev(t.dataset.lamp);
  if (t.dataset.tab) return setView(t.dataset.tab);
  if (t.dataset.overlay) { state.overlay = t.dataset.overlay; paintPlan(); return; }
  const a = t.dataset.act, id = t.dataset.id;
  if (a === 'toggle') toggleDev(id);
  else if (a === 'scene') applyScene(t.dataset.scene);
  else if (a === 'undo' || a === 'undo-toast') { undo(); if (a === 'undo-toast') $('[data-toast]').hidden = true; }
  else if (a === 'alloff') allOff();
  else if (a === 'back') setView('rooms');
  else if (a === 'blind') {
    const d = byId(id), before = snapshot();
    d.pos = +t.dataset.to; renderAll();
    commit(d.name + (d.pos ? ' opened' : ' closed'), before); renderSum();
  } else if (a === 'play') {
    const d = byId(id), before = snapshot();
    d.on = !d.on; renderAll();
    commit(d.name + (d.on ? ' playing' : ' paused'), before); renderSum();
  } else if (a === 'next') {
    const d = byId(id), before = snapshot();
    d.track = (d.track + 1) % TRACKS.length; d.on = true; renderAll();
    commit('Now playing ' + TRACKS[d.track][0], before); renderSum();
  }
});

/* sliders patch the plan and labels live; one undo step per drag */
let dragBefore = null;
root.addEventListener('input', (e) => {
  const t = e.target;
  if (t.type !== 'range') return;
  if (!dragBefore) dragBefore = snapshot();
  const ds = t.dataset, v = +t.value;
  let d;
  if (ds.bri) { d = byId(ds.bri); d.bri = v / 100; $('[data-obri="' + d.id + '"]').textContent = v + '%'; }
  else if (ds.k) { d = byId(ds.k); d.k = v; $('[data-ok="' + d.id + '"]').textContent = v + ' K'; $('[data-card="' + d.id + '"]').style.setProperty('--glow', kColor(v)); }
  else if (ds.pos) { d = byId(ds.pos); d.pos = v / 100; $('[data-opos="' + d.id + '"]').textContent = v + '%'; }
  else if (ds.vol) { d = byId(ds.vol); d.vol = v / 100; $('[data-ovol="' + d.id + '"]').textContent = v + '%'; }
  if (!d) return;
  if (d.type === 'light') $('[data-sub="' + d.id + '"]').textContent = Math.round(d.bri * 100) + '% · ' + d.k + ' K · ' + fmtW(draw(d));
  if (d.type === 'blind') $('[data-sub="' + d.id + '"]').textContent = d.pos === 0 ? 'Closed' : d.pos === 1 ? 'Fully open' : 'Open ' + Math.round(d.pos * 100) + '%';
  paintPlan(); renderRooms(); renderSum();
});
root.addEventListener('change', (e) => {
  const t = e.target;
  if (t.type !== 'range' || !dragBefore) return;
  const d = byId(t.dataset.bri || t.dataset.k || t.dataset.pos || t.dataset.vol);
  const what = t.dataset.bri ? 'brightness ' + t.value + '%' : t.dataset.k ? 'warmth ' + t.value + ' K' : t.dataset.pos ? 'position ' + t.value + '%' : 'volume ' + t.value + '%';
  state.undo.push({ label: d.name + ' ' + what, dev: dragBefore });
  dragBefore = null;
  toast(d.name + ' set to ' + what, true);
  renderSum();
  /* refresh scene highlight without stealing the slider's focus */
  const m = sceneMatch(state.room);
  $$('[data-act="scene"]').forEach((b) => b.setAttribute('aria-pressed', String(b.dataset.scene === m)));
  if (d.type === 'blind') $$('[data-act="blind"][data-id="' + d.id + '"]').forEach((b) => {
    const dis = (+b.dataset.to) === d.pos;
    b.disabled = dis; if (dis) b.title = d.pos ? 'Already fully open' : 'Already closed'; else b.removeAttribute('title');
  });
});

/* keyboard: shortcuts on the root, arrows inside the room listbox */
root.addEventListener('keydown', (e) => {
  const tg = e.target;
  if (tg.matches('input:not([type=range]), textarea')) return;
  if (e.metaKey || e.ctrlKey) {
    if (e.key.toLowerCase() === 'z') { e.preventDefault(); undo(); }
    return;
  }
  if (e.altKey) return;
  const k = e.key;
  if ((k === 'ArrowDown' || k === 'ArrowUp') && tg.type !== 'range') {
    e.preventDefault();
    const i = ROOMS.findIndex((r) => r.id === state.room);
    const n = ROOMS[(i + (k === 'ArrowDown' ? 1 : -1) + ROOMS.length) % ROOMS.length];
    selectRoom(n.id);
    if (tg.closest('[data-rooms]')) $('[data-room="' + n.id + '"]').focus();
    return;
  }
  if (tg.type === 'range') return;
  if ((k === 'Enter' || k === ' ') && tg.dataset.room) { e.preventDefault(); selectRoom(tg.dataset.room, true); return; }
  if (k === 'l' || k === 'L') { e.preventDefault(); roomLights(); }
  else if (k >= '1' && k <= '4') { e.preventDefault(); applyScene(SCENES[+k - 1].id); }
  else if (k === 'c' || k === 'C') { state.overlay = state.overlay === 'climate' ? 'light' : 'climate'; paintPlan(); }
  else if (k === 'z' || k === 'Z') { e.preventDefault(); undo(); }
  else if (k === 'Escape') { $('[data-toast]').hidden = true; }
});

buildPlan();
renderAll(true);

css:
@property --asm-climate-lo { syntax: "<angle>"; inherits: true; initial-value: 0deg; }
@property --asm-climate-hi { syntax: "<angle>"; inherits: true; initial-value: 0deg; }
@property --asm-climate-a { syntax: "<angle>"; inherits: true; initial-value: 0deg; }
@property --asm-climate-mc { syntax: "<color>"; inherits: true; initial-value: oklch(0.72 0.17 45); }

.asm-climate {
  /* re-theme with these four */
  --asm-climate-bg: oklch(0.205 0.012 55);
  --asm-climate-ink: oklch(0.94 0.012 75);
  --asm-climate-heat: oklch(0.72 0.17 45);
  --asm-climate-cool: oklch(0.8 0.09 220);
  /* derived */
  --asm-climate-auto: color-mix(in oklch, var(--asm-climate-heat) 30%, oklch(0.78 0.12 150));
  --asm-climate-off: color-mix(in oklch, var(--asm-climate-ink) 40%, var(--asm-climate-bg));
  --asm-climate-panel: color-mix(in oklch, var(--asm-climate-ink) 4.5%, var(--asm-climate-bg));
  --asm-climate-raise: color-mix(in oklch, var(--asm-climate-ink) 8%, var(--asm-climate-bg));
  --asm-climate-line: color-mix(in oklch, var(--asm-climate-ink) 10%, transparent);
  --asm-climate-line2: color-mix(in oklch, var(--asm-climate-ink) 18%, transparent);
  --asm-climate-mute: color-mix(in oklch, var(--asm-climate-ink) 62%, var(--asm-climate-bg));
  --asm-climate-faint: color-mix(in oklch, var(--asm-climate-ink) 40%, var(--asm-climate-bg));
  --asm-climate-hover: color-mix(in oklch, var(--asm-climate-ink) 6%, transparent);
  --asm-climate-ease: cubic-bezier(.2, .8, .2, 1);
  --asm-climate-spring: linear(0, 0.1 4%, 0.4 10%, 0.76 17%, 0.98 24%, 1.07 30%, 1.08 36%, 1.04 45%, 1.006 56%, 0.996 70%, 1);
  --asm-climate-mc: var(--asm-climate-heat);
  --asm-climate-dial: clamp(200px, 27cqi, 262px);

  position: relative; width: 100%; height: var(--asm-climate-h, 680px); box-sizing: border-box;
  container-type: inline-size; container-name: asm-climate; overflow: clip; isolation: isolate;
  background: var(--asm-climate-bg); color: var(--asm-climate-ink); color-scheme: dark; border-radius: 16px;
  accent-color: var(--asm-climate-mc);
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  box-shadow: inset 0 0 0 1px var(--asm-climate-line);
  transition: --asm-climate-mc .7s var(--asm-climate-ease);

  &[data-mode="cool"] { --asm-climate-mc: var(--asm-climate-cool); }
  &[data-mode="auto"] { --asm-climate-mc: var(--asm-climate-auto); }
  &[data-mode="off"] { --asm-climate-mc: var(--asm-climate-off); }
  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--asm-climate-mc); outline-offset: 2px; }
  & button { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
  & button:disabled, & [aria-disabled="true"] { cursor: not-allowed; opacity: .4; }
  & h2, & p, & ul, & figure { margin: 0; padding: 0; }
  & ul { list-style: none; }
  & [hidden] { display: none !important; }
  & svg { fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { font: 600 10px/1 ui-monospace, Menlo, monospace; min-width: 17px; padding: 3px 4px; text-align: center; border-radius: 5px;
    color: var(--asm-climate-mute); background: var(--asm-climate-raise); box-shadow: inset 0 -1.5px 0 var(--asm-climate-line2); }
}

.asm-climate .asm-climate-app {
  height: 100%; display: grid;
  grid-template-columns: 214px minmax(0, .92fr) minmax(0, 1.08fr);
  grid-template-rows: auto minmax(0, 1fr) auto;
  grid-template-areas: "top top top" "zones main week" "keys keys keys";
}
.asm-climate .asm-climate-eyebrow { font-size: 10.5px; font-weight: 650; letter-spacing: .1em; text-transform: uppercase; color: var(--asm-climate-faint); }

/* top */
.asm-climate .asm-climate-top { grid-area: top; display: flex; align-items: center; gap: 14px; padding: 12px 16px; border-bottom: 1px solid var(--asm-climate-line); }
.asm-climate .asm-climate-brand {
  display: flex; align-items: center; gap: 10px;
  & > svg { width: 30px; height: 30px; padding: 6px; border-radius: 9px; color: var(--asm-climate-bg); background: var(--asm-climate-mc); stroke-width: 2; transition: background .6s; }
  & b { display: block; font-size: 14.5px; letter-spacing: -.01em; }
  & small { display: block; font-size: 11.5px; color: var(--asm-climate-mute); white-space: nowrap; }
}
.asm-climate .asm-climate-wx { margin-left: auto; font-size: 12.5px; color: var(--asm-climate-mute); font-variant-numeric: tabular-nums; display: flex; align-items: center; gap: 8px; white-space: nowrap;
  & svg { width: 18px; height: 18px; color: var(--asm-climate-cool); }
  & b { color: var(--asm-climate-ink); font-weight: 600; }
}
.asm-climate .asm-climate-tabs { display: none; }

/* zones */
.asm-climate .asm-climate-zones {
  grid-area: zones; min-height: 0; overflow: auto; padding: 16px 10px 14px 12px; border-right: 1px solid var(--asm-climate-line);
  display: flex; flex-direction: column; gap: 8px; scrollbar-width: thin;
  & > h2 { padding: 0 8px; }
  & ul { display: grid; gap: 4px; }
}
.asm-climate .asm-climate-zone {
  position: relative; display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 1px 8px; padding: 10px 11px; border-radius: 12px; cursor: pointer;
  transition: background .2s; outline-offset: -2px;
  & b { font-weight: 600; }
  & .c { grid-row: 1 / 3; grid-column: 2; align-self: center; font-size: 22px; font-weight: 300; letter-spacing: -.02em; font-variant-numeric: tabular-nums; }
  & .s { font-size: 11.5px; color: var(--asm-climate-mute); font-variant-numeric: tabular-nums; display: flex; align-items: center; gap: 5px; }
  & .s i { width: 6px; height: 6px; border-radius: 50%; background: var(--asm-climate-faint); }
  & .s i.is-heat { background: var(--asm-climate-heat); box-shadow: 0 0 8px var(--asm-climate-heat); }
  & .s i.is-cool { background: var(--asm-climate-cool); box-shadow: 0 0 8px var(--asm-climate-cool); }
  &:hover { background: var(--asm-climate-hover); }
  &[aria-selected="true"] { background: var(--asm-climate-raise); cursor: default; box-shadow: inset 0 0 0 1px var(--asm-climate-line); }
}
.asm-climate .asm-climate-pump {
  margin-top: auto; padding: 12px; border-radius: 12px; background: var(--asm-climate-panel); box-shadow: inset 0 0 0 1px var(--asm-climate-line);
  font-size: 12px; color: var(--asm-climate-mute); display: grid; gap: 6px; font-variant-numeric: tabular-nums;
  & b { color: var(--asm-climate-ink); font-weight: 600; }
  & .bar { height: 4px; border-radius: 4px; background: var(--asm-climate-line); overflow: hidden; }
  & .bar i { display: block; height: 100%; background: var(--asm-climate-mc); transform-origin: left; transition: transform .8s var(--asm-climate-ease), background .6s; }
}

/* main: dial */
.asm-climate .asm-climate-main {
  grid-area: main; min-height: 0; overflow: auto; padding: 16px 18px; display: flex; flex-direction: column; align-items: center; gap: 12px; scrollbar-width: thin;
}
.asm-climate .asm-climate-dialrow { display: flex; align-items: center; gap: clamp(8px, 2cqi, 22px); }
.asm-climate .asm-climate-step {
  width: 40px; height: 40px; border-radius: 50%; display: grid; place-items: center; background: var(--asm-climate-raise); box-shadow: inset 0 0 0 1px var(--asm-climate-line);
  transition: background .2s, transform .35s var(--asm-climate-spring);
  & svg { width: 18px; height: 18px; stroke-width: 2; }
  &:hover:not(:disabled) { background: color-mix(in oklch, var(--asm-climate-mc) 18%, var(--asm-climate-raise)); }
  &:active:not(:disabled) { transform: scale(.9); }
}
.asm-climate .asm-climate-dial {
  --t: 10px;
  position: relative; width: var(--asm-climate-dial); aspect-ratio: 1; border-radius: 50%; cursor: grab; touch-action: none; flex: none;
  transition: --asm-climate-lo .7s var(--asm-climate-spring), --asm-climate-hi .7s var(--asm-climate-spring), --asm-climate-a .7s var(--asm-climate-spring);
  &.is-drag { cursor: grabbing; transition: none; }
  &:focus-visible { outline-offset: 6px; border-radius: 50%; }
  & > * { position: absolute; border-radius: 50%; }
}
.asm-climate .asm-climate-glow {
  inset: 18%; background: var(--asm-climate-mc); filter: blur(34px); opacity: .22; transition: opacity .8s var(--asm-climate-ease);
}
.asm-climate[data-active="1"] .asm-climate-glow { animation: asm-climate-breathe 3.2s ease-in-out infinite; }
