  }
  .asm-climate .asm-climate-zones, .asm-climate .asm-climate-main, .asm-climate .asm-climate-week { grid-area: main; border: 0; }
  .asm-climate .asm-climate-zones { flex-direction: column; overflow: auto; padding: 12px;
    & > h2 { display: block; }
    & ul { display: grid; }
  }
  .asm-climate .asm-climate-zone { min-width: 0; }
  .asm-climate .asm-climate-pump { margin: 8px 0 0; }
  .asm-climate .asm-climate-main, .asm-climate .asm-climate-week { padding: 12px; }
