    toast('New ' + PNAME[np] + ' block from ' + hhmm(mid));
  } else if (a === 'copy') {
    const src = S().sched[state.day], tgt = state.day < 5 ? [0, 1, 2, 3, 4] : [5, 6];
    tgt.forEach((d) => { if (d !== state.day) S().sched[d] = src.map((b) => ({ s: b.s, p: b.p })); });
    scheduleChanged();
    toast('Copied ' + DAYL[state.day] + ' to ' + (state.day < 5 ? 'Monday – Friday' : 'the weekend'));
  }
});

/* dial: pointer */
function valFromPoint(e) {
  const r = dial.getBoundingClientRect(), dx = e.clientX - (r.left + r.width / 2), dy = e.clientY - (r.top + r.height / 2);
  let th = (Math.atan2(dx, -dy) * 180) / Math.PI; if (th < 0) th += 360;
  let off = (th - 225 + 360) % 360;
  if (off > 270) off = off > 315 ? 0 : 270;
  return { v: 10 + (off / 270) * 20, d: Math.hypot(dx, dy) / (r.width / 2) };
}
dial.addEventListener('pointerdown', (e) => {
  if (S().mode === 'off') { toast('Switch to Heat, Cool or Auto first'); return; }
  const p = valFromPoint(e);
  if (p.d < 0.62) return;
  dial.setPointerCapture(e.pointerId);
  dial.classList.add('is-drag');
  setTarget(p.v, true);
  const mv = (ev) => setTarget(valFromPoint(ev).v, true);
  const up = () => {
    dial.classList.remove('is-drag');
    dial.removeEventListener('pointermove', mv); dial.removeEventListener('pointerup', up); dial.removeEventListener('pointercancel', up);
    const s = S();
    toast(s.hold ? 'Holding ' + fmtT(s.hold.t) + '° until ' + hhmm(nextStart(s.sched[TODAY], state.now)) : 'Back on schedule');
  };
  dial.addEventListener('pointermove', mv); dial.addEventListener('pointerup', up); dial.addEventListener('pointercancel', up);
});

/* schedule handles: pointer drag patches widths in place, renders on release */
function patchBig(day) {
  const big = $('[data-big]');
  if (!big) return;
  day.forEach((b, i) => {
    const e = i + 1 < day.length ? day[i + 1].s : 1440, n = $('[data-blk="' + i + '"]', big);
    if (n) n.style.width = (((e - b.s) / 1440) * 100).toFixed(3) + '%';
    const h = $('[data-hdl="' + i + '"]', big);
    if (h) { h.style.left = ((b.s / 1440) * 100).toFixed(3) + '%'; h.firstChild.textContent = hhmm(b.s); h.setAttribute('aria-valuenow', b.s); h.setAttribute('aria-valuetext', hhmm(b.s)); }
  });
}
function moveHandle(i, m) {
  const day = S().sched[state.day];
  const lo = day[i - 1].s + 15, hi = (i + 1 < day.length ? day[i + 1].s : 1440) - 15;
  day[i].s = Math.max(lo, Math.min(hi, Math.round(m / 15) * 15));
}
root.addEventListener('pointerdown', (e) => {
  const h = e.target.closest('[data-hdl]');
  if (!h) return;
  e.preventDefault();
  const i = +h.dataset.hdl, big = $('[data-big]');
  h.setPointerCapture(e.pointerId); h.classList.add('is-drag');
  const day = S().sched[state.day];
  const mv = (ev) => { const r = big.getBoundingClientRect(); moveHandle(i, ((ev.clientX - r.left) / r.width) * 1440); patchBig(day); };
  const up = () => {
    h.removeEventListener('pointermove', mv); h.removeEventListener('pointerup', up); h.removeEventListener('pointercancel', up);
    scheduleChanged();
    toast(DAYL[state.day] + ': change now at ' + hhmm(day[i].s));
  };
  h.addEventListener('pointermove', mv); h.addEventListener('pointerup', up); h.addEventListener('pointercancel', up);
});

/* chart crosshair */
const plot = $('.asm-climate-plot');
plot.addEventListener('pointermove', (e) => {
  const P = renderChart.P; if (!P) return;
  const r = plot.getBoundingClientRect(), x = Math.max(0, Math.min(1, (e.clientX - r.left) / r.width));
  const p = P[Math.round(x * 144)];
  const hair = $('[data-hair]');
  hair.setAttribute('x1', ((p.m / 1440) * 600).toFixed(1)); hair.setAttribute('x2', ((p.m / 1440) * 600).toFixed(1));
  const tip = $('[data-tip]');
  tip.hidden = false;
  tip.style.left = Math.max(70, Math.min(r.width - 70, x * r.width)) + 'px';
  tip.textContent = hhmm(p.m) + (p.f && p.m > state.now ? ' forecast' : '') + '  in ' + fmtT(p.ins) + '°  set ' + fmtT(p.set) + '°  out ' + fmtT(p.o) + '°' + (p.open ? '  door open' : '');
});
plot.addEventListener('pointerleave', () => { $('[data-tip]').hidden = true; $('[data-hair]').setAttribute('x1', -10); $('[data-hair]').setAttribute('x2', -10); });

/* keyboard */
root.addEventListener('keydown', (e) => {
  const tg = e.target, k = e.key;
  if (e.metaKey || e.ctrlKey || e.altKey) return;
  if (tg === dial) {
    const t = target(state.zone), step = { ArrowUp: 0.5, ArrowRight: 0.5, ArrowDown: -0.5, ArrowLeft: -0.5, PageUp: 2, PageDown: -2 }[k];
    if (step) { e.preventDefault(); setTarget(t + step); return; }
    if (k === 'Home') { e.preventDefault(); setTarget(10); return; }
    if (k === 'End') { e.preventDefault(); setTarget(30); return; }
  }
  if (tg.dataset.hdl) {
    if (k === 'ArrowLeft' || k === 'ArrowRight') {
      e.preventDefault();
      const i = +tg.dataset.hdl, day = S().sched[state.day];
      moveHandle(i, day[i].s + (k === 'ArrowRight' ? 15 : -15) * (e.shiftKey ? 4 : 1));
      scheduleChanged();
      const n = $('[data-hdl="' + i + '"]'); if (n) n.focus();
      return;
    }
  }
  const list = tg.closest('[role=listbox], [role=radiogroup]');
  if (list && /^Arrow/.test(k)) {
    const items = $$('[role=option], [role=radio]', list), i = items.indexOf(tg.closest('[role=option], [role=radio]'));
    if (i > -1) {
      e.preventDefault();
      const n = items[(i + (k === 'ArrowDown' || k === 'ArrowRight' ? 1 : -1) + items.length) % items.length];
      n.click(); const again = $$('[role=option], [role=radio]', tg.closest('[role=listbox], [role=radiogroup]') || list)[items.indexOf(n)];
      const f = root.contains(n) ? n : again; if (f) f.focus();
      return;
    }
  }
  if ((k === 'Enter' || k === ' ') && tg.matches('[role=option]')) { e.preventDefault(); tg.click(); return; }
  if (tg.matches('input, textarea')) return;
  if (k === 'ArrowUp' || k === 'ArrowDown') { e.preventDefault(); setTarget(target(state.zone) + (k === 'ArrowUp' ? 0.5 : -0.5)); }
  else if (k === 'ArrowLeft' || k === 'ArrowRight') { e.preventDefault(); state.day = (state.day + (k === 'ArrowRight' ? 1 : 6)) % 7; state.blk = -1; renderWeek(); }
  else if (/^[hcao]$/i.test(k)) setMode({ h: 'heat', c: 'cool', a: 'auto', o: 'off' }[k.toLowerCase()]);
  else if (k === 'r' || k === 'R') { if (S().hold) { S().hold = null; renderDial(); renderZones(); toast('Back on schedule · ' + fmtT(target(state.zone)) + '°'); } }
});

/* live simulation: one simulated minute every 3 s, paused when hidden or off screen */
let visible = true;
const io = new IntersectionObserver((en) => { visible = en[0].isIntersecting; });
io.observe(root);
const timer = setInterval(() => {
  if (!root.isConnected) { clearInterval(timer); io.disconnect(); return; }
  if (!visible || document.hidden) return;
  state.now = Math.min(1439, state.now + 1);
  ZONES.forEach((z) => {
    const s = state.z[z.id];
    if (s.hold && state.now >= s.hold.until) s.hold = null;
    const r = physics(s.cur, target(z.id), s.mode, outdoor(state.now), false, 1);
    s.cur = r.ins; s.run += r.heat;
    if (state.now % 10 === 0) s.hist.push({ m: state.now, ins: s.cur, set: target(z.id), o: outdoor(state.now), open: false });
  });
  renderZones(); renderDial(); renderWx();
  if (state.now % 10 === 0) renderChart();
}, 3000);

renderAll();

css:
.asm-routines {
  /* re-theme with these four */
  --asm-routines-paper: oklch(0.972 0.005 240);
  --asm-routines-ink: oklch(0.235 0.014 255);
  --asm-routines-accent: oklch(0.62 0.2 33);
  --asm-routines-card: oklch(0.996 0.002 240);
  /* derived */
  --asm-routines-side: color-mix(in oklab, var(--asm-routines-ink) 3.5%, var(--asm-routines-paper));
  --asm-routines-line: color-mix(in oklab, var(--asm-routines-ink) 10%, transparent);
  --asm-routines-line2: color-mix(in oklab, var(--asm-routines-ink) 18%, transparent);
  --asm-routines-mute: color-mix(in oklab, var(--asm-routines-ink) 60%, var(--asm-routines-paper));
  --asm-routines-faint: color-mix(in oklab, var(--asm-routines-ink) 40%, var(--asm-routines-paper));
  --asm-routines-hover: color-mix(in oklab, var(--asm-routines-ink) 5%, transparent);
  --asm-routines-tint: color-mix(in oklab, var(--asm-routines-accent) 10%, var(--asm-routines-card));
  --asm-routines-deep: color-mix(in oklab, var(--asm-routines-accent) 78%, var(--asm-routines-ink));
  --asm-routines-ok: oklch(0.6 0.13 150);
  --asm-routines-c-security: oklch(0.52 0.08 250);
  --asm-routines-c-comfort: oklch(0.7 0.13 70);
  --asm-routines-c-energy: oklch(0.62 0.13 150);
  --asm-routines-ease: cubic-bezier(.2, .8, .2, 1);
  --asm-routines-spring: linear(0, 0.12 4%, 0.42 10%, 0.78 17%, 0.98 24%, 1.06 30%, 1.07 36%, 1.035 45%, 1.005 56%, 0.997 70%, 1);

  position: relative; width: 100%; height: var(--asm-routines-h, 680px); box-sizing: border-box;
  container-type: inline-size; container-name: asm-routines; overflow: clip; isolation: isolate;
  background: var(--asm-routines-paper); color: var(--asm-routines-ink); color-scheme: light; border-radius: 16px;
  accent-color: var(--asm-routines-accent);
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  box-shadow: inset 0 0 0 1px var(--asm-routines-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--asm-routines-accent); outline-offset: 2px; }
  & button, & input { font: inherit; color: inherit; }
  & button { background: none; border: 0; padding: 0; cursor: pointer; }
  & button:disabled { cursor: not-allowed; opacity: .42; }
  & h2, & h3, & p, & ul, & ol, & figure, & blockquote { margin: 0; padding: 0; }
  & ul, & ol { list-style: none; }
  & [hidden] { display: none !important; }
  & svg { fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; flex: none; width: 16px; height: 16px; }
  & kbd { font: 600 10px/1 ui-monospace, Menlo, monospace; min-width: 17px; padding: 3px 4px; text-align: center; border-radius: 5px;
    color: var(--asm-routines-mute); background: var(--asm-routines-card); box-shadow: inset 0 0 0 1px var(--asm-routines-line2), inset 0 -1.5px 0 var(--asm-routines-line2); }
}
.asm-routines .asm-routines-app {
  height: 100%; display: grid;
  grid-template-columns: 286px minmax(0, 1fr) 290px;
  grid-template-rows: auto minmax(0, 1fr) auto;
  grid-template-areas: "top top top" "list editor side" "keys keys keys";
}
.asm-routines .asm-routines-eyebrow { font-size: 10.5px; font-weight: 650; letter-spacing: .1em; text-transform: uppercase; color: var(--asm-routines-faint); }

/* top */
.asm-routines .asm-routines-top { grid-area: top; display: flex; align-items: center; gap: 10px; padding: 12px 16px; border-bottom: 1px solid var(--asm-routines-line); }
.asm-routines .asm-routines-brand {
  display: flex; align-items: center; gap: 10px; margin-right: auto;
