}
.asm-routines .asm-routines-tabs { display: none; }
.asm-routines .asm-routines-btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 7px; height: 32px; padding: 0 12px; border-radius: 9px; font-weight: 580; white-space: nowrap;
