  transition: background .2s; outline-offset: -2px;
  & .ci { width: 30px; height: 30px; border-radius: 9px; display: grid; place-items: center; background: color-mix(in oklab, var(--c) 15%, var(--asm-routines-card)); color: color-mix(in oklab, var(--c) 80%, var(--asm-routines-ink)); }
