    state.trace = null;
    renderAll();
    commit('Removed “' + (k === 'c' ? condText(gone) : actText(gone)) + '”', before); renderUndo();
    return;
  }
  const a = t.dataset.act;
  if (a === 'new') newRule();
  else if (a === 'undo' || a === 'undo-toast') { undo(); renderUndo(); if (a === 'undo-toast') $('[data-toast]').hidden = true; }
  else if (a === 'test') runTest();
  else if (a === 'clearq') { state.q = ''; $('[data-q]').value = ''; renderList(); $('[data-q]').focus(); }
  else if (a === 'dup') {
    const r = cur(), before = snap(), id = 'r' + (++seq);
    const c = JSON.parse(JSON.stringify(r));
    Object.assign(c, { id: id, name: (r.name + ' copy').slice(0, 40), on: false, last: 'Never run', log: [] });
    rules.splice(rules.indexOf(r) + 1, 0, c);
    state.sel = id; state.trace = null;
    renderAll();
    commit('Duplicated ' + r.name, before); renderUndo(); revealSel();
  } else if (a === 'del') {
    const r = cur(), before = snap(), i = rules.indexOf(r);
    rules.splice(i, 1);
    const vis = visibleRules();
    state.sel = (vis[Math.min(i, vis.length - 1)] || rules[0] || {}).id;
    state.trace = null;
    renderAll();
    commit('Deleted ' + r.name, before); renderUndo();
  }
});

let nameBefore = null;
root.addEventListener('focusin', (e) => { if (e.target.matches('[data-name]')) nameBefore = snap(); });
root.addEventListener('input', (e) => {
  if (e.target.matches('[data-q]')) { state.q = e.target.value; renderList(); return; }
  if (e.target.matches('[data-name]')) {
    const r = cur(); r.name = e.target.value || 'Untitled routine';
    const row = $('[data-rule="' + r.id + '"] b'); if (row) row.textContent = r.name;
  }
});
root.addEventListener('change', (e) => {
  if (!e.target.matches('[data-name]') || !nameBefore) return;
  const old = nameBefore.rules.find((x) => x.id === state.sel);
  if (old && old.name !== cur().name) { commit('Renamed to ' + cur().name, nameBefore); renderUndo(); }
  nameBefore = null;
});

root.addEventListener('keydown', (e) => {
  const tg = e.target, k = e.key;
  if ((e.metaKey || e.ctrlKey) && k.toLowerCase() === 'z' && !tg.matches('input')) { e.preventDefault(); undo(); renderUndo(); return; }
  if (tg.matches('[data-name]') && k === 'Enter') { e.preventDefault(); tg.blur(); return; }
  if (tg.matches('[data-q]') && k === 'Escape') { tg.value = ''; state.q = ''; renderList(); return; }
  if (tg.matches('input, textarea')) return;
  if (k === 'Escape') { if (!menu.hidden) closeMenu(true); else $('[data-toast]').hidden = true; return; }
  const grp = tg.closest('[role=radiogroup]');
  if (grp && /^Arrow/.test(k)) {
    const it = $$('[role=radio]', grp), i = it.indexOf(tg);
    e.preventDefault();
    const n = it[(i + (k === 'ArrowRight' || k === 'ArrowDown' ? 1 : -1) + it.length) % it.length];
    const attr = Object.keys(n.dataset)[0], val = n.dataset[attr];
    n.click();
    const f = $('[data-' + attr.replace(/[A-Z]/g, (m) => '-' + m.toLowerCase()) + '="' + val + '"]'); if (f) f.focus();
    return;
  }
  if (tg.dataset.rule && (k === 'ArrowDown' || k === 'ArrowUp')) {
    e.preventDefault();
    const rows = $$('[data-rule]'), i = rows.indexOf(tg), n = rows[(i + (k === 'ArrowDown' ? 1 : -1) + rows.length) % rows.length];
    select(n.dataset.rule); $('[data-rule="' + n.dataset.rule + '"]').focus();
    return;
  }
  if (tg.dataset.rule && (k === 'Enter' || k === ' ')) { e.preventDefault(); select(tg.dataset.rule, true); return; }
  if (tg.dataset.tok && (k === 'ArrowDown')) { e.preventDefault(); openMenu(tg); return; }
  if (e.metaKey || e.ctrlKey || e.altKey) return;
  if (k === '/') { e.preventDefault(); if (root.clientWidth < 760) setView('list'); $('[data-q]').focus(); }
  else if (k === 'n' || k === 'N') { e.preventDefault(); newRule(); }
  else if (k === 't' || k === 'T') { e.preventDefault(); runTest(); }
  else if (k === 'e' || k === 'E') { e.preventDefault(); if (cur()) toggleRule(cur().id); }
});

renderAll();

css:
.asm-watch {
  /* re-theme with these four */
  --asm-watch-bg: oklch(0.175 0.004 250);
  --asm-watch-ink: oklch(0.93 0.006 95);
  --asm-watch-alert: oklch(0.8 0.15 72);
  --asm-watch-arm: oklch(0.64 0.2 27);
  /* derived */
  --asm-watch-ok: oklch(0.74 0.14 152);
  --asm-watch-panel: color-mix(in oklab, var(--asm-watch-ink) 4%, var(--asm-watch-bg));
  --asm-watch-raise: color-mix(in oklab, var(--asm-watch-ink) 8%, var(--asm-watch-bg));
  --asm-watch-line: color-mix(in oklab, var(--asm-watch-ink) 10%, transparent);
  --asm-watch-line2: color-mix(in oklab, var(--asm-watch-ink) 18%, transparent);
  --asm-watch-mute: color-mix(in oklab, var(--asm-watch-ink) 60%, var(--asm-watch-bg));
  --asm-watch-faint: color-mix(in oklab, var(--asm-watch-ink) 38%, var(--asm-watch-bg));
  --asm-watch-hover: color-mix(in oklab, var(--asm-watch-ink) 6%, transparent);
  --asm-watch-ease: cubic-bezier(.2, .8, .2, 1);
  --asm-watch-spring: linear(0, 0.12 4%, 0.42 10%, 0.78 17%, 0.98 24%, 1.06 30%, 1.07 36%, 1.035 45%, 1.005 56%, 0.997 70%, 1);
  --asm-watch-c-person: var(--asm-watch-alert);
  --asm-watch-c-vehicle: oklch(0.74 0.09 230);
  --asm-watch-c-animal: oklch(0.74 0.13 140);
  --asm-watch-c-package: oklch(0.72 0.12 45);

  position: relative; width: 100%; height: var(--asm-watch-h, 680px); box-sizing: border-box;
  container-type: inline-size; container-name: asm-watch; overflow: clip; isolation: isolate;
  background: var(--asm-watch-bg); color: var(--asm-watch-ink); color-scheme: dark; border-radius: 16px;
  accent-color: var(--asm-watch-alert);
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  box-shadow: inset 0 0 0 1px var(--asm-watch-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--asm-watch-alert); outline-offset: 2px; }
  & button { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
  & button:disabled { cursor: not-allowed; opacity: .4; }
  & h2, & p, & ul { margin: 0; padding: 0; }
  & ul { list-style: none; }
  & [hidden] { display: none !important; }
  & svg { fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; flex: none; width: 16px; height: 16px; }
  & kbd { font: 600 10px/1 ui-monospace, Menlo, monospace; min-width: 16px; padding: 3px 4px; text-align: center; border-radius: 5px; color: var(--asm-watch-mute); background: var(--asm-watch-raise); box-shadow: inset 0 -1.5px 0 var(--asm-watch-line2); }
  &[data-arm="off"] { --asm-watch-st: var(--asm-watch-faint); }
  &[data-arm="home"] { --asm-watch-st: var(--asm-watch-ok); }
  &[data-arm="night"] { --asm-watch-st: var(--asm-watch-alert); }
  &[data-arm="away"] { --asm-watch-st: var(--asm-watch-arm); }
  &[data-arm="arming"] { --asm-watch-st: var(--asm-watch-alert); }
}
.asm-watch .asm-watch-app {
  height: 100%; display: grid;
  grid-template-columns: minmax(0, 1fr) 308px;
  grid-template-rows: auto minmax(0, 1fr) auto;
  grid-template-areas: "top top" "main side" "keys keys";
}
.asm-watch .asm-watch-h { font-size: 10.5px; font-weight: 650; letter-spacing: .1em; text-transform: uppercase; color: var(--asm-watch-faint); }

/* top */
.asm-watch .asm-watch-top { grid-area: top; display: flex; align-items: center; gap: 14px; padding: 11px 16px; border-bottom: 1px solid var(--asm-watch-line); }
.asm-watch .asm-watch-brand {
  display: flex; align-items: center; gap: 10px;
  & > svg { width: 30px; height: 30px; padding: 6px; border-radius: 9px; background: var(--asm-watch-st); color: var(--asm-watch-bg); stroke-width: 2; transition: background .5s; }
  & b { display: block; font-size: 14.5px; letter-spacing: -.01em; }
  & small { display: block; font-size: 11.5px; color: var(--asm-watch-mute); white-space: nowrap; }
}
.asm-watch .asm-watch-arm {
  display: inline-flex; padding: 3px; border-radius: 10px; background: var(--asm-watch-panel); box-shadow: inset 0 0 0 1px var(--asm-watch-line); margin-left: auto;
  & button { height: 28px; padding: 0 12px; border-radius: 7px; font-size: 12.5px; font-weight: 580; color: var(--asm-watch-mute); transition: background .25s, color .25s; }
  & button:hover { color: var(--asm-watch-ink); }
  & button[aria-checked="true"] { background: color-mix(in oklab, var(--asm-watch-st) 22%, var(--asm-watch-raise)); color: var(--asm-watch-ink); box-shadow: inset 0 0 0 1px color-mix(in oklab, var(--asm-watch-st) 50%, transparent); cursor: default; }
  & button[aria-busy="true"] { color: var(--asm-watch-alert); animation: asm-watch-blink 1s steps(2) infinite; }
}
.asm-watch .asm-watch-status {
  display: flex; align-items: center; gap: 8px; font-size: 12.5px; color: var(--asm-watch-mute); font-variant-numeric: tabular-nums; white-space: nowrap;
  & i { width: 8px; height: 8px; border-radius: 50%; background: var(--asm-watch-st); box-shadow: 0 0 0 3px color-mix(in oklab, var(--asm-watch-st) 25%, transparent); }
  & b { color: var(--asm-watch-ink); }
}
.asm-watch[data-arm="arming"] .asm-watch-status i { animation: asm-watch-blink 1s steps(2) infinite; }
.asm-watch .asm-watch-tabs { display: none; }
.asm-watch .asm-watch-link { font-size: 12px; font-weight: 600; color: var(--asm-watch-alert); padding: 2px 4px; border-radius: 5px; }
.asm-watch .asm-watch-link:hover:not(:disabled) { background: var(--asm-watch-hover); }

/* main */
.asm-watch .asm-watch-main {
  grid-area: main; min-width: 0; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr) auto auto; gap: 10px; padding: 12px 14px 12px 16px;
}
.asm-watch .asm-watch-bar { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.asm-watch .asm-watch-tools { display: flex; gap: 6px; }
.asm-watch .asm-watch-chip {
  display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 10px; border-radius: 8px; font-size: 12px; font-weight: 580; white-space: nowrap;
  background: var(--asm-watch-raise); box-shadow: inset 0 0 0 1px var(--asm-watch-line2); transition: background .2s, color .2s;
  & svg { width: 14px; height: 14px; }
  &:hover { background: color-mix(in oklab, var(--asm-watch-ink) 12%, var(--asm-watch-bg)); }
  &[aria-pressed="true"] { color: var(--asm-watch-alert); box-shadow: inset 0 0 0 1px color-mix(in oklab, var(--asm-watch-alert) 60%, transparent); }
  &.is-live { color: var(--asm-watch-bg); background: var(--asm-watch-ink); box-shadow: none; }
  &.is-live kbd { background: color-mix(in oklab, var(--asm-watch-bg) 14%, transparent); color: var(--asm-watch-bg); box-shadow: none; }
}
.asm-watch .asm-watch-stage {
  min-height: 0; display: grid; gap: 8px; grid-template-columns: repeat(2, minmax(0, 1fr)); grid-template-rows: repeat(2, minmax(0, 1fr)); grid-auto-flow: dense;
}
.asm-watch[data-layout="focus"] .asm-watch-stage { grid-template-columns: minmax(0, 1fr) 23%; grid-template-rows: repeat(3, minmax(0, 1fr)); }
.asm-watch .asm-watch-tile {
  position: relative; min-width: 0; min-height: 0; border-radius: 10px; overflow: hidden; background: black; text-align: left;
  box-shadow: 0 0 0 1px var(--asm-watch-line); transition: box-shadow .25s; isolation: isolate;
  & canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }
  & > span { position: absolute; z-index: 1; pointer-events: none; }
  & .nm { left: 8px; top: 7px; display: inline-flex; align-items: center; gap: 6px; font-size: 12px; font-weight: 620; text-shadow: 0 1px 3px black; }
  & .nm kbd { background: rgba(0, 0, 0, .45); box-shadow: none; color: rgba(255, 255, 255, .7); }
  & .rec { right: 8px; top: 8px; display: inline-flex; align-items: center; gap: 5px; padding: 2px 6px; border-radius: 5px; background: rgba(0, 0, 0, .5); font: 650 9.5px/1.4 ui-monospace, Menlo, monospace; letter-spacing: .08em; }
  & .rec i { width: 6px; height: 6px; border-radius: 50%; background: var(--asm-watch-arm); animation: asm-watch-blink 1.6s steps(2) infinite; }
  & .ts { left: 8px; bottom: 7px; font: 500 10.5px ui-monospace, Menlo, monospace; color: rgba(255, 255, 255, .82); text-shadow: 0 1px 2px black; font-variant-numeric: tabular-nums; }
  & .det { right: 8px; bottom: 7px; padding: 2px 7px; border-radius: 5px; background: var(--asm-watch-alert); color: oklch(0.2 0.02 70); font-size: 11px; font-weight: 700; animation: asm-watch-pop .3s var(--asm-watch-spring); }
  & .zm { left: 50%; top: 8px; translate: -50% 0; padding: 2px 7px; border-radius: 5px; background: rgba(0, 0, 0, .55); font: 600 10px ui-monospace, Menlo, monospace; }
  &:hover { box-shadow: 0 0 0 1px var(--asm-watch-line2); }
  &:focus-visible { outline-offset: -2px; }
  &.is-focus { grid-column: 1; grid-row: 1 / -1; }
}
.asm-watch[data-mode="replay"] .asm-watch-tile .rec i, .asm-watch[data-mode="scrub"] .asm-watch-tile .rec i { background: var(--asm-watch-alert); animation: none; }
.asm-watch[data-layout="focus"] .asm-watch-tile:not(.is-focus) {
  & .nm { font-size: 11px; }
  & .ts, & .nm kbd { display: none; }
}
.asm-watch .asm-watch-replay {
  display: grid; grid-template-columns: auto minmax(0, 1fr) 110px auto auto; align-items: center; gap: 10px; padding: 8px 8px 8px 10px; border-radius: 11px;
  background: color-mix(in oklab, var(--asm-watch-alert) 9%, var(--asm-watch-panel)); box-shadow: inset 0 0 0 1px color-mix(in oklab, var(--asm-watch-alert) 28%, transparent);
  animation: asm-watch-pop .35s var(--asm-watch-ease);
  & .ti { width: 28px; height: 28px; border-radius: 8px; display: grid; place-items: center; background: color-mix(in oklab, var(--asm-watch-alert) 22%, transparent); color: var(--asm-watch-alert); }
  & .tx { min-width: 0; }
  & b { display: block; font-size: 12.5px; font-weight: 620; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  & small { display: block; font-size: 11.5px; color: var(--asm-watch-mute); font-variant-numeric: tabular-nums; }
  & .pg { height: 4px; border-radius: 4px; background: var(--asm-watch-line2); overflow: hidden; }
  & .pg i { display: block; height: 100%; background: var(--asm-watch-alert); transform-origin: left; transform: scaleX(0); }
}
.asm-watch[data-mode="scrub"] .asm-watch-replay { grid-template-columns: auto minmax(0, 1fr) auto; }
.asm-watch .asm-watch-line { display: grid; gap: 3px; }
.asm-watch .asm-watch-hours { display: flex; justify-content: space-between; font: 500 10px ui-monospace, Menlo, monospace; color: var(--asm-watch-faint); }
.asm-watch .asm-watch-track {
  position: relative; height: 30px; border-radius: 8px; cursor: ew-resize; touch-action: none;
  & .asm-watch-day { position: absolute; inset: 0; border-radius: 8px; overflow: hidden;
    background:
      repeating-linear-gradient(135deg, transparent 0 3px, var(--asm-watch-line2) 3px 5px) right / 5.5% 100% no-repeat,
      linear-gradient(90deg, color-mix(in oklab, var(--asm-watch-ink) 3%, var(--asm-watch-bg)) 0 29%, color-mix(in oklab, var(--asm-watch-alert) 14%, var(--asm-watch-raise)) 33.5% 77%, color-mix(in oklab, var(--asm-watch-ink) 3%, var(--asm-watch-bg)) 81.5%);
    box-shadow: inset 0 0 0 1px var(--asm-watch-line); }
  & .asm-watch-marks { position: absolute; inset: 0; }
  &:focus-visible { outline-offset: 3px; }
}
.asm-watch .asm-watch-mark {
  position: absolute; top: 4px; bottom: 4px; width: 6px; margin-left: -3px; border-radius: 3px; background: var(--c, var(--asm-watch-alert));
  transition: transform .3s var(--asm-watch-spring), box-shadow .2s; cursor: pointer;
  &[data-type="person"] { --c: var(--asm-watch-c-person); }
  &[data-type="vehicle"] { --c: var(--asm-watch-c-vehicle); }
  &[data-type="animal"] { --c: var(--asm-watch-c-animal); }
  &[data-type="package"] { --c: var(--asm-watch-c-package); }
  &:hover { transform: scaleY(1.25); }
  &[aria-pressed="true"] { box-shadow: 0 0 0 2px var(--asm-watch-bg), 0 0 0 3.5px var(--c); }
}
.asm-watch .asm-watch-head {
  position: absolute; top: -3px; bottom: -3px; width: 2px; margin-left: -1px; background: var(--asm-watch-ink); border-radius: 2px; pointer-events: none; z-index: 2;
  & span { position: absolute; bottom: calc(100% + 3px); left: 50%; translate: -50% 0; padding: 1px 5px; border-radius: 4px; background: var(--asm-watch-ink); color: var(--asm-watch-bg); font: 650 10px ui-monospace, Menlo, monospace; white-space: nowrap; font-variant-numeric: tabular-nums; }
}
.asm-watch[data-mode="live"] .asm-watch-head span { background: var(--asm-watch-arm); color: white; }

/* side */
.asm-watch .asm-watch-side {
  grid-area: side; min-height: 0; overflow: auto; padding: 14px 14px 16px; border-left: 1px solid var(--asm-watch-line); background: var(--asm-watch-panel);
  display: flex; flex-direction: column; gap: 10px; scrollbar-width: thin;
}
.asm-watch .asm-watch-sidehead { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.asm-watch .asm-watch-filters {
  display: flex; flex-wrap: wrap; gap: 4px;
  & button { height: 24px; padding: 0 8px; border-radius: 7px; font-size: 11.5px; font-weight: 560; color: var(--asm-watch-mute); box-shadow: inset 0 0 0 1px var(--asm-watch-line); }
  & button span { opacity: .7; font-variant-numeric: tabular-nums; }
  & button:hover { color: var(--asm-watch-ink); }
  & button[aria-checked="true"] { background: var(--asm-watch-ink); color: var(--asm-watch-bg); box-shadow: none; cursor: default; }
}
.asm-watch .asm-watch-events { display: grid; gap: 2px; }
.asm-watch .asm-watch-ev {
  position: relative; display: grid; grid-template-columns: 28px minmax(0, 1fr) auto; align-items: center; gap: 9px; padding: 8px 8px 8px 9px; border-radius: 10px; cursor: pointer;
  transition: background .2s; outline-offset: -2px; animation: asm-watch-in .35s var(--asm-watch-ease) both; animation-delay: calc(var(--i) * 28ms);
  & .ti { width: 28px; height: 28px; border-radius: 8px; display: grid; place-items: center; color: var(--c); background: color-mix(in oklab, var(--c) 16%, transparent); }
  & .ti svg { width: 15px; height: 15px; }
  & .tx { min-width: 0; }
  & b { display: block; font-size: 12.5px; font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  & small { display: block; font-size: 11.5px; color: var(--asm-watch-mute); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  & .tm { text-align: right; font-variant-numeric: tabular-nums; }
  & .tm b { font: 600 12px ui-monospace, Menlo, monospace; }
  &.is-new::after { content: ""; position: absolute; left: 3px; top: 50%; width: 5px; height: 5px; margin-top: -2.5px; border-radius: 50%; background: var(--asm-watch-alert); }
  &:hover { background: var(--asm-watch-hover); }
  &[aria-selected="true"] { background: var(--asm-watch-raise); box-shadow: inset 0 0 0 1px var(--asm-watch-line2); cursor: default; }
  &[data-type="person"] { --c: var(--asm-watch-c-person); }
  &[data-type="vehicle"] { --c: var(--asm-watch-c-vehicle); }
  &[data-type="animal"] { --c: var(--asm-watch-c-animal); }
  &[data-type="package"] { --c: var(--asm-watch-c-package); }
}
.asm-watch .asm-watch-sensh { margin-top: 6px; }
.asm-watch .asm-watch-sensors { display: grid; gap: 2px; }
.asm-watch .asm-watch-sen {
  display: grid; grid-template-columns: 28px minmax(0, 1fr) auto; align-items: center; gap: 9px; padding: 7px 4px 7px 9px; border-radius: 10px;
  & .ti { width: 28px; height: 28px; border-radius: 8px; display: grid; place-items: center; color: var(--asm-watch-mute); background: var(--asm-watch-raise); }
  & .ti svg { width: 15px; height: 15px; }
  & b { display: block; font-size: 12.5px; font-weight: 600; }
  & small { display: block; font-size: 11.5px; color: var(--asm-watch-mute); font-variant-numeric: tabular-nums; }
  &.is-warn .ti { color: var(--asm-watch-alert); background: color-mix(in oklab, var(--asm-watch-alert) 18%, transparent); }
  &.is-warn small { color: var(--asm-watch-alert); }
}
.asm-watch .asm-watch-mini {
  height: 26px; padding: 0 10px; border-radius: 7px; font-size: 11.5px; font-weight: 600; background: var(--asm-watch-raise); box-shadow: inset 0 0 0 1px var(--asm-watch-line2); transition: background .2s;
  &:hover:not(:disabled) { background: color-mix(in oklab, var(--asm-watch-ink) 13%, var(--asm-watch-bg)); }
  &.is-warn { background: var(--asm-watch-alert); color: oklch(0.2 0.02 70); box-shadow: none; }
}

/* footer, pad, toast */
.asm-watch .asm-watch-keys {
  grid-area: keys; display: flex; flex-wrap: wrap; gap: 4px 16px; padding: 8px 16px; border-top: 1px solid var(--asm-watch-line); font-size: 11.5px; color: var(--asm-watch-mute);
  & span { display: inline-flex; align-items: center; gap: 4px; }
}
.asm-watch .asm-watch-pad {
  position: absolute; inset: 0; z-index: 8; display: grid; place-items: center; background: color-mix(in oklab, var(--asm-watch-bg) 70%, transparent);
  backdrop-filter: blur(6px); transition: opacity .25s; @starting-style { opacity: 0; }
