  ra.textContent = n ? 'Mark ' + n + ' reviewed' : 'All reviewed';
  renderTabs();
}
function renderTabs() {
  const n = EVENTS.filter((e) => !e.seen).length;
  $('[data-newcount]').textContent = n ? ' · ' + n + ' new' : '';
}
function renderSensors() {
  const g = state.garage, moving = Math.abs(state.garage - state.garageTo) > 0.001;
  const row = (icon, name, val, warn, btn) => '<li class="asm-watch-sen' + (warn ? ' is-warn' : '') + '"><span class="ti">' + ic(icon) + '</span><span class="tx"><b>' + name + '</b><small>' + val + '</small></span>' + (btn || '') + '</li>';
  $('[data-sensors]').innerHTML =
    row('<rect x="6" y="3" width="12" height="18" rx="1"/><circle cx="15" cy="12" r=".8"/>', 'Front door', 'Closed · ' + (state.sensors.front ? 'locked' : 'unlocked'), !state.sensors.front,
      '<button type="button" class="asm-watch-mini" data-act="lock" data-lock="front">' + (state.sensors.front ? 'Unlock' : 'Lock') + '</button>') +
    row('<rect x="6" y="3" width="12" height="18" rx="1"/><circle cx="15" cy="12" r=".8"/>', 'Back door', 'Closed · ' + (state.sensors.back ? 'locked' : 'unlocked'), !state.sensors.back,
      '<button type="button" class="asm-watch-mini" data-act="lock" data-lock="back">' + (state.sensors.back ? 'Unlock' : 'Lock') + '</button>') +
    row('<path d="M3.5 10 12 4l8.5 6v10h-17Z"/><path d="M7 20v-7h10v7M7 15.5h10"/>', 'Garage door', '<span data-gpct>' + (moving ? (state.garageTo ? 'Opening ' : 'Closing ') + Math.round(g * 100) + '%' : g ? 'Open since 19:03' : 'Closed') + '</span>', g > 0 && !moving,
      '<button type="button" class="asm-watch-mini' + (g && !moving ? ' is-warn' : '') + '" data-act="garage"' + (moving ? ' disabled title="The door is moving"' : '') + '>' + (state.garageTo ? 'Close' : 'Open') + '</button>') +
    row('<rect x="4" y="4" width="16" height="16" rx="1.5"/><path d="M12 4v16M4 12h16"/>', 'Windows', '11 of 12 closed · bathroom tilted', false, '') +
    row('<circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="3"/>', 'Smoke and CO', state.smoke === 'run' ? 'Testing sirens…' : state.smoke === 'done' ? 'All clear · tested just now' : 'All clear · tested 1 Sep', false,
      '<button type="button" class="asm-watch-mini" data-act="smoke"' + (state.smoke === 'run' ? ' disabled title="Test in progress"' : '') + '>' + (state.smoke === 'run' ? 'Testing' : 'Test') + '</button>');
}

/* ── arming ── */
let armTimer = 0;
function renderArm() {
  root.dataset.arm = state.arming ? 'arming' : state.arm;
  $('[data-armset]').innerHTML = ARM.map((a) => '<button type="button" role="radio" aria-checked="' + (state.arm === a.id && !state.arming) + '" tabindex="' + (state.arm === a.id ? 0 : -1) + '" data-arm="' + a.id + '"' + (state.arming && state.arming.to === a.id ? ' aria-busy="true"' : '') + '>' + a.name + '</button>').join('');
  const st = $('[data-status]');
  if (state.arming) st.innerHTML = '<i></i><span>Arming ' + ARM.find((a) => a.id === state.arming.to).name + ' in <b>' + state.arming.left + ' s</b></span><button type="button" class="asm-watch-link" data-act="cancelarm">Cancel</button>';
  else if (state.arm === 'off') st.innerHTML = '<i></i><span>Disarmed since ' + fmt(state.armSince) + '</span>';
  else st.innerHTML = '<i></i><span>Armed · ' + ARM.find((a) => a.id === state.arm).name + ' since ' + fmt(state.armSince) + '</span>';
  st.title = state.arming ? '' : ARM.find((a) => a.id === state.arm).desc;
}
function armTo(id) {
  if (state.arming) { clearInterval(armTimer); state.arming = null; }
  if (id === state.arm) { renderArm(); return; }
  if (id === 'off') { openPad(); return; }
  if (state.garage > 0 && id !== 'home') toast('Garage door is open. It will be bypassed until closed.');
  state.arming = { to: id, left: 10 };
  renderArm();
  armTimer = setInterval(() => {
    if (!root.isConnected) { clearInterval(armTimer); return; }
    if (!state.arming) { clearInterval(armTimer); return; }
    state.arming.left--;
    if (state.arming.left <= 0) {
      clearInterval(armTimer);
      state.arm = state.arming.to; state.armSince = Math.floor(liveT()); state.arming = null;
      toast('Armed · ' + ARM.find((a) => a.id === state.arm).name);
    }
    renderArm();
  }, 1000);
}
function openPad() {
  state.code = ''; state.padErr = false;
  const pad = $('[data-pad]');
  pad.hidden = false;
  $('[data-keypad]').innerHTML = ['1', '2', '3', '4', '5', '6', '7', '8', '9', 'clear', '0', 'cancel'].map((k) =>
    '<button type="button" data-key="' + k + '"' + (k === 'clear' ? ' aria-label="Clear"' : k === 'cancel' ? ' aria-label="Cancel"' : '') + '>' + (k === 'clear' ? ic('<path d="M9 6h11v12H9l-5-6Z"/><path d="m12 10 4 4M16 10l-4 4"/>') : k === 'cancel' ? ic('<path d="M6 6l12 12M18 6 6 18"/>') : k) + '</button>').join('');
  paintDots();
  $('[data-key="1"]').focus();
}
function paintDots() {
  const d = $('[data-dots]');
  $$('i', d).forEach((n, i) => n.classList.toggle('is-on', i < state.code.length));
  d.classList.toggle('is-err', state.padErr);
  d.setAttribute('aria-label', state.padErr ? 'Wrong code, try again' : state.code.length + ' of 4 digits');
  $('.asm-watch-padt').textContent = state.padErr ? 'Wrong code. Try again' : 'Enter code to disarm';
}
function closePad() { $('[data-pad]').hidden = true; renderArm(); const n = $('[data-arm="off"]'); if (n) n.focus(); }
function padKey(k) {
  if (k === 'cancel') return closePad();
  if (k === 'clear') { state.code = state.code.slice(0, -1); state.padErr = false; paintDots(); return; }
  if (state.code.length >= 4) return;
  state.code += k; state.padErr = false; paintDots();
  if (state.code.length === 4) {
    if (state.code === '2580') {
      state.arm = 'off'; state.armSince = Math.floor(liveT());
      $('[data-pad]').hidden = true; renderArm(); toast('Disarmed');
    } else {
      state.padErr = true; state.code = ''; paintDots();
      const box = $('.asm-watch-padbox');
      if (!reduce.matches) box.animate([{ transform: 'translateX(0)' }, { transform: 'translateX(-8px)' }, { transform: 'translateX(7px)' }, { transform: 'translateX(-4px)' }, { transform: 'translateX(0)' }], { duration: 360, easing: 'cubic-bezier(.3,.7,.4,1)' });
    }
  }
}

/* ── toast, views ── */
let tT = 0;
function toast(m) { const t = $('[data-toast]'); t.textContent = m; t.hidden = false; clearTimeout(tT); tT = setTimeout(() => { if (root.isConnected) t.hidden = true; }, 3400); }
function setView(v) { state.view = v; root.dataset.view = v; $$('[data-tab]').forEach((t) => t.setAttribute('aria-selected', String(t.dataset.tab === v))); }

root.addEventListener('click', (e) => {
  const t = e.target.closest('button, [data-ev]');
  if (!t || !root.contains(t)) return;
  if (t.dataset.key) return padKey(t.dataset.key);
  if (t.dataset.cam) {
    if (state.layout === 'focus' && state.cam === t.dataset.cam) { state.zoom = !state.zoom; setLayout('focus'); frame(); }
    else setLayout('focus', t.dataset.cam);
    return;
  }
  if (t.dataset.ev) return replay(t.dataset.ev);
  if (t.dataset.tab) return setView(t.dataset.tab);
  if (t.dataset.arm) return armTo(t.dataset.arm);
  if (t.dataset.filter) { state.filter = t.dataset.filter; renderEvents(); return; }
  const a = t.dataset.act;
  if (a === 'layout') setLayout(t.dataset.to);
  else if (a === 'zones') { state.zones = !state.zones; t.setAttribute('aria-pressed', String(state.zones)); frame(); toast(state.zones ? 'Motion zones shown' : 'Motion zones hidden'); }
  else if (a === 'live') goLive();
  else if (a === 'again' && state.ev) replay(state.ev.id);
  else if (a === 'cancelarm') { clearInterval(armTimer); state.arming = null; renderArm(); toast('Arming cancelled'); }
  else if (a === 'reviewall') { EVENTS.forEach((x) => { x.seen = true; }); renderEvents(); toast('All events reviewed'); }
  else if (a === 'garage') { state.garageTo = state.garageTo ? 0 : 1; renderSensors(); kick(); }
  else if (a === 'lock') { const k = t.dataset.lock; state.sensors[k] = !state.sensors[k]; renderSensors(); toast((k === 'front' ? 'Front' : 'Back') + ' door ' + (state.sensors[k] ? 'locked' : 'unlocked')); }
  else if (a === 'smoke') {
    state.smoke = 'run'; renderSensors();
    setTimeout(() => { if (!root.isConnected) return; state.smoke = 'done'; renderSensors(); toast('Smoke and CO test passed'); }, 1800);
  }
});

root.addEventListener('keydown', (e) => {
  const tg = e.target, k = e.key;
  if (!$('[data-pad]').hidden) {
    if (/^[0-9]$/.test(k)) { e.preventDefault(); padKey(k); }
    else if (k === 'Backspace') { e.preventDefault(); padKey('clear'); }
    else if (k === 'Escape') { e.preventDefault(); closePad(); }
    else if (k === 'Tab') {
      const keys = $$('[data-key]'), i = keys.indexOf(document.activeElement);
      if ((e.shiftKey && i === 0) || (!e.shiftKey && i === keys.length - 1)) { e.preventDefault(); keys[e.shiftKey ? keys.length - 1 : 0].focus(); }
    }
    return;
  }
  if (e.metaKey || e.ctrlKey || e.altKey) return;
  if (tg === track && /^(Arrow|Home|End)/.test(k)) {
    e.preventDefault();
    const base = state.mode === 'scrub' ? state.scrubT : shownT();
    const step = (e.shiftKey ? 3600 : 300) * (k === 'ArrowRight' || k === 'ArrowUp' ? 1 : -1);
    const r = track.getBoundingClientRect();
    const tt = k === 'Home' ? 0 : k === 'End' ? liveT() : base + step;
    scrubTo(r.left + (Math.max(0, tt) / 86400) * r.width);
    return;
  }
  const grp = tg.closest('[role=radiogroup], [role=listbox]');
  if (grp && /^Arrow/.test(k)) {
    const items = $$('[role=radio], [role=option]', grp), i = items.indexOf(tg.closest('[role=radio], [role=option]'));
    if (i > -1) {
      e.preventDefault();
      const n = items[(i + (k === 'ArrowRight' || k === 'ArrowDown' ? 1 : -1) + items.length) % items.length];
      if (grp.matches('[role=listbox]')) { n.focus(); return; }
      const key = n.dataset.filter ? '[data-filter="' + n.dataset.filter + '"]' : '[data-arm="' + n.dataset.arm + '"]';
      n.click(); const f = $(key); if (f && $('[data-pad]').hidden) f.focus();
      return;
    }
  }
  if ((k === 'Enter' || k === ' ') && tg.dataset.ev && tg.matches('[role=option]')) { e.preventDefault(); replay(tg.dataset.ev); return; }
  if (k >= '1' && k <= '4') { setLayout('focus', CAMS[+k - 1].id); }
  else if (k === 'g' || k === 'G') setLayout('grid');
  else if (k === 'f' || k === 'F') setLayout('focus');
  else if (k === 'l' || k === 'L') goLive();
  else if (k === 'm' || k === 'M') { $('[data-act="zones"]').click(); }
  else if (k === 'ArrowRight' || k === 'ArrowLeft') {
    if (tg.closest('[role=radiogroup]')) return;
    e.preventDefault();
    const i = state.ev ? EVENTS.indexOf(state.ev) : EVENTS.length;
    const n = EVENTS[Math.max(0, Math.min(EVENTS.length - 1, i + (k === 'ArrowRight' ? 1 : -1)))];
    replay(n.id);
  } else if (k === 'Escape') { if (state.mode !== 'live') goLive(); else if (state.layout === 'focus') setLayout('grid'); }
});

renderArm(); renderEvents(); renderSensors(); renderMarks(); renderReplay(); setLayout('grid');
kick();

css:
.asm-energy {
  /* re-theme with these four */
  --asm-energy-paper: oklch(0.982 0.006 110);
  --asm-energy-ink: oklch(0.22 0.012 120);
  --asm-energy-accent: oklch(0.87 0.19 123);
  --asm-energy-solar: oklch(0.84 0.15 82);
  /* derived */
  --asm-energy-grid: color-mix(in oklab, var(--asm-energy-ink) 62%, var(--asm-energy-paper));
  --asm-energy-batt: var(--asm-energy-accent);
  --asm-energy-card: color-mix(in oklab, white 70%, var(--asm-energy-paper));
  --asm-energy-line: color-mix(in oklab, var(--asm-energy-ink) 10%, transparent);
  --asm-energy-line2: color-mix(in oklab, var(--asm-energy-ink) 18%, transparent);
  --asm-energy-mute: color-mix(in oklab, var(--asm-energy-ink) 60%, var(--asm-energy-paper));
  --asm-energy-faint: color-mix(in oklab, var(--asm-energy-ink) 40%, var(--asm-energy-paper));
  --asm-energy-hover: color-mix(in oklab, var(--asm-energy-ink) 5%, transparent);
  --asm-energy-rib: color-mix(in oklab, var(--asm-energy-ink) 11%, transparent);
  --asm-energy-hl: color-mix(in oklab, var(--asm-energy-accent) 85%, var(--asm-energy-ink));
  --asm-energy-ease: cubic-bezier(.22, .8, .2, 1);
  --asm-energy-spring: linear(0, 0.12 4%, 0.42 10%, 0.78 17%, 0.98 24%, 1.06 30%, 1.07 36%, 1.035 45%, 1.005 56%, 0.997 70%, 1);

  position: relative; width: 100%; height: var(--asm-energy-h, 680px); box-sizing: border-box;
  container-type: inline-size; container-name: asm-energy; overflow: clip; isolation: isolate;
  background: var(--asm-energy-paper); color: var(--asm-energy-ink); color-scheme: light; border-radius: 16px;
  accent-color: var(--asm-energy-ink);
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  box-shadow: inset 0 0 0 1px var(--asm-energy-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--asm-energy-ink); outline-offset: 2px; }
  & button, & input { font: inherit; color: inherit; }
  & button { background: none; border: 0; padding: 0; cursor: pointer; }
  & button:disabled { cursor: not-allowed; opacity: .35; }
  & h2, & p, & table { margin: 0; padding: 0; }
  & [hidden] { display: none !important; }
  & svg { fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; width: 16px; height: 16px; }
  & kbd { font: 600 10px/1 ui-monospace, Menlo, monospace; min-width: 16px; padding: 3px 4px; text-align: center; border-radius: 5px; color: var(--asm-energy-mute); background: var(--asm-energy-card); box-shadow: inset 0 0 0 1px var(--asm-energy-line2), inset 0 -1.5px 0 var(--asm-energy-line2); }
  & .s-solar { --c: var(--asm-energy-solar); }
  & .s-batt { --c: var(--asm-energy-batt); }
  & .s-grid { --c: var(--asm-energy-grid); }
}
.asm-energy .asm-energy-app {
  height: 100%; display: grid; gap: 0 14px; padding: 0 16px;
  grid-template-columns: minmax(0, 1fr) minmax(330px, 36%);
  grid-template-rows: auto auto minmax(0, 1fr) 176px auto;
  grid-template-areas: "top top" "kpis kpis" "flow table" "bars table" "keys keys";
}
.asm-energy .asm-energy-h { font-size: 10.5px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--asm-energy-faint); }

/* top */
.asm-energy .asm-energy-top { grid-area: top; display: flex; align-items: center; gap: 12px; padding: 12px 0; margin: 0 -16px; padding-inline: 16px; border-bottom: 1px solid var(--asm-energy-line); }
.asm-energy .asm-energy-brand {
  display: flex; align-items: center; gap: 10px; margin-right: auto;
  & > svg { width: 30px; height: 30px; padding: 6px; border-radius: 9px; background: var(--asm-energy-accent); color: var(--asm-energy-ink); stroke-width: 2; }
  & b { display: block; font-size: 14.5px; letter-spacing: -.01em; }
  & small { display: block; font-size: 11.5px; color: var(--asm-energy-mute); white-space: nowrap; }
}
.asm-energy .asm-energy-seg {
  display: inline-flex; padding: 3px; border-radius: 10px; background: color-mix(in oklab, var(--asm-energy-ink) 5%, var(--asm-energy-paper));
  & button { height: 28px; padding: 0 12px; border-radius: 7px; font-size: 12.5px; font-weight: 600; color: var(--asm-energy-mute); transition: background .2s, color .2s; }
  & button:hover { color: var(--asm-energy-ink); }
  & button[aria-checked="true"] { background: var(--asm-energy-card); color: var(--asm-energy-ink); box-shadow: 0 1px 2px color-mix(in oklab, var(--asm-energy-ink) 16%, transparent); cursor: default; }
  &.is-unit button { padding: 0 10px; }
}
.asm-energy .asm-energy-step {
  display: inline-flex; align-items: center; gap: 4px;
  & b { min-width: 13.5em; text-align: center; font-size: 13.5px; font-weight: 650; letter-spacing: -.01em; font-variant-numeric: tabular-nums; white-space: nowrap; }
  & button { width: 28px; height: 28px; border-radius: 8px; display: grid; place-items: center; box-shadow: inset 0 0 0 1px var(--asm-energy-line2); transition: background .2s; }
  & button:hover:not(:disabled) { background: var(--asm-energy-hover); }
}

/* kpis */
.asm-energy .asm-energy-kpis { grid-area: kpis; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 10px; padding: 14px 0 12px; }
.asm-energy .asm-energy-kpi {
  display: grid; gap: 1px; padding: 10px 14px 11px; border-radius: 14px; background: var(--asm-energy-card); box-shadow: inset 0 0 0 1px var(--asm-energy-line);
  & span { font-size: 11px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; color: var(--asm-energy-faint); }
  & b { font-size: clamp(20px, 2.3cqi, 27px); font-weight: 680; letter-spacing: -.03em; font-variant-numeric: tabular-nums; line-height: 1.15; }
  & b small { font-size: .5em; font-weight: 600; letter-spacing: 0; color: var(--asm-energy-mute); }
  & em { font-style: normal; font-size: 11.5px; color: var(--asm-energy-mute); font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & em.is-good { color: oklch(0.5 0.13 145); }
  & em.is-bad { color: oklch(0.55 0.17 35); }
  &:first-child { background: var(--asm-energy-ink); color: var(--asm-energy-paper); box-shadow: none; }
  &:first-child span, &:first-child b small { color: color-mix(in oklab, var(--asm-energy-paper) 60%, var(--asm-energy-ink)); }
  &:first-child em.is-good { color: var(--asm-energy-accent); }
  &:first-child em.is-bad { color: oklch(0.8 0.12 45); }
}
.asm-energy .asm-energy-tabs { display: none; }

/* cards */
.asm-energy .asm-energy-flow, .asm-energy .asm-energy-table, .asm-energy .asm-energy-bars {
  min-width: 0; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); border-radius: 16px; background: var(--asm-energy-card); box-shadow: inset 0 0 0 1px var(--asm-energy-line);
}
.asm-energy .asm-energy-flow { grid-area: flow; margin-bottom: 12px; }
.asm-energy .asm-energy-table { grid-area: table; margin-bottom: 12px; }
.asm-energy .asm-energy-bars { grid-area: bars; margin-bottom: 12px; }
.asm-energy .asm-energy-cardhead { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 10px 14px 4px; min-height: 40px; }
.asm-energy .asm-energy-crumb {
  display: flex; align-items: center; gap: 6px; font-size: 13px; min-width: 0;
  & b { font-weight: 680; white-space: nowrap; }
  & span { color: var(--asm-energy-faint); }
  & .hint { font-size: 12px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}
.asm-energy .asm-energy-back { width: 26px; height: 26px; border-radius: 7px; display: grid; place-items: center; box-shadow: inset 0 0 0 1px var(--asm-energy-line2); }
.asm-energy .asm-energy-back:hover, .asm-energy .asm-energy-crumbl:hover { background: var(--asm-energy-hover); }
.asm-energy .asm-energy-crumbl { color: var(--asm-energy-mute); font-weight: 560; padding: 2px 4px; border-radius: 5px; white-space: nowrap; }
.asm-energy .asm-energy-legend {
  display: flex; gap: 12px; font-size: 11.5px; color: var(--asm-energy-mute); flex: none;
  & span { display: inline-flex; align-items: center; gap: 5px; }
  & i { width: 9px; height: 9px; border-radius: 3px; background: var(--c); }
}

/* sankey */
.asm-energy .asm-energy-sankey {
  position: relative; min-height: 0; margin: 0 6px 8px;
  & svg { position: absolute; inset: 0; width: 100%; height: 100%; display: block; overflow: visible; }
  & path { transition: d .75s var(--asm-energy-ease), fill .3s, opacity .3s; stroke: none; }
  & .rib { fill: var(--c, var(--asm-energy-rib)); opacity: .55; }
  & .rib.r { fill: var(--asm-energy-rib); opacity: 1; }
  & .rib.is-zero { opacity: 0; }
  & .node { fill: var(--c, var(--asm-energy-ink)); }
  & .node.mid, & .node.rn { fill: var(--asm-energy-ink); }
  & .rib.r.is-hl, & .rib.r.is-hover { fill: color-mix(in oklab, var(--asm-energy-accent) 70%, transparent); }
  & .node.rn.is-hl, & .node.rn.is-hover { fill: var(--asm-energy-hl); }
  &.has-hover .rib.r:not(.is-hover), &.has-hl:not(.has-hover) .rib.r:not(.is-hl) { opacity: .45; }
  &.is-sizing path, &.is-sizing .lab { transition: none; }
}
.asm-energy .asm-energy-sankey:has(.lr:hover) .lab.lr:not(:hover) { opacity: .55; }
.asm-energy .asm-energy-labels { position: absolute; inset: 0; pointer-events: none; }
.asm-energy .lab {
  position: absolute; left: 0; top: 0; display: grid; line-height: 1.2; white-space: nowrap; pointer-events: auto;
  transform: translate(calc(var(--x, 0) * 1px), calc(var(--y, 0) * 1px)) translate(0, -50%);
  transition: transform .75s var(--asm-energy-ease), opacity .3s;
  & b { font-size: 12.5px; font-weight: 650; }
  & small { font-size: 11px; color: var(--asm-energy-mute); font-variant-numeric: tabular-nums; }
  &.is-zero { opacity: 0; pointer-events: none; }
}
.asm-energy .lab.ls { text-align: right; transform: translate(calc(var(--x, 0) * 1px), calc(var(--y, 0) * 1px)) translate(-100%, -50%); }
.asm-energy .lab.lm { text-align: left; transform: translate(calc(var(--x, 0) * 1px), calc(var(--y, 0) * 1px)) translate(-50%, -100%); justify-items: center; }
.asm-energy .lab.lr {
