  { id: 'wh', name: 'Hot water boost', cat: 'heat', kwh: 1.2, s: 'morning' },
  { id: 'ev', name: 'Car charger', cat: 'ev', kwh: 9.6, s: 'night', days: [1, 4, 6] },
  { id: 'oven', name: 'Oven and hob', cat: 'kitchen', kwh: 1.1, s: 'dinner' },
  { id: 'fridge', name: 'Fridge-freezer', cat: 'kitchen', kwh: 0.9, s: 'flat' },
  { id: 'dish', name: 'Dishwasher', cat: 'kitchen', kwh: 0.8, s: 'late' },
  { id: 'kettle', name: 'Kettle', cat: 'kitchen', kwh: 0.3, s: 'meals' },
  { id: 'wash', name: 'Washing machine', cat: 'laundry', kwh: 0.7, s: 'midday', days: [0, 3, 4] },
  { id: 'dry', name: 'Tumble dryer', cat: 'laundry', kwh: 1.4, s: 'afternoon', days: [0, 3, 4] },
  { id: 'tv', name: 'TV and console', cat: 'media', kwh: 0.6, s: 'evening' },
