const SRC = [{ id: 'solar', name: 'Solar' }, { id: 'batt', name: 'Battery' }, { id: 'grid', name: 'Grid' }];

/* ── dates: day numbers since 1 Jan 2026 (a Thursday) ── */
const MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
