  --asm-garden-line2: color-mix(in oklab, var(--asm-garden-ink) 20%, transparent);
  --asm-garden-mute: color-mix(in oklab, var(--asm-garden-ink) 62%, var(--asm-garden-paper));
  --asm-garden-faint: color-mix(in oklab, var(--asm-garden-ink) 42%, var(--asm-garden-paper));
  --asm-garden-hover: color-mix(in oklab, var(--asm-garden-ink) 5%, transparent);
  --asm-garden-wtint: color-mix(in oklab, var(--asm-garden-water) 16%, var(--asm-garden-card));
  --asm-garden-warn: oklch(0.6 0.15 55);
  --asm-garden-ease: cubic-bezier(.2, .8, .2, 1);
  --asm-garden-spring: linear(0, 0.12 4%, 0.42 10%, 0.78 17%, 0.98 24%, 1.06 30%, 1.07 36%, 1.035 45%, 1.005 56%, 0.997 70%, 1);

  position: relative; width: 100%; height: var(--asm-garden-h, 680px); box-sizing: border-box;
  container-type: inline-size; container-name: asm-garden; overflow: clip; isolation: isolate;
  background: var(--asm-garden-paper); color: var(--asm-garden-ink); color-scheme: light; border-radius: 16px;
  accent-color: var(--asm-garden-water);
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  box-shadow: inset 0 0 0 1px var(--asm-garden-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--asm-garden-water); outline-offset: 2px; }
  & button { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
  & button:disabled { cursor: not-allowed; opacity: .4; }
  & h2, & h3, & p, & dl, & dd { margin: 0; padding: 0; }
  & [hidden] { display: none !important; }
  & svg { fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; flex: none; width: 16px; height: 16px; }
  & kbd { font: 600 10px/1 ui-monospace, Menlo, monospace; min-width: 16px; padding: 3px 4px; text-align: center; border-radius: 5px; color: var(--asm-garden-mute); background: var(--asm-garden-card); box-shadow: inset 0 0 0 1px var(--asm-garden-line2), inset 0 -1.5px 0 var(--asm-garden-line2); }
}
.asm-garden .asm-garden-app {
  height: 100%; display: grid;
  grid-template-columns: minmax(0, .92fr) minmax(0, 1.28fr);
  grid-template-rows: auto minmax(0, 1fr) auto;
  grid-template-areas: "top top" "left right" "keys keys";
}
.asm-garden .asm-garden-h { font-size: 10.5px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--asm-garden-faint); }

/* top */
.asm-garden .asm-garden-top { grid-area: top; display: flex; align-items: center; gap: 12px; padding: 12px 16px; border-bottom: 1px solid var(--asm-garden-line); }
.asm-garden .asm-garden-brand {
  display: flex; align-items: center; gap: 10px; margin-right: auto;
  & > svg { width: 30px; height: 30px; padding: 6px; border-radius: 9px; background: var(--asm-garden-water); color: white; stroke-width: 2; }
  & b { display: block; font-size: 14.5px; letter-spacing: -.01em; }
  & small { display: block; font-size: 11.5px; color: var(--asm-garden-mute); white-space: nowrap; }
}
.asm-garden .asm-garden-tabs { display: none; }
.asm-garden .asm-garden-ctl { display: flex; align-items: center; gap: 8px; }
.asm-garden .asm-garden-lab { font-size: 12px; color: var(--asm-garden-mute); }
.asm-garden .asm-garden-seg {
  display: inline-flex; padding: 3px; border-radius: 10px; background: var(--asm-garden-side); box-shadow: inset 0 0 0 1px var(--asm-garden-line);
  & button { height: 26px; padding: 0 10px; border-radius: 7px; font-size: 12px; font-weight: 600; color: var(--asm-garden-mute); transition: background .2s, color .2s; }
  & button:hover { color: var(--asm-garden-ink); }
  & button[aria-checked="true"] { background: var(--asm-garden-card); color: var(--asm-garden-ink); cursor: default; box-shadow: 0 1px 2px color-mix(in oklab, var(--asm-garden-ink) 15%, transparent); }
}
.asm-garden .asm-garden-skip {
  display: inline-flex; align-items: center; gap: 8px; height: 32px; padding: 0 10px 0 8px; border-radius: 10px; font-weight: 600; font-size: 12.5px;
  background: var(--asm-garden-card); box-shadow: inset 0 0 0 1px var(--asm-garden-line2); white-space: nowrap;
  & i { position: relative; width: 30px; height: 18px; border-radius: 99px; background: var(--asm-garden-line2); transition: background .25s; }
  & i::after { content: ""; position: absolute; left: 2px; top: 2px; width: 14px; height: 14px; border-radius: 50%; background: white; box-shadow: 0 1px 2px color-mix(in oklab, var(--asm-garden-ink) 30%, transparent); transition: transform .45s var(--asm-garden-spring); }
  &[aria-checked="true"] i { background: var(--asm-garden-water); }
  &[aria-checked="true"] i::after { transform: translateX(12px); }
  & small { font-weight: 500; color: var(--asm-garden-mute); }
}

/* left: map + zone */
.asm-garden .asm-garden-left { grid-area: left; min-height: 0; overflow: auto; padding: 14px 14px 16px 16px; display: flex; flex-direction: column; gap: 12px; scrollbar-width: thin; border-right: 1px solid var(--asm-garden-line); }
.asm-garden .asm-garden-mapwrap { display: grid; gap: 6px; }
.asm-garden .asm-garden-map {
  width: 100%; height: auto; aspect-ratio: 420 / 300; display: block; border-radius: 12px; overflow: visible;
  & .ground { fill: oklch(0.91 0.025 85); }
  & .house { fill: oklch(0.47 0.02 60); }
  & .roof { stroke: oklch(0.58 0.02 60); stroke-width: 1; }
  & .patio { fill: oklch(0.84 0.02 75); }
  & .pave { stroke: oklch(0.76 0.02 75); stroke-width: 1; }
  & .stones { stroke: oklch(0.8 0.02 75); stroke-width: 9; }
  & .shed { fill: oklch(0.6 0.05 55); }
  & .hl { fill: oklch(0.95 0.01 80); font: 650 10px system-ui, sans-serif; text-anchor: middle; letter-spacing: .08em; text-transform: uppercase; stroke: none; }
  & .hl.sm { font-size: 8px; }
  & .zone { cursor: pointer; outline: none; --base: var(--asm-garden-leaf); }
  & .zone[aria-current="true"] { cursor: default; }
  & .shape { fill: color-mix(in oklab, var(--asm-garden-water) calc(var(--m) * 70%), var(--base)); stroke: color-mix(in oklab, var(--base) 70%, black); stroke-width: 1; transition: fill .8s var(--asm-garden-ease), stroke .25s, stroke-width .25s; }
  & .zone:hover .shape { stroke: var(--asm-garden-ink); stroke-width: 1.6; }
  & .zone[aria-current="true"] .shape { stroke: var(--asm-garden-ink); stroke-width: 2.2; stroke-dasharray: 5 3; }
  & .zone:focus-visible .shape { stroke: var(--asm-garden-water); stroke-width: 3; stroke-dasharray: none; }
  & .det { stroke: color-mix(in oklab, var(--base) 55%, black); stroke-width: 1.2; pointer-events: none; }
  & .badge { pointer-events: none; }
  & .badge circle { fill: var(--asm-garden-card); stroke: var(--asm-garden-ink); stroke-width: 1.2; transition: fill .25s; }
  & .bn { font: 700 10px system-ui, sans-serif; text-anchor: middle; fill: var(--asm-garden-ink); stroke: none; }
  & .zone[aria-current="true"] .badge circle { fill: var(--asm-garden-ink); }
  & .zone[aria-current="true"] .bn { fill: var(--asm-garden-card); }
  & .zone.is-run .badge circle { fill: var(--asm-garden-water); stroke: var(--asm-garden-water); }
  & .zone.is-run .bn { fill: white; }
  & .zm { font: 650 10px system-ui, sans-serif; fill: var(--asm-garden-ink); pointer-events: none; paint-order: stroke; stroke: color-mix(in oklab, white 80%, transparent); stroke-width: 3.5px; stroke-linejoin: round; font-variant-numeric: tabular-nums; }
  & .head { fill: var(--asm-garden-ink); opacity: .55; }
  & .drop { fill: none; stroke: color-mix(in oklab, var(--asm-garden-water) 80%, white); stroke-width: 1.4; opacity: 0; transform-box: fill-box; transform-origin: center; pointer-events: none; }
  & .zone.is-run .drop { animation: asm-garden-spray 1.6s var(--asm-garden-ease) infinite; animation-delay: calc(var(--j) * -530ms); }
  & .zone.is-run .head { fill: var(--asm-garden-water); opacity: 1; }
  & [data-z="hedge"] { --base: oklch(0.5 0.09 145); }
  & [data-z="herbs"] { --base: oklch(0.7 0.08 115); }
  & [data-z="veg"] { --base: oklch(0.56 0.06 58); }
  & [data-z="trees"] { --base: oklch(0.6 0.11 140); }
  & [data-z="glass"] { --base: oklch(0.9 0.025 190); }
}
.asm-garden .asm-garden-mlegend {
  display: flex; gap: 14px; font-size: 11.5px; color: var(--asm-garden-mute);
  & span { display: inline-flex; align-items: center; gap: 6px; }
  & i { width: 14px; height: 9px; border-radius: 3px; }
  & i.dry { background: var(--asm-garden-leaf); }
  & i.wet { background: color-mix(in oklab, var(--asm-garden-water) 45%, var(--asm-garden-leaf)); }
  & .note { margin-left: auto; font-variant-numeric: tabular-nums; }
}
.asm-garden .asm-garden-zone {
  display: grid; gap: 12px; padding: 14px; border-radius: 16px; background: var(--asm-garden-card); box-shadow: inset 0 0 0 1px var(--asm-garden-line);
}
.asm-garden .asm-garden-zhead {
  display: flex; justify-content: space-between; align-items: center; gap: 12px;
  & h3 { font-size: clamp(17px, 1.6cqi, 21px); font-weight: 700; letter-spacing: -.02em; line-height: 1.2; text-wrap: balance; }
  & .pl { font-size: 12px; color: var(--asm-garden-mute); }
}
.asm-garden .asm-garden-ring {
  position: relative; width: 52px; height: 52px; flex: none;
  & svg { position: absolute; inset: 0; width: 100%; height: 100%; transform: rotate(-90deg); }
  & .tr { stroke: var(--asm-garden-line2); stroke-width: 3; }
  & .pr { stroke: var(--asm-garden-water); stroke-width: 3; stroke-dasharray: 1; stroke-dashoffset: calc(1 - var(--p)); transition: stroke-dashoffset .25s linear; }
  & .asm-garden-run { position: absolute; inset: 6px; border-radius: 50%; display: grid; place-items: center; background: var(--asm-garden-water); color: white; transition: transform .35s var(--asm-garden-spring), background .2s; }
  & .asm-garden-run:hover { background: color-mix(in oklab, var(--asm-garden-water) 85%, black); }
  & .asm-garden-run:active { transform: scale(.92); }
  & .asm-garden-run svg { position: static; width: 18px; height: 18px; transform: none; fill: currentColor; stroke: none; }
  &.is-run .asm-garden-run { background: var(--asm-garden-ink); }
}
.asm-garden .asm-garden-moist {
  display: grid; grid-template-columns: auto minmax(0, 1fr) 120px; align-items: center; gap: 14px;
  & .mv b { display: block; font-size: 30px; font-weight: 300; letter-spacing: -.04em; line-height: 1; font-variant-numeric: tabular-nums; }
  & .mv b small { font-size: .45em; font-weight: 500; letter-spacing: 0; }
  & .mv span { font-size: 11.5px; color: var(--asm-garden-mute); }
  & .mv span.is-low { color: var(--asm-garden-warn); font-weight: 600; }
  & .mbar { position: relative; height: 10px; border-radius: 6px; background: var(--asm-garden-side); box-shadow: inset 0 0 0 1px var(--asm-garden-line); overflow: hidden; }
  & .mbar i { position: absolute; inset: 0; background: linear-gradient(90deg, color-mix(in oklab, var(--asm-garden-water) 40%, white), var(--asm-garden-water)); transform-origin: left; transform: scaleX(calc(var(--m) / .8)); transition: transform .4s var(--asm-garden-ease); }
  & .mbar .band { position: absolute; top: 0; bottom: 0; left: calc(35% / .8); width: calc(25% / .8); border-inline: 1.5px dashed var(--asm-garden-ink); opacity: .45; }
}
.asm-garden .asm-garden-spark {
  width: 120px; height: 32px; overflow: visible;
  & .band { fill: color-mix(in oklab, var(--asm-garden-water) 12%, transparent); stroke: none; }
  & path { stroke: var(--asm-garden-water); stroke-width: 1.6; vector-effect: non-scaling-stroke; }
  & circle { fill: var(--asm-garden-water); stroke: none; }
}
.asm-garden .asm-garden-facts {
  display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px 14px;
  & div { display: grid; }
  & .w { grid-column: 1 / -1; }
  & dt { font-size: 10.5px; font-weight: 650; letter-spacing: .06em; text-transform: uppercase; color: var(--asm-garden-faint); }
  & dd { font-size: 13px; font-weight: 560; font-variant-numeric: tabular-nums; }
}

/* right: grid + budget */
.asm-garden .asm-garden-right { grid-area: right; min-width: 0; min-height: 0; overflow: auto; padding: 14px 16px 16px; display: flex; flex-direction: column; gap: 12px; scrollbar-width: thin; }
.asm-garden :is(.asm-garden-right, .asm-garden-left) > * { flex: none; }
.asm-garden .asm-garden-planhead {
  display: flex; justify-content: space-between; align-items: end; gap: 10px; flex-wrap: wrap;
  & .asm-garden-sub { font-size: 12.5px; color: var(--asm-garden-mute); text-wrap: pretty; }
}
.asm-garden .asm-garden-help { display: flex; align-items: center; gap: 3px; font-size: 11px; color: var(--asm-garden-faint); white-space: nowrap; }
.asm-garden .asm-garden-gridwrap { overflow-x: auto; scrollbar-width: thin; }
.asm-garden .asm-garden-grid {
  display: grid; grid-template-columns: minmax(118px, 1.35fr) repeat(7, minmax(44px, 1fr)) minmax(58px, .8fr); gap: 3px; min-width: 520px;
  & .row { grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; align-items: stretch; }
  & .c { display: grid; min-width: 0; }
  & .zc { align-items: center; }
  & .hd .c { padding: 2px 0 6px; }
  & .hd .zc { font-size: 10.5px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--asm-garden-faint); align-self: end; }
  & .dc { justify-items: center; text-align: center; gap: 1px; border-radius: 10px; padding: 6px 2px !important; position: relative; animation: asm-garden-in .45s var(--asm-garden-ease) both; animation-delay: calc(var(--i) * 30ms); }
  & .dc b { font-size: 11.5px; font-weight: 700; }
  & .dc svg { width: 20px; height: 20px; color: var(--asm-garden-water); stroke-width: 1.5; }
  & .dc small { font-size: 10.5px; color: var(--asm-garden-mute); font-variant-numeric: tabular-nums; white-space: nowrap; }
  & .dc em { font-style: normal; font-size: 10px; color: var(--asm-garden-faint); font-variant-numeric: tabular-nums; }
  & .dc u { position: absolute; top: -7px; left: 50%; translate: -50% 0; text-decoration: none; font-size: 9.5px; font-weight: 700; letter-spacing: .04em; padding: 1px 6px; border-radius: 99px; background: var(--asm-garden-water); color: white; }
  & .dc.is-skip { background: var(--asm-garden-wtint); }
  & .tc { justify-items: end; align-content: center; padding-right: 4px; font-variant-numeric: tabular-nums; }
  & .tc b { font-size: 12.5px; font-weight: 650; }
  & .tc small { font-size: 10px; color: var(--asm-garden-faint); }
  & .hd .tc { font-size: 10.5px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--asm-garden-faint); align-content: end; }
}
.asm-garden .asm-garden-grid .zb {
  display: flex; align-items: center; gap: 8px; width: 100%; height: 100%; min-height: 38px; padding: 0 8px; border-radius: 9px; text-align: left; font-weight: 600; font-size: 12.5px; transition: background .2s;
  & i { width: 10px; height: 10px; border-radius: 3px; flex: none; background: color-mix(in oklab, var(--asm-garden-water) calc(var(--m) * 140%), var(--asm-garden-leaf)); }
  &:hover { background: var(--asm-garden-hover); }
  &[aria-pressed="true"] { background: var(--asm-garden-card); box-shadow: inset 0 0 0 1.5px var(--asm-garden-ink); }
}
.asm-garden .asm-garden-grid .cell {
  position: relative; width: 100%; min-height: 38px; border-radius: 9px; display: grid; place-items: center; font-variant-numeric: tabular-nums;
  background: var(--asm-garden-side); box-shadow: inset 0 0 0 1px var(--asm-garden-line); overflow: hidden; isolation: isolate;
  transition: box-shadow .2s, transform .3s var(--asm-garden-spring), background .2s;
  & span { color: var(--asm-garden-faint); }
  & b { font-size: 13px; font-weight: 650; }
  & svg { position: absolute; right: 3px; top: 3px; width: 11px; height: 11px; color: var(--asm-garden-water); }
  &::before { content: ""; position: absolute; inset: 0; z-index: -1; background: color-mix(in oklab, var(--asm-garden-water) 32%, var(--asm-garden-card)); transform-origin: bottom; transform: scaleY(var(--w)); transition: transform .45s var(--asm-garden-spring); }
  &:not(.is-on)::before { transform: scaleY(0); }
  &:hover { box-shadow: inset 0 0 0 1.5px var(--asm-garden-line2); }
  &:active { transform: scale(.94); }
  &.is-on { background: var(--asm-garden-card); }
  &.is-skipped { color: var(--asm-garden-faint); }
  &.is-skipped b { text-decoration: line-through; text-decoration-thickness: 1.5px; }
  &.is-skipped::before { background: repeating-linear-gradient(135deg, color-mix(in oklab, var(--asm-garden-water) 14%, var(--asm-garden-card)) 0 4px, var(--asm-garden-card) 4px 8px); }
}
.asm-garden .asm-garden-budget {
  display: grid; gap: 10px; margin-top: auto; padding: 14px; border-radius: 16px; background: var(--asm-garden-card); box-shadow: inset 0 0 0 1px var(--asm-garden-line);
  counter-reset: asm-garden-n var(--asm-garden-n) asm-garden-s var(--asm-garden-s);
  transition: --asm-garden-n 1s var(--asm-garden-ease), --asm-garden-s 1s var(--asm-garden-ease);
  & .num::after { content: counter(asm-garden-n) " L"; }
  & .num2::after { content: counter(asm-garden-s); }
  &.is-over .num { color: var(--asm-garden-warn); }
}
.asm-garden .asm-garden-btop {
  display: flex; justify-content: space-between; align-items: end; gap: 12px; flex-wrap: wrap;
  & p { display: grid; }
  & .num, & .num2 { font-size: clamp(22px, 2.6cqi, 30px); font-weight: 700; letter-spacing: -.03em; line-height: 1.1; font-variant-numeric: tabular-nums; }
  & .num2 { color: var(--asm-garden-water); }
  & .sv { text-align: right; }
  & small { font-size: 12px; color: var(--asm-garden-mute); }
}
.asm-garden .asm-garden-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.asm-garden .asm-garden-stack {
  position: relative; display: flex; height: 14px; border-radius: 7px; background: var(--asm-garden-side); box-shadow: inset 0 0 0 1px var(--asm-garden-line);
  & i { height: 100%; flex: none; width: calc(var(--w) * 100%); background: oklch(0.62 0.11 calc(238 - var(--z) * 19)); transition: width .8s var(--asm-garden-ease); }
  & i:first-child { border-radius: 7px 0 0 7px; }
  & .cap { position: absolute; top: -4px; bottom: -4px; width: 2px; margin-left: -1px; background: var(--asm-garden-ink); border-radius: 2px; transition: left .8s var(--asm-garden-ease); }
}
.asm-garden .asm-garden-blegend {
  display: flex; flex-wrap: wrap; gap: 4px 14px; font-size: 11.5px; color: var(--asm-garden-mute);
  & span { display: inline-flex; align-items: center; gap: 5px; }
  & i { width: 9px; height: 9px; border-radius: 3px; background: oklch(0.62 0.11 calc(238 - var(--z) * 19)); }
  & b { color: var(--asm-garden-ink); font-weight: 600; font-variant-numeric: tabular-nums; }
}

/* footer + toast */
.asm-garden .asm-garden-keys {
  grid-area: keys; display: flex; flex-wrap: wrap; gap: 4px 16px; padding: 8px 16px; border-top: 1px solid var(--asm-garden-line); font-size: 11.5px; color: var(--asm-garden-mute);
  & span { display: inline-flex; align-items: center; gap: 4px; }
}
.asm-garden .asm-garden-toast {
  position: absolute; left: 50%; bottom: 46px; z-index: 5; max-width: calc(100% - 32px); padding: 9px 14px; border-radius: 11px; font-size: 12.5px;
  background: var(--asm-garden-ink); color: var(--asm-garden-paper); translate: -50% 0; box-shadow: 0 16px 40px -14px color-mix(in oklab, var(--asm-garden-ink) 70%, transparent);
  transition: opacity .3s var(--asm-garden-ease), translate .45s var(--asm-garden-spring);
  @starting-style { opacity: 0; translate: -50% 12px; }
}

@keyframes asm-garden-spray { 0% { opacity: 0; transform: scale(.15); } 25% { opacity: .9; } 100% { opacity: 0; transform: scale(1); } }
@keyframes asm-garden-in { from { opacity: 0; transform: translateY(5px); } }

/* responsive */
@container asm-garden (width < 960px) {
  .asm-garden .asm-garden-app { grid-template-columns: minmax(0, .8fr) minmax(0, 1.2fr); }
  .asm-garden .asm-garden-lab, .asm-garden .asm-garden-help, .asm-garden .asm-garden-brand small { display: none; }
  .asm-garden .asm-garden-moist { grid-template-columns: auto minmax(0, 1fr); }
  .asm-garden .asm-garden-spark { display: none; }
  .asm-garden .asm-garden-grid .dc small .t { display: none; }
}
@container asm-garden (width < 760px) {
  .asm-garden .asm-garden-app { grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr) auto; grid-template-areas: "top" "main" "keys"; }
  .asm-garden .asm-garden-top { flex-wrap: wrap; gap: 8px; padding: 10px 12px; }
  .asm-garden .asm-garden-tabs {
    display: flex; order: 3; width: 100%; padding: 3px; border-radius: 10px; background: var(--asm-garden-side); box-shadow: inset 0 0 0 1px var(--asm-garden-line);
