const DEFAULT_MIN = { lawn: 15, veg: 25, herbs: 10, hedge: 20, trees: 15, glass: 8 };
const BUDGET = 2400;
const state = { zone: 'lawn', plan: JSON.parse(JSON.stringify(PLAN0)), skip: true, delay: 0, run: null, cell: [0, 0], view: 'map', today: 0 };
const Z = (id) => ZONES.find((z) => z.id === id);

/* ── rules ── */
function skipReason(zid, di) {
