const DETAIL = {
  hedge: '<path class="det" d="M13 30v230M13 280h210" stroke-dasharray="1 7"/>',
  lawn: '<path class="det" d="M52 112v152M72 112v152M92 112v152M112 112v152M132 112v152M152 112v152M172 112v152M192 112v152M212 112v152" opacity=".35"/>',
