  veg: '<path class="det" d="M262 142h0M280 142h0M298 142h0M316 142h0M334 142h0M352 142h0M370 142h0M388 142h0M262 180h0M280 180h0M298 180h0M316 180h0M334 180h0M352 180h0M370 180h0M388 180h0M262 218h0M280 218h0M298 218h0M316 218h0M334 218h0M352 218h0M370 218h0M388 218h0" stroke-width="7" stroke-linecap="round" opacity=".45"/>',
  trees: '<path class="det" d="M282 266m-8 0a8 8 0 1 0 16 0a8 8 0 1 0-16 0M331 270m-9 0a9 9 0 1 0 18 0a9 9 0 1 0-18 0M383 262m-11 0a11 11 0 1 0 22 0a11 11 0 1 0-22 0" opacity=".35"/>',
  glass: '<path class="det" d="M335 14v70M359 14v70M383 14v70M312 49h94" opacity=".5"/>'
};
const HEADS = {
  lawn: [[40, 120], [220, 120], [40, 256], [220, 256], [130, 188]], veg: [[256, 142], [256, 180], [256, 218]], herbs: [[272, 96]],
  hedge: [[13, 140], [130, 281]], trees: [[282, 266], [331, 270], [383, 262]], glass: [[336, 49], [382, 49]]
