      '<button type="button" class="asm-garden-run" data-act="run" aria-label="' + (run ? 'Stop ' + z.name : 'Run ' + z.name + ' now for ' + dur + ' minutes') + '">' + (run ? ic('<rect x="7" y="7" width="10" height="10" rx="1.5"/>') : ic('<path d="M8 5.5v13l10-6.5Z"/>')) + '</button></div></div>' +
    '<div class="asm-garden-moist"><div class="mv"><b>' + mPct + '<small>%</small></b><span class="' + (mPct < 35 ? 'is-low' : '') + '">' + status + '</span></div>' +
