      return '<span class="c" role="gridcell"><button type="button" class="cell' + (on ? ' is-on' : '') + (why && on ? ' is-skipped' : '') + '" data-cell="' + zi + ',' + di + '" tabindex="' + (focus ? 0 : -1) + '" aria-pressed="' + on + '" aria-label="' + z.name + ', ' + DAYS[di].d + ' ' + DAYS[di].n + ': ' + (on ? min + ' minutes' + (why ? ', skipped for ' + why.toLowerCase() : '') : 'off') + '" style="--w:' + Math.min(1, min / 30).toFixed(3) + '">' +
        (on ? '<b>' + min + '</b>' + (why ? ic('<path d="M12 4c2.5 3.5 4.5 6 4.5 8.5a4.5 4.5 0 0 1-9 0C7.5 10 9.5 7.5 12 4Z"/><path d="M4 20 20 4"/>') : '') : '<span>–</span>') + '</button></span>';
