  const z = ZONES[zi], v = state.plan[z.id][di];
  state.plan[z.id][di] = v ? 0 : DEFAULT_MIN[z.id];
  state.cell = [zi, di];
  renderGrid(); renderBudget(); if (state.zone === z.id) renderZone();
  focusCell();
  const why = skipReason(z.id, di);
  toast(z.name + ' ' + DAYS[di].d + ': ' + (v ? 'off' : DEFAULT_MIN[z.id] + ' min' + (why ? ', but skipped for ' + why.toLowerCase() : '')));
