  if (t.dataset.tab) return setView(t.dataset.tab);
  if (t.dataset.pick) { selectZone(t.dataset.pick); if (root.clientWidth < 760) setView('map'); return; }
  if (t.dataset.cell) { const [zi, di] = t.dataset.cell.split(',').map(Number); toggleCell(zi, di); return; }
  if (t.dataset.delayset != null) { state.delay = +t.dataset.delayset; renderAll(); toast(state.delay ? 'Watering paused for ' + state.delay + ' h' : 'Rain delay off'); return; }
  const a = t.dataset.act;
  if (a === 'skip') { state.skip = !state.skip; renderAll(); toast(state.skip ? 'Smart skip on · rainy days are skipped' : 'Smart skip off · every planned run will water'); }
  else if (a === 'run') { if (state.run && state.run.z === state.zone) stopRun(); else startRun(state.zone); }
});

root.addEventListener('keydown', (e) => {
  const tg = e.target, k = e.key;
  if (e.metaKey || e.ctrlKey || e.altKey) return;
  if (tg.dataset.z && (k === 'Enter' || k === ' ')) { e.preventDefault(); selectZone(tg.dataset.z); return; }
  if (tg.dataset.cell) {
    const [zi, di] = tg.dataset.cell.split(',').map(Number);
    const mv = { ArrowRight: [0, 1], ArrowLeft: [0, -1], ArrowDown: [1, 0], ArrowUp: [-1, 0] }[k];
    if (mv) {
      e.preventDefault();
      state.cell = [Math.max(0, Math.min(ZONES.length - 1, zi + mv[0])), Math.max(0, Math.min(6, di + mv[1]))];
      $$('[data-cell]').forEach((c) => { c.tabIndex = c.dataset.cell === state.cell.join(',') ? 0 : -1; });
      focusCell(); return;
    }
    if (k === 'Home' || k === 'End') { e.preventDefault(); state.cell = [zi, k === 'Home' ? 0 : 6]; $$('[data-cell]').forEach((c) => { c.tabIndex = c.dataset.cell === state.cell.join(',') ? 0 : -1; }); focusCell(); return; }
    if (k === '+' || k === '=') { e.preventDefault(); bump(zi, di, 5); return; }
    if (k === '-' || k === '_') { e.preventDefault(); bump(zi, di, -5); return; }
  }
  const grp = tg.closest('[role=radiogroup]');
  if (grp && /^Arrow/.test(k)) {
    e.preventDefault();
    const it = $$('[role=radio]', grp), i = it.indexOf(tg), n = it[(i + (k === 'ArrowRight' || k === 'ArrowDown' ? 1 : -1) + it.length) % it.length];
    const v = n.dataset.delayset; n.click(); const f = $('[data-delayset="' + v + '"]'); if (f) f.focus(); return;
  }
  if (k >= '1' && k <= '6') { selectZone(ZONES[+k - 1].id); }
  else if (k === 'r' || k === 'R') { if (state.run && state.run.z === state.zone) stopRun(); else startRun(state.zone); }
  else if (k === 's' || k === 'S') { $('[data-act="skip"]').click(); }
  else if (k === 'Escape' && state.run) stopRun();
});

renderAll();

css:
.asm-presence {
  /* re-theme with these four */
  --asm-presence-bg: oklch(0.205 0.013 112);
  --asm-presence-ink: oklch(0.93 0.014 100);
  --asm-presence-accent: oklch(0.87 0.12 104);
  --asm-presence-home: oklch(0.8 0.12 150);
  /* people */
  --asm-presence-p1: oklch(0.74 0.14 34);
  --asm-presence-p2: oklch(0.82 0.13 86);
  --asm-presence-p3: oklch(0.78 0.11 165);
  --asm-presence-p4: oklch(0.75 0.1 252);
  --asm-presence-p5: oklch(0.76 0.07 62);
  /* derived */
  --asm-presence-panel: color-mix(in oklab, var(--asm-presence-ink) 4%, var(--asm-presence-bg));
  --asm-presence-raise: color-mix(in oklab, var(--asm-presence-ink) 8%, var(--asm-presence-bg));
  --asm-presence-line: color-mix(in oklab, var(--asm-presence-ink) 10%, transparent);
  --asm-presence-line2: color-mix(in oklab, var(--asm-presence-ink) 18%, transparent);
  --asm-presence-mute: color-mix(in oklab, var(--asm-presence-ink) 60%, var(--asm-presence-bg));
  --asm-presence-faint: color-mix(in oklab, var(--asm-presence-ink) 38%, var(--asm-presence-bg));
  --asm-presence-hover: color-mix(in oklab, var(--asm-presence-ink) 6%, transparent);
  --asm-presence-ease: cubic-bezier(.2, .8, .2, 1);
  --asm-presence-spring: linear(0, 0.12 4%, 0.42 10%, 0.78 17%, 0.98 24%, 1.06 30%, 1.07 36%, 1.035 45%, 1.005 56%, 0.997 70%, 1);
  --asm-presence-ln: 66px;

  position: relative; width: 100%; height: var(--asm-presence-h, 680px); box-sizing: border-box;
  container-type: inline-size; container-name: asm-presence; overflow: clip; isolation: isolate;
  background: var(--asm-presence-bg); color: var(--asm-presence-ink); color-scheme: dark; border-radius: 16px;
  accent-color: var(--asm-presence-accent);
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  box-shadow: inset 0 0 0 1px var(--asm-presence-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--asm-presence-accent); outline-offset: 2px; }
  & button { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
  & button:disabled { cursor: not-allowed; opacity: .4; }
  & h2, & p, & ul, & ol { margin: 0; padding: 0; }
  & ul, & ol { list-style: none; }
  & [hidden] { display: none !important; }
  & svg { fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; flex: none; width: 16px; height: 16px; }
  & kbd { font: 600 10px/1 ui-monospace, Menlo, monospace; min-width: 16px; padding: 3px 4px; text-align: center; border-radius: 5px; color: var(--asm-presence-mute); background: var(--asm-presence-raise); box-shadow: inset 0 -1.5px 0 var(--asm-presence-line2); }
}
.asm-presence .asm-presence-app {
  height: 100%; display: grid;
  grid-template-columns: 256px minmax(0, 1fr) 280px;
  grid-template-rows: auto minmax(0, 1fr) auto auto;
  grid-template-areas: "top top top" "people map side" "day day day" "keys keys keys";
}
.asm-presence .asm-presence-h { font-size: 10.5px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--asm-presence-faint); }

/* top */
.asm-presence .asm-presence-top { grid-area: top; display: flex; align-items: center; gap: 14px; padding: 11px 16px; border-bottom: 1px solid var(--asm-presence-line); }
.asm-presence .asm-presence-brand {
  display: flex; align-items: center; gap: 10px; margin-right: auto;
  & > svg { width: 30px; height: 30px; padding: 5px; border-radius: 9px; background: var(--asm-presence-accent); color: var(--asm-presence-bg); stroke-width: 2; }
  & b { display: block; font-size: 14.5px; letter-spacing: -.01em; }
  & small { display: block; font-size: 11.5px; color: var(--asm-presence-mute); white-space: nowrap; }
}
.asm-presence .asm-presence-clock {
  display: flex; align-items: baseline; gap: 8px; font-variant-numeric: tabular-nums;
  & b { font-size: 22px; font-weight: 300; letter-spacing: -.03em; }
  & span { font-size: 11px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; padding: 2px 7px; border-radius: 99px; background: var(--asm-presence-raise); color: var(--asm-presence-mute); }
}
.asm-presence[data-live="1"] .asm-presence-clock span { background: color-mix(in oklab, var(--asm-presence-home) 22%, transparent); color: var(--asm-presence-home); }
.asm-presence[data-future="1"] .asm-presence-clock span { background: color-mix(in oklab, var(--asm-presence-accent) 18%, transparent); color: var(--asm-presence-accent); }
.asm-presence .asm-presence-tabs { display: none; }

/* people */
.asm-presence .asm-presence-people { grid-area: people; min-height: 0; overflow: auto; padding: 14px 10px 14px 12px; border-right: 1px solid var(--asm-presence-line); display: flex; flex-direction: column; gap: 8px; scrollbar-width: thin;
  & > h2 { padding: 0 6px; }
}
.asm-presence .asm-presence-list { display: grid; gap: 3px; }
.asm-presence .asm-presence-person {
  position: relative; display: grid; grid-template-columns: 34px minmax(0, 1fr) auto; gap: 10px; align-items: start; padding: 9px 8px 9px 9px; border-radius: 12px; cursor: pointer;
  transition: background .2s; outline-offset: -2px;
  & .av { width: 34px; height: 34px; border-radius: 50%; display: grid; place-items: center; font-size: 11px; font-weight: 750; letter-spacing: .02em; color: oklch(0.2 0.02 100); background: var(--c);
    box-shadow: 0 0 0 2px var(--asm-presence-bg), 0 0 0 3.5px color-mix(in oklab, var(--c) 0%, transparent); transition: box-shadow .3s; }
  & .tx { min-width: 0; display: grid; gap: 1px; }
  & b { font-weight: 650; }
  & b small { font-weight: 500; font-size: 11px; color: var(--asm-presence-faint); margin-left: 3px; }
  & em { font-style: normal; font-size: 12px; color: var(--asm-presence-mute); line-height: 1.35; text-wrap: pretty; }
  & .meta { font-size: 11px; color: var(--asm-presence-faint); font-variant-numeric: tabular-nums; display: flex; align-items: center; gap: 2px; }
  & .bt { display: inline-flex; align-items: center; gap: 4px; }
  & .bt i { width: 16px; height: 8px; border-radius: 2px; box-shadow: inset 0 0 0 1px var(--asm-presence-line2); position: relative; overflow: hidden; }
  & .bt i::before { content: ""; position: absolute; inset: 1.5px; right: auto; width: calc(var(--b) * (100% - 3px)); background: var(--asm-presence-mute); border-radius: 1px; }
  & .bt.is-low { color: var(--asm-presence-p1); }
  & .bt.is-low i::before { background: var(--asm-presence-p1); }
  &.is-home .av { box-shadow: 0 0 0 2px var(--asm-presence-bg), 0 0 0 3.5px var(--asm-presence-home); }
  &.is-trip em { color: var(--asm-presence-ink); }
  &:hover { background: var(--asm-presence-hover); }
  &[aria-selected="true"] { background: var(--asm-presence-raise); box-shadow: inset 0 0 0 1px color-mix(in oklab, var(--c) 45%, transparent); }
}
.asm-presence .asm-presence-bell {
  width: 30px; height: 30px; border-radius: 8px; display: grid; place-items: center; color: var(--asm-presence-faint); transition: background .2s, color .2s;
  &:hover { background: var(--asm-presence-hover); color: var(--asm-presence-ink); }
  &[aria-checked="true"] { color: var(--asm-presence-accent); }
}

/* map */
.asm-presence .asm-presence-mapcard { grid-area: map; position: relative; min-width: 0; min-height: 0; display: grid; place-items: center; padding: 8px; overflow: hidden;
  background: radial-gradient(closest-side, color-mix(in oklab, var(--asm-presence-ink) 5%, var(--asm-presence-bg)), var(--asm-presence-bg)); }
.asm-presence .asm-presence-map {
  width: 100%; height: 100%; display: block; overflow: visible;
  & .rings circle { fill: none; stroke: var(--asm-presence-line); stroke-width: 1; stroke-dasharray: 2 4; }
  & .rings text { fill: var(--asm-presence-faint); stroke: none; font: 500 9px ui-monospace, Menlo, monospace; text-anchor: end; }
  & .compass { stroke: var(--asm-presence-line2); stroke-width: 1; }
  & .cn { fill: var(--asm-presence-faint); stroke: none; font: 700 9px system-ui, sans-serif; }
  & .fence { fill: color-mix(in oklab, var(--asm-presence-home) 12%, transparent); stroke: var(--asm-presence-home); stroke-width: 1; stroke-dasharray: 3 2; transition: r .3s var(--asm-presence-ease); }
  & .place rect { fill: var(--asm-presence-faint); stroke: none; transition: fill .3s; }
  & .place text { fill: var(--asm-presence-mute); stroke: none; font: 500 9.5px system-ui, sans-serif; transition: fill .3s; }
  & .place.is-here rect { fill: var(--asm-presence-ink); }
  & .place.is-here text { fill: var(--asm-presence-ink); font-weight: 650; }
  & .homemark circle { fill: var(--asm-presence-home); stroke: none; }
  & .homemark path { fill: var(--asm-presence-bg); stroke: none; }
  & .routes path { fill: none; stroke: var(--c); stroke-width: 1.4; stroke-dasharray: 3 4; opacity: .7; animation: asm-presence-march 1.2s linear infinite; }
  & .trail path { fill: none; stroke: var(--c); stroke-width: 2.2; stroke-linejoin: round; opacity: .55; }
  & .av { cursor: pointer; transition: transform .55s var(--asm-presence-spring), opacity .3s; outline: none; }
  & .av .disc { fill: var(--c); stroke: var(--asm-presence-bg); stroke-width: 2.5; transition: transform .3s var(--asm-presence-spring); }
  & .av text { fill: oklch(0.2 0.02 100); stroke: none; font: 750 9.5px system-ui, sans-serif; text-anchor: middle; pointer-events: none; }
  & .av .halo { fill: none; stroke: var(--c); stroke-width: 1.5; opacity: 0; transform-box: fill-box; transform-origin: center; }
  & .av.is-trip .halo { opacity: .5; stroke-dasharray: 3 3; animation: asm-presence-spin 6s linear infinite; }
  & .av.is-sel .halo { opacity: 1; stroke-dasharray: none; animation: asm-presence-ping 1.8s var(--asm-presence-ease) infinite; }
  & .av.is-dim { opacity: .45; }
  & .av:hover .disc, & .av:focus-visible .disc { transform: scale(1.12); transform-box: fill-box; transform-origin: center; }
}
.asm-presence.is-moving .asm-presence-map .av { transition: opacity .3s; }
.asm-presence .asm-presence-maptools { position: absolute; left: 12px; bottom: 10px; right: 12px; display: flex; justify-content: flex-start; pointer-events: none; }
.asm-presence .asm-presence-fence {
  pointer-events: auto; display: inline-flex; align-items: center; gap: 8px; padding: 6px 10px; border-radius: 10px; font-size: 11.5px; color: var(--asm-presence-mute);
  background: color-mix(in oklab, var(--asm-presence-panel) 85%, transparent); box-shadow: inset 0 0 0 1px var(--asm-presence-line); backdrop-filter: blur(6px);
  & input { width: 96px; accent-color: var(--asm-presence-home); }
  & output { font: 600 11px ui-monospace, Menlo, monospace; color: var(--asm-presence-ink); min-width: 4.2em; }
}

/* side */
.asm-presence .asm-presence-side { grid-area: side; min-height: 0; overflow: auto; padding: 14px; border-left: 1px solid var(--asm-presence-line); display: flex; flex-direction: column; gap: 10px; scrollbar-width: thin; }
.asm-presence .asm-presence-count {
  display: grid; gap: 4px; padding: 14px; border-radius: 14px; background: var(--asm-presence-panel); box-shadow: inset 0 0 0 1px var(--asm-presence-line);
  & .dots { display: flex; gap: 6px; }
  & .dots i { width: 12px; height: 12px; border-radius: 50%; box-shadow: inset 0 0 0 1.5px var(--c); transition: background .3s; }
  & .dots i.is-on { background: var(--c); }
  & p { display: flex; align-items: baseline; gap: 6px; }
  & b { font-size: 34px; font-weight: 250; letter-spacing: -.04em; line-height: 1; font-variant-numeric: tabular-nums; }
  & span { font-size: 14px; color: var(--asm-presence-mute); }
  & small { font-size: 12px; color: var(--asm-presence-mute); }
}
.asm-presence .asm-presence-autos {
  display: grid; gap: 2px;
  & li { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 7px 2px; border-bottom: 1px solid var(--asm-presence-line); }
  & b { display: block; font-size: 12.5px; font-weight: 600; }
  & small { display: block; font-size: 11.5px; color: var(--asm-presence-mute); }
}
.asm-presence .asm-presence-switch {
  position: relative; flex: none; width: 32px; height: 19px; border-radius: 99px; background: var(--asm-presence-line2); transition: background .25s;
  &::after { content: ""; position: absolute; left: 2px; top: 2px; width: 15px; height: 15px; border-radius: 50%; background: var(--asm-presence-ink); transition: transform .45s var(--asm-presence-spring); }
  &[aria-checked="true"] { background: var(--asm-presence-home); }
  &[aria-checked="true"]::after { transform: translateX(13px); background: var(--asm-presence-bg); }
}
.asm-presence .asm-presence-log {
  display: grid; gap: 0;
  & li { display: grid; grid-template-columns: 40px minmax(0, 1fr); gap: 8px; padding: 5px 0; font-size: 12px; color: var(--asm-presence-mute); border-left: 2px solid var(--c, var(--asm-presence-line2)); padding-left: 8px; animation: asm-presence-in .3s var(--asm-presence-ease) both; animation-delay: calc(var(--i) * 18ms); }
  & time { font: 500 11px ui-monospace, Menlo, monospace; color: var(--asm-presence-faint); padding-top: 1px; }
  & b { color: var(--asm-presence-ink); font-weight: 620; }
  & li.is-in span { color: var(--asm-presence-ink); }
  & li.is-sys { border-left-color: var(--asm-presence-accent); }
  & li.is-sys span { color: var(--asm-presence-accent); }
  & li.is-empty { border: 0; display: block; }
}

/* day lanes */
.asm-presence .asm-presence-day { grid-area: day; padding: 10px 16px 12px; border-top: 1px solid var(--asm-presence-line); display: grid; gap: 8px; min-width: 0; }
.asm-presence .asm-presence-dayhead { display: flex; align-items: center; gap: 14px; flex-wrap: wrap; }
.asm-presence .asm-presence-play { display: flex; gap: 6px; }
.asm-presence .asm-presence-btn {
  height: 30px; min-width: 30px; padding: 0 11px; border-radius: 9px; display: inline-grid; place-items: center; font-weight: 600; font-size: 12.5px;
  background: var(--asm-presence-raise); box-shadow: inset 0 0 0 1px var(--asm-presence-line2); transition: background .2s, transform .3s var(--asm-presence-spring);
  &:hover:not(:disabled) { background: color-mix(in oklab, var(--asm-presence-ink) 13%, var(--asm-presence-bg)); }
  &:active:not(:disabled) { transform: scale(.94); }
  &[data-act="play"] { padding: 0; width: 30px; }
  &.is-on { background: var(--asm-presence-accent); color: var(--asm-presence-bg); box-shadow: none; }
}
.asm-presence .asm-presence-hint { font-size: 12px; color: var(--asm-presence-mute); }
.asm-presence .asm-presence-lkey {
  display: flex; gap: 12px; margin-left: auto; font-size: 11.5px; color: var(--asm-presence-mute);
  & span { display: inline-flex; align-items: center; gap: 5px; }
  & i { width: 14px; height: 8px; border-radius: 2px; }
  & .k-home { background: color-mix(in oklab, var(--asm-presence-ink) 22%, transparent); }
  & .k-away { background: var(--asm-presence-ink); }
  & .k-trip { background: repeating-linear-gradient(135deg, var(--asm-presence-ink) 0 2px, transparent 2px 4px); }
  & .k-exp { box-shadow: inset 0 0 0 1px var(--asm-presence-ink); opacity: .6; }
}
.asm-presence .asm-presence-lanes { position: relative; cursor: ew-resize; touch-action: none; user-select: none; padding-top: 16px; }
.asm-presence .asm-presence-ticks {
  position: absolute; top: 0; left: var(--asm-presence-ln); right: 0; height: 14px;
  & span { position: absolute; translate: -50% 0; font: 500 9.5px ui-monospace, Menlo, monospace; color: var(--asm-presence-faint); }
  & span:first-child { translate: 0 0; }
  & span:last-child { translate: -100% 0; }
}
.asm-presence .asm-presence-rows { display: grid; gap: 4px; }
.asm-presence .lane {
  display: grid; grid-template-columns: var(--asm-presence-ln) minmax(0, 1fr); align-items: center; height: 18px;
  & .ln { font-size: 11.5px; font-weight: 600; color: var(--asm-presence-mute); cursor: default; }
  & .track { position: relative; height: 100%; border-radius: 4px; background: color-mix(in oklab, var(--asm-presence-ink) 3%, transparent); }
  & .track i { position: absolute; top: 2px; bottom: 2px; border-radius: 3px; }
  & .track i.home { background: color-mix(in oklab, var(--c) 26%, transparent); }
  & .track i.away { background: var(--c); }
  & .track i.trip { background: repeating-linear-gradient(135deg, var(--c) 0 2px, transparent 2px 5px); }
  & .track i.exp { -webkit-mask: linear-gradient(90deg, #000 var(--cut, 0%), rgba(0, 0, 0, .35) var(--cut, 0%)); mask: linear-gradient(90deg, #000 var(--cut, 0%), rgba(0, 0, 0, .35) var(--cut, 0%)); }
  &.is-sel .ln { color: var(--c); }
  &.is-sel .track { box-shadow: inset 0 0 0 1px color-mix(in oklab, var(--c) 50%, transparent); }
  &.house .track i.awaym { background: repeating-linear-gradient(90deg, color-mix(in oklab, var(--asm-presence-accent) 30%, transparent) 0 6px, color-mix(in oklab, var(--asm-presence-accent) 16%, transparent) 6px 12px); display: grid; place-items: center; overflow: hidden; }
  &.house .track i.awaym span { font-size: 9.5px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase; color: var(--asm-presence-accent); white-space: nowrap; }
  &.house .track i.nowl { top: -2px; bottom: -2px; width: 0; border-left: 1.5px dashed var(--asm-presence-mute); border-radius: 0; }
}
.asm-presence .asm-presence-scrub {
  position: absolute; top: 12px; bottom: -4px; left: calc(var(--asm-presence-ln) + var(--x, 0) * (100% - var(--asm-presence-ln))); width: 0; outline: none;
  & i { position: absolute; top: 4px; bottom: 0; left: -1px; width: 2px; background: var(--asm-presence-ink); border-radius: 2px; box-shadow: 0 0 0 1px var(--asm-presence-bg); }
  & span { position: absolute; top: -12px; left: 0; translate: -50% 0; padding: 1px 6px; border-radius: 5px; background: var(--asm-presence-ink); color: var(--asm-presence-bg); font: 650 10.5px ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; white-space: nowrap; }
  &:focus-visible span { box-shadow: 0 0 0 2px var(--asm-presence-accent); }
}
.asm-presence[data-live="1"] .asm-presence-scrub span { background: var(--asm-presence-home); }

/* footer + toast */
.asm-presence .asm-presence-keys {
  grid-area: keys; display: flex; flex-wrap: wrap; gap: 4px 16px; padding: 8px 16px; border-top: 1px solid var(--asm-presence-line); font-size: 11.5px; color: var(--asm-presence-mute);
  & span { display: inline-flex; align-items: center; gap: 4px; }
}
.asm-presence .asm-presence-toast {
