const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => Array.from(el.querySelectorAll(s));
const ic = (p) => '<svg viewBox="0 0 24 24" aria-hidden="true">' + p + '</svg>';
const reduce = matchMedia('(prefers-reduced-motion: reduce)');
const NOW = 21 * 60 + 40;
const hhmm = (m) => { m = Math.max(0, Math.min(1439, Math.round(m))); return String(Math.floor(m / 60)).padStart(2, '0') + ':' + String(m % 60).padStart(2, '0'); };

/* ── places: distance in km and bearing from home ── */
const PL = {
  home: { name: 'Home', d: 0, b: 0 },
  park: { name: 'Fenn Park', d: 0.6, b: 330 },
  linden: { name: 'Linden Primary', d: 0.9, b: 40 },
  shop: { name: 'Corner market', d: 1.4, b: 228 },
  mira: { name: "Mira's house", d: 1.8, b: 95 },
  hollis: { name: 'Hollis Academy', d: 2.6, b: 125 },
  pool: { name: 'Westbrook pool', d: 3.4, b: 160 },
  depot: { name: 'Northgate depot', d: 6.2, b: 205 },
  office: { name: 'Vane & Co studio', d: 11.5, b: 268 },
  halina: { name: "Grandma Halina's", d: 34, b: 20 }
};
const MODE = { train: 'On the train', bus: 'On the bus', bike: 'Cycling', car: 'Driving', walk: 'Walking' };
const S = (p, a, b) => ({ p: p, a: a, b: b }), T = (m, a, b) => ({ t: m, a: a, b: b });
const PEOPLE = [
  { id: 'ines', name: 'Ines', role: 'Parent', ini: 'IV', hue: 'var(--asm-presence-p1)', batt: 64, segs: [S('home', 0, 460), T('train', 460, 505), S('office', 505, 1050), T('train', 1050, 1090), S('shop', 1090, 1115), T('walk', 1115, 1130), S('home', 1130, 1440)] },
  { id: 'tomasz', name: 'Tomasz', role: 'Parent', ini: 'TO', hue: 'var(--asm-presence-p2)', batt: 38, segs: [S('home', 0, 350), T('bike', 350, 370), S('depot', 370, 860), T('bike', 860, 885), S('home', 885, 1170), T('car', 1170, 1215), S('halina', 1215, 1290), T('car', 1290, 1340), S('home', 1340, 1440)] },
  { id: 'lea', name: 'Lea', role: '14', ini: 'LE', hue: 'var(--asm-presence-p3)', batt: 12, segs: [S('home', 0, 470), T('bus', 470, 495), S('hollis', 495, 930), T('bus', 930, 945), S('pool', 945, 1065), T('bus', 1065, 1095), S('home', 1095, 1230), T('walk', 1230, 1245), S('mira', 1245, 1350), T('walk', 1350, 1370), S('home', 1370, 1440)] },
  { id: 'oskar', name: 'Oskar', role: '9', ini: 'OS', hue: 'var(--asm-presence-p4)', batt: 81, segs: [S('home', 0, 500), T('walk', 500, 515), S('linden', 515, 915), T('walk', 915, 930), S('home', 930, 1440)] },
  { id: 'biscuit', name: 'Biscuit', role: 'Dog · collar tag', ini: 'B', hue: 'var(--asm-presence-p5)', batt: 55, pet: true, segs: [S('home', 0, 420), T('walk', 420, 435), S('park', 435, 465), T('walk', 465, 480), S('home', 480, 990), T('walk', 990, 1005), S('park', 1005, 1050), T('walk', 1050, 1065), S('home', 1065, 1440)] }
];
const state = { t: NOW, sel: null, playing: false, fence: 150, alerts: { ines: false, tomasz: true, lea: true, oskar: false, biscuit: false }, autos: { away: true, welcome: true, night: false } };

/* ── geometry: real km on a plane, drawn on a log-scale radius ── */
const KM = (p) => { const r = (PL[p].b * Math.PI) / 180; return [PL[p].d * Math.sin(r), -PL[p].d * Math.cos(r)]; };
const RAD = (d) => (180 * Math.log(1 + d / 0.25)) / Math.log(1 + 40 / 0.25);
function toScreen(x, y) { const d = Math.hypot(x, y); if (d < 1e-6) return [0, 0]; const r = RAD(d); return [(x / d) * r, (y / d) * r]; }
function segAt(p, m) { return p.segs.find((s) => m >= s.a && m < s.b) || p.segs[p.segs.length - 1]; }
function where(p, m) {
  const i = p.segs.indexOf(segAt(p, m)), s = p.segs[i];
  if (s.p) return { stay: s, km: KM(s.p), place: s.p };
  const from = p.segs[i - 1].p, to = p.segs[i + 1].p, k = (m - s.a) / (s.b - s.a), A = KM(from), B = KM(to);
  return { trip: s, from: from, to: to, k: k, km: [A[0] + (B[0] - A[0]) * k, A[1] + (B[1] - A[1]) * k] };
}
const humans = PEOPLE.filter((p) => !p.pet);
const homeCount = (m) => humans.filter((p) => { const w = where(p, m); return w.place === 'home'; }).length;
function awayBands() {
  const out = []; let start = null;
  for (let m = 0; m <= 1440; m += 5) {
    const empty = m < 1440 && homeCount(m) === 0;
    if (empty && start === null) start = m;
    if (!empty && start !== null) { out.push([start, m]); start = null; }
  }
  return out;
}
const AWAY = awayBands();

/* ── map ── */
const map = $('[data-map]');
(function buildMap() {
  let h = '<g class="rings">' + [[0.5, '500 m'], [2, '2 km'], [10, '10 km'], [40, '40 km']].map((r) => '<circle r="' + RAD(r[0]).toFixed(1) + '"/><text x="-4" y="' + (-RAD(r[0]) + 11).toFixed(1) + '">' + r[1] + '</text>').join('') + '</g>';
  h += '<path class="compass" d="M0 -197v10M0 187v10M-197 0h10M187 0h10"/><text class="cn" x="8" y="-188">N</text>';
  h += '<circle class="fence" data-fencec r="10"/>';
  h += '<g class="routes" data-routes></g><g class="trail" data-trail></g>';
  h += '<g class="places">' + Object.keys(PL).filter((k) => k !== 'home').map((k) => {
    const [x, y] = toScreen(...KM(k)), w = PL[k].name.length * 5.4;
    /* labels sit on the outer side unless that would leave the map */
    const right = x >= 0 ? x + 8 + w < 196 : x - 8 - w < -196;
    return '<g class="place" data-place="' + k + '"><rect x="' + (x - 3).toFixed(1) + '" y="' + (y - 3).toFixed(1) + '" width="6" height="6" transform="rotate(45 ' + x.toFixed(1) + ' ' + y.toFixed(1) + ')"/><text x="' + (x + (right ? 8 : -8)).toFixed(1) + '" y="' + (y + 3.5).toFixed(1) + '" text-anchor="' + (right ? 'start' : 'end') + '">' + PL[k].name + '</text></g>';
  }).join('') + '</g>';
  h += '<g class="homemark"><circle r="7"/><path d="M-3.5 1.5V-1L0 -3.8 3.5 -1v2.5Z"/></g>';
  h += '<g class="avatars">' + PEOPLE.map((p, i) => '<g class="av" data-av="' + p.id + '" style="--c:' + p.hue + '" role="button" tabindex="-1" aria-label="' + p.name + '"><circle class="halo" r="20"/><circle class="disc" r="12"/><text y="3.8">' + p.ini + '</text></g>').join('') + '</g>';
  map.innerHTML = h;
})();
function paintMap() {
  const pos = {}, groups = {};
  PEOPLE.forEach((p) => {
    const w = where(p, state.t), s = toScreen(...w.km);
    pos[p.id] = { w: w, s: s };
    const key = w.place || ('t' + p.id);
    (groups[key] = groups[key] || []).push(p.id);
  });
  /* people at the same place fan out around it */
  Object.values(groups).forEach((ids) => {
    if (ids.length < 2) return;
    ids.forEach((id, i) => { const a = (i / ids.length) * Math.PI * 2 - Math.PI / 2, r = 15; pos[id].s = [pos[id].s[0] + Math.cos(a) * r, pos[id].s[1] + Math.sin(a) * r]; });
  });
  PEOPLE.forEach((p) => {
    const g = $('[data-av="' + p.id + '"]', map), P = pos[p.id];
    g.style.transform = 'translate(' + P.s[0].toFixed(2) + 'px,' + P.s[1].toFixed(2) + 'px)';
    g.classList.toggle('is-trip', !!P.w.trip);
    g.classList.toggle('is-sel', state.sel === p.id);
    g.classList.toggle('is-dim', !!state.sel && state.sel !== p.id);
    g.setAttribute('aria-label', p.name + ': ' + status(p, state.t).text);
  });
  /* routes of everyone travelling right now */
  $('[data-routes]', map).innerHTML = PEOPLE.map((p) => {
    const w = pos[p.id].w; if (!w.trip) return '';
    const pts = []; const A = KM(w.from), B = KM(w.to);
    for (let k = 0; k <= 1.0001; k += 0.05) pts.push(toScreen(A[0] + (B[0] - A[0]) * k, A[1] + (B[1] - A[1]) * k));
    return '<path style="--c:' + p.hue + '" d="M' + pts.map((q) => q[0].toFixed(1) + ' ' + q[1].toFixed(1)).join('L') + '"/>';
  }).join('');
  /* the selected person's trail from midnight to the scrubbed time */
  const tr = $('[data-trail]', map);
  if (state.sel) {
    const p = PEOPLE.find((x) => x.id === state.sel), pts = [];
    for (let m = 0; m <= state.t; m += 5) pts.push(toScreen(...where(p, m).km));
    pts.push(toScreen(...where(p, state.t).km));
    tr.innerHTML = '<path style="--c:' + p.hue + '" d="M' + pts.map((q) => q[0].toFixed(1) + ' ' + q[1].toFixed(1)).join('L') + '"/>';
  } else tr.innerHTML = '';
  $('[data-fencec]', map).setAttribute('r', RAD(state.fence / 1000).toFixed(2));
  $$('[data-place]', map).forEach((g) => {
    const k = g.dataset.place, here = PEOPLE.some((p) => pos[p.id].w.place === k);
    g.classList.toggle('is-here', here);
  });
}

/* ── words ── */
function status(p, m) {
  const w = where(p, m), future = m > NOW, pre = future ? 'Expected: ' : '';
  if (w.stay) {
    const since = w.stay.a === 0 ? 'last night' : hhmm(w.stay.a);
    if (w.place === 'home') return { text: pre + 'Home since ' + since, km: 0, home: true };
    return { text: pre + 'At ' + PL[w.place].name + ' since ' + since, km: PL[w.place].d };
  }
  const left = Math.max(1, Math.round(w.trip.b - m));
  return { text: pre + MODE[w.trip.t] + ' to ' + (w.to === 'home' ? 'home' : PL[w.to].name) + ' · ETA ' + hhmm(w.trip.b) + ' (' + left + ' min)', km: Math.hypot(...w.km), trip: true };
}
function events(upto) {
  const ev = [];
  PEOPLE.forEach((p) => p.segs.forEach((s) => {
    if (!s.p) return;
    if (s.a > 0 && s.a <= upto) ev.push({ m: s.a, p: p, txt: s.p === 'home' ? 'arrived home' : 'arrived at ' + PL[s.p].name, home: s.p === 'home', arr: true });
    if (s.b < 1440 && s.b <= upto) ev.push({ m: s.b, p: p, txt: s.p === 'home' ? 'left home' : 'left ' + PL[s.p].name, home: s.p === 'home', arr: false });
  }));
  AWAY.forEach((b) => {
    if (state.autos.away && b[0] <= upto) ev.push({ m: b[0], sys: true, txt: 'Last one out · Away mode on' });
    if (state.autos.welcome && b[1] <= upto && b[1] < 1440) ev.push({ m: b[1], sys: true, txt: 'First one home · welcome lights' });
  });
  return ev.sort((a, b) => b.m - a.m || (a.sys ? -1 : 1));
}

/* ── panels ── */
function renderPeople() {
  $('[data-people]').innerHTML = PEOPLE.map((p, i) => {
    const st = status(p, state.t);
    return '<li class="asm-presence-person' + (st.home ? ' is-home' : st.trip ? ' is-trip' : '') + '" role="option" tabindex="' + ((state.sel ? state.sel === p.id : i === 0) ? 0 : -1) + '" aria-selected="' + (state.sel === p.id) + '" data-person="' + p.id + '" style="--c:' + p.hue + ';--i:' + i + '">' +
      '<span class="av">' + p.ini + '</span><span class="tx"><b>' + p.name + ' <small>' + p.role + '</small></b><em>' + st.text + '</em>' +
      '<span class="meta">' + (st.km ? st.km.toFixed(1) + ' km away · ' : '') + '<span class="bt' + (p.batt < 20 ? ' is-low' : '') + '"><i style="--b:' + p.batt / 100 + '"></i>' + p.batt + '%</span></span></span>' +
      '<button type="button" class="asm-presence-bell" role="switch" aria-checked="' + state.alerts[p.id] + '" data-alert="' + p.id + '" aria-label="Tell me when ' + p.name + ' gets home" title="Tell me when ' + p.name + ' gets home">' +
      ic(state.alerts[p.id] ? '<path d="M6 16.5V11a6 6 0 0 1 12 0v5.5l1.5 2h-15Z"/><path d="M10 20.5a2 2 0 0 0 4 0"/>' : '<path d="M6 16.5V11a6 6 0 0 1 9.5-4.9M18 11v5.5l1.5 2H8"/><path d="M10 20.5a2 2 0 0 0 4 0M4 4l16 16"/>') + '</button></li>';
  }).join('');
}
function renderSide() {
  const n = homeCount(state.t), pets = PEOPLE.filter((p) => p.pet && where(p, state.t).place === 'home').length;
  const inAway = AWAY.find((b) => state.t >= b[0] && state.t < b[1]);
  $('[data-count]').innerHTML = '<div class="dots">' + humans.map((p) => '<i class="' + (where(p, state.t).place === 'home' ? 'is-on' : '') + '" style="--c:' + p.hue + '"></i>').join('') + '</div>' +
    '<p><b>' + n + '</b><span> of ' + humans.length + ' home</span></p><small>' + (inAway && state.autos.away ? 'House in Away mode since ' + hhmm(inAway[0]) : n === 0 ? 'Nobody home' : pets ? 'Biscuit is home too' : 'Biscuit is out') + '</small>';
  const autos = [
    ['away', 'Last one out', 'Lock up, heating to 16°, Away mode'],
    ['welcome', 'First one home', 'Hall and kitchen lights to 60%'],
    ['night', 'Everyone home after 22:00', 'Arm Night mode']
  ];
  $('[data-autos]').innerHTML = autos.map((a) => '<li><span><b>' + a[1] + '</b><small>' + a[2] + '</small></span><button type="button" class="asm-presence-switch" role="switch" aria-checked="' + state.autos[a[0]] + '" data-auto="' + a[0] + '" aria-label="' + a[1] + '"></button></li>').join('');
  const ev = events(state.t).slice(0, 14);
  $('[data-log]').innerHTML = ev.map((e, i) => '<li class="' + (e.sys ? 'is-sys' : e.home ? (e.arr ? 'is-in' : 'is-out') : '') + '" style="--i:' + i + (e.p ? ';--c:' + e.p.hue : '') + '"><time>' + hhmm(e.m) + '</time><span>' + (e.p ? '<b>' + e.p.name + '</b> ' : '') + e.txt + '</span></li>').join('') || '<li class="is-empty">Nothing yet today</li>';
}
const X = (m) => ((m / 1440) * 100).toFixed(3) + '%';
function renderLanes() {
  $('[data-ticks]').innerHTML = [0, 3, 6, 9, 12, 15, 18, 21, 24].map((h) => '<span style="left:' + X(h * 60) + '">' + String(h).padStart(2, '0') + '</span>').join('');
  let rows = PEOPLE.map((p) => '<div class="lane" data-lane="' + p.id + '" style="--c:' + p.hue + '"><span class="ln">' + p.name + '</span><div class="track">' +
    p.segs.map((s) => {
      const cls = s.p ? (s.p === 'home' ? 'home' : 'away') : 'trip';
      const exp = s.b > NOW ? ' exp' : '';
      const title = s.p ? PL[s.p].name + ' ' + hhmm(s.a) + '–' + hhmm(s.b) : MODE[s.t] + ' ' + hhmm(s.a) + '–' + hhmm(s.b);
      return '<i class="' + cls + exp + '" style="left:' + X(s.a) + ';width:' + X(s.b - s.a) + (s.a < NOW && s.b > NOW ? ';--cut:' + (((NOW - s.a) / (s.b - s.a)) * 100).toFixed(2) + '%' : '') + '" title="' + title + '"></i>';
    }).join('') + '</div></div>').join('');
  rows += '<div class="lane house"><span class="ln">House</span><div class="track">' + AWAY.map((b) => '<i class="awaym" style="left:' + X(b[0]) + ';width:' + X(b[1] - b[0]) + '" title="Away mode ' + hhmm(b[0]) + '–' + hhmm(b[1]) + '"><span>Away mode</span></i>').join('') +
    '<i class="nowl" style="left:' + X(NOW) + '"></i></div></div>';
  $('[data-rows]').innerHTML = rows;
}
function paintScrub() {
  const s = $('[data-scrub]');
  s.style.setProperty('--x', (state.t / 1440).toFixed(5));
  $('[data-scrubt]').textContent = hhmm(state.t);
  s.setAttribute('aria-valuenow', String(Math.round(state.t)));
  s.setAttribute('aria-valuetext', hhmm(state.t) + (Math.round(state.t) === NOW ? ', now' : ''));
  const live = Math.round(state.t) === NOW;
  root.dataset.live = live ? '1' : '0';
  root.dataset.future = state.t > NOW ? '1' : '0';
  $('[data-clock]').textContent = hhmm(state.t);
  $('[data-mode]').textContent = live ? 'Live' : state.t > NOW ? 'Expected' : 'Earlier today';
  const nb = $('[data-act="now"]');
  nb.disabled = live; nb.title = live ? 'Already showing now' : 'Jump to now (N)';
  $$('[data-lane]').forEach((l) => l.classList.toggle('is-sel', state.sel === l.dataset.lane));
}
function renderAll() { paintMap(); renderPeople(); renderSide(); paintScrub(); }

/* ── time control ── */
let lastSide = 0;
function setT(m, light) {
  state.t = Math.max(0, Math.min(1439, m));
  paintMap(); paintScrub();
  const now = performance.now();
  if (!light || now - lastSide > 120) { renderPeople(); renderSide(); lastSide = now; }
}
let raf = 0, prev = 0;
function play(on) {
  state.playing = on;
  const b = $('[data-act="play"]');
  b.setAttribute('aria-label', on ? 'Pause' : 'Play the day');
  b.innerHTML = on ? ic('<path d="M9 6v12M15 6v12"/>') : ic('<path d="M8 5.5v13l10-6.5Z"/>');
  b.classList.toggle('is-on', on);
  root.classList.toggle('is-moving', on);
  if (on) {
    if (state.t >= NOW - 1 || state.t >= 1438) setT(0);
