  const dt = Math.min(100, ts - prev); prev = ts;
  const speed = reduce.matches ? 30 : 50;          /* minutes of the day per second */
  const next = state.t + (dt / 1000) * speed;
  if (next >= NOW) { setT(NOW); play(false); toast('Caught up with now'); return; }
  setT(next, true);
  raf = requestAnimationFrame(tick);
}
const scrub = $('[data-scrub]'), lanes = $('[data-lanes]');
function fromX(clientX) { const r = $('[data-rows] .track').getBoundingClientRect(); return ((clientX - r.left) / r.width) * 1440; }
lanes.addEventListener('pointerdown', (e) => {
  if (e.target.closest('.ln')) return;
  if (state.playing) play(false);
  lanes.setPointerCapture(e.pointerId);
  root.classList.add('is-moving');
  setT(fromX(e.clientX), true);
  const mv = (ev) => setT(fromX(ev.clientX), true);
  const up = () => { root.classList.remove('is-moving'); lanes.removeEventListener('pointermove', mv); lanes.removeEventListener('pointerup', up); lanes.removeEventListener('pointercancel', up); renderPeople(); renderSide(); };
  lanes.addEventListener('pointermove', mv); lanes.addEventListener('pointerup', up); lanes.addEventListener('pointercancel', up);
});

/* ── toast, views ── */
let tT = 0;
function toast(m) { const t = $('[data-toast]'); t.textContent = m; t.hidden = false; clearTimeout(tT); tT = setTimeout(() => { if (root.isConnected) t.hidden = true; }, 3200); }
function setView(v) { root.dataset.view = v; $$('[data-tab]').forEach((t) => t.setAttribute('aria-selected', String(t.dataset.tab === v))); }
function select(id) {
  state.sel = state.sel === id ? null : id;
  renderPeople(); paintMap(); paintScrub();
  const p = PEOPLE.find((x) => x.id === state.sel);
  if (p) toast(p.name + ': ' + status(p, state.t).text);
}

root.addEventListener('click', (e) => {
  const t = e.target.closest('button, [data-person], [data-av]');
  if (!t || !root.contains(t)) return;
  if (t.dataset.alert) {
    e.stopPropagation();
    const id = t.dataset.alert; state.alerts[id] = !state.alerts[id]; renderPeople();
    const p = PEOPLE.find((x) => x.id === id);
    toast(state.alerts[id] ? 'You will be told when ' + p.name + ' gets home' : 'No arrival alert for ' + p.name);
    return;
  }
  if (t.dataset.person) { select(t.dataset.person); if (root.clientWidth < 760 && state.sel) setView('map'); return; }
  if (t.dataset.av) { select(t.dataset.av); return; }
  if (t.dataset.tab) return setView(t.dataset.tab);
  if (t.dataset.auto) {
    const k = t.dataset.auto; state.autos[k] = !state.autos[k]; renderSide();
    toast(t.getAttribute('aria-label') + (state.autos[k] ? ' on' : ' off'));
    return;
  }
  const a = t.dataset.act;
  if (a === 'play') play(!state.playing);
  else if (a === 'now') { play(false); setT(NOW); }
});
root.addEventListener('input', (e) => {
  if (!e.target.matches('[data-fence]')) return;
  state.fence = +e.target.value; $('[data-fenceo]').textContent = state.fence + ' m'; paintMap();
});
root.addEventListener('keydown', (e) => {
  const tg = e.target, k = e.key;
  if (tg.matches('input')) return;
  if (e.metaKey || e.ctrlKey || e.altKey) return;
  if (tg.dataset.person && /^Arrow(Up|Down)$/.test(k)) {
    e.preventDefault();
    const it = $$('[data-person]'), i = it.indexOf(tg), n = it[(i + (k === 'ArrowDown' ? 1 : -1) + it.length) % it.length];
    it.forEach((x) => { x.tabIndex = -1; }); n.tabIndex = 0; n.focus(); return;
  }
  if (tg.dataset.person && (k === 'Enter' || k === ' ')) { e.preventDefault(); select(tg.dataset.person); $('[data-person="' + tg.dataset.person + '"]').focus(); return; }
  if (k === 'ArrowRight' || k === 'ArrowLeft') { e.preventDefault(); if (state.playing) play(false); setT(Math.round(state.t / 15) * 15 + (k === 'ArrowRight' ? 1 : -1) * (e.shiftKey ? 60 : 15)); }
  else if (k === 'Home' && tg === scrub) { e.preventDefault(); setT(0); }
  else if (k === 'End' && tg === scrub) { e.preventDefault(); setT(NOW); }
  else if (k === ' ') { e.preventDefault(); play(!state.playing); }
  else if (k === 'n' || k === 'N') { play(false); setT(NOW); }
  else if (k >= '1' && k <= '5') select(PEOPLE[+k - 1].id);
  else if (k === 'Escape') { if (state.playing) play(false); else if (state.sel) select(state.sel); }
});

renderLanes();
renderAll();

css:
.asm-pair {
  /* re-theme with these four */
  --asm-pair-paper: oklch(0.984 0.003 262);
  --asm-pair-ink: oklch(0.24 0.028 262);
  --asm-pair-accent: oklch(0.52 0.2 263);
  --asm-pair-card: oklch(1 0 0);
  /* derived */
  --asm-pair-side: color-mix(in oklab, var(--asm-pair-ink) 3.5%, var(--asm-pair-paper));
  --asm-pair-line: color-mix(in oklab, var(--asm-pair-ink) 10%, transparent);
  --asm-pair-line2: color-mix(in oklab, var(--asm-pair-ink) 18%, transparent);
  --asm-pair-mute: color-mix(in oklab, var(--asm-pair-ink) 60%, var(--asm-pair-paper));
  --asm-pair-faint: color-mix(in oklab, var(--asm-pair-ink) 40%, var(--asm-pair-paper));
  --asm-pair-hover: color-mix(in oklab, var(--asm-pair-ink) 5%, transparent);
  --asm-pair-tint: color-mix(in oklab, var(--asm-pair-accent) 10%, var(--asm-pair-card));
  --asm-pair-thread: var(--asm-pair-accent);
  --asm-pair-zigbee: oklch(0.7 0.15 62);
  --asm-pair-wifi: oklch(0.62 0.13 155);
  --asm-pair-good: oklch(0.58 0.14 152);
  --asm-pair-warn: oklch(0.66 0.15 65);
  --asm-pair-bad: oklch(0.58 0.2 28);
  --asm-pair-ease: cubic-bezier(.2, .8, .2, 1);
  --asm-pair-spring: linear(0, 0.12 4%, 0.42 10%, 0.78 17%, 0.98 24%, 1.06 30%, 1.07 36%, 1.035 45%, 1.005 56%, 0.997 70%, 1);

  position: relative; width: 100%; height: var(--asm-pair-h, 680px); box-sizing: border-box;
  container-type: inline-size; container-name: asm-pair; overflow: clip; isolation: isolate;
  background: var(--asm-pair-paper); color: var(--asm-pair-ink); color-scheme: light; border-radius: 16px;
  accent-color: var(--asm-pair-accent);
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  box-shadow: inset 0 0 0 1px var(--asm-pair-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--asm-pair-accent); outline-offset: 2px; }
  & button, & input { font: inherit; color: inherit; }
  & button { background: none; border: 0; padding: 0; cursor: pointer; }
  & button:disabled { cursor: not-allowed; opacity: .42; }
  & h2, & h3, & p, & ul, & ol, & dl, & dd { margin: 0; padding: 0; }
  & ul, & ol { list-style: none; }
  & [hidden] { display: none !important; }
  & svg { fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; flex: none; width: 16px; height: 16px; }
  & kbd { font: 600 10px/1 ui-monospace, Menlo, monospace; min-width: 16px; padding: 3px 4px; text-align: center; border-radius: 5px; color: var(--asm-pair-mute); background: var(--asm-pair-card); box-shadow: inset 0 0 0 1px var(--asm-pair-line2), inset 0 -1.5px 0 var(--asm-pair-line2); }
  & .pt-thread { --c: var(--asm-pair-thread); }
  & .pt-zigbee { --c: var(--asm-pair-zigbee); }
  & .pt-wifi { --c: var(--asm-pair-wifi); }
  & .pt-hub, & .pt-ap { --c: var(--asm-pair-ink); }
}
.asm-pair .asm-pair-app {
  height: 100%; display: grid;
  grid-template-columns: 284px minmax(0, 1fr) 300px;
  grid-template-rows: auto minmax(0, 1fr) auto;
  grid-template-areas: "top top top" "list mesh info" "keys keys keys";
}
.asm-pair .asm-pair-h { font-size: 10.5px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--asm-pair-faint); }

/* top */
.asm-pair .asm-pair-top { grid-area: top; display: flex; align-items: center; gap: 14px; padding: 11px 16px; border-bottom: 1px solid var(--asm-pair-line); }
.asm-pair .asm-pair-brand {
  display: flex; align-items: center; gap: 10px;
  & > svg { width: 30px; height: 30px; padding: 5px; border-radius: 9px; background: var(--asm-pair-ink); color: var(--asm-pair-paper); stroke-width: 1.8; }
  & b { display: block; font-size: 14.5px; letter-spacing: -.01em; }
  & small { display: block; font-size: 11.5px; color: var(--asm-pair-mute); white-space: nowrap; }
}
.asm-pair .asm-pair-nets {
  margin-left: auto; display: flex; gap: 14px; font-size: 12px; color: var(--asm-pair-mute); white-space: nowrap;
  & span { display: inline-flex; align-items: center; gap: 6px; }
  & i { width: 8px; height: 8px; border-radius: 50%; background: var(--c); }
  & b { color: var(--asm-pair-ink); font-variant-numeric: tabular-nums; }
  & .is-off { color: var(--asm-pair-bad); font-weight: 600; }
  & .is-off i { background: var(--asm-pair-bad); }
}
.asm-pair .asm-pair-tabs { display: none; }
.asm-pair .asm-pair-btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 7px; height: 32px; padding: 0 12px; border-radius: 9px; font-weight: 580; white-space: nowrap;
  background: var(--asm-pair-card); box-shadow: inset 0 0 0 1px var(--asm-pair-line2); transition: background .2s, transform .3s var(--asm-pair-spring);
  &:hover:not(:disabled) { background: color-mix(in oklab, var(--asm-pair-ink) 4%, var(--asm-pair-card)); }
  &:active:not(:disabled) { transform: scale(.96); }
  &.is-accent { background: var(--asm-pair-accent); color: white; box-shadow: none; }
  &.is-accent:hover:not(:disabled) { background: color-mix(in oklab, var(--asm-pair-accent) 86%, black); }
  &.is-accent kbd { background: color-mix(in oklab, white 20%, transparent); color: white; box-shadow: none; }
  &.is-danger { color: var(--asm-pair-bad); }
  &.is-dangerfill { background: var(--asm-pair-bad); color: white; box-shadow: none; }
}
.asm-pair .asm-pair-mini { height: 24px; padding: 0 9px; border-radius: 7px; font-size: 11.5px; font-weight: 650; }
.asm-pair .asm-pair-mini.is-accent { background: var(--asm-pair-accent); color: white; }

/* list */
.asm-pair .asm-pair-list { grid-area: list; min-height: 0; overflow: auto; padding: 14px 12px 16px; background: var(--asm-pair-side); border-right: 1px solid var(--asm-pair-line); display: flex; flex-direction: column; gap: 10px; scrollbar-width: thin; }
.asm-pair .asm-pair-search {
  display: flex; align-items: center; gap: 8px; height: 34px; padding: 0 8px 0 10px; border-radius: 10px; background: var(--asm-pair-card); box-shadow: inset 0 0 0 1px var(--asm-pair-line2); color: var(--asm-pair-mute); flex: none;
  &:focus-within { box-shadow: inset 0 0 0 1.5px var(--asm-pair-accent), 0 0 0 4px color-mix(in oklab, var(--asm-pair-accent) 14%, transparent); }
  & input { flex: 1; min-width: 0; border: 0; background: none; outline: none; color: var(--asm-pair-ink); }
  & input::-webkit-search-cancel-button { display: none; }
}
.asm-pair .asm-pair-filters {
  display: flex; flex-wrap: wrap; gap: 4px; flex: none;
  & button { height: 25px; padding: 0 8px; border-radius: 99px; font-size: 11.5px; font-weight: 580; color: var(--asm-pair-mute); box-shadow: inset 0 0 0 1px var(--asm-pair-line2); }
  & button span { opacity: .65; font-variant-numeric: tabular-nums; }
  & button:hover { color: var(--asm-pair-ink); background: var(--asm-pair-hover); }
  & button[aria-checked="true"] { background: var(--asm-pair-ink); color: var(--asm-pair-paper); box-shadow: none; cursor: default; }
}
.asm-pair .asm-pair-groups { display: grid; gap: 2px;
  & h3 { padding: 8px 6px 3px; }
  & ul { display: grid; gap: 1px; }
}
.asm-pair .asm-pair-dev {
  display: grid; grid-template-columns: 30px minmax(0, 1fr) auto; align-items: center; gap: 10px; padding: 7px 8px; border-radius: 10px; cursor: pointer; transition: background .2s; outline-offset: -2px;
  & .tx { min-width: 0; display: grid; }
  & b { font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  & small { font-size: 11.5px; color: var(--asm-pair-mute); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-variant-numeric: tabular-nums; }
  &:hover { background: var(--asm-pair-hover); }
  &[aria-selected="true"] { background: var(--asm-pair-card); box-shadow: inset 0 0 0 1px var(--asm-pair-line), 0 1px 3px color-mix(in oklab, var(--asm-pair-ink) 8%, transparent); cursor: default; }
  &.is-off small { color: var(--asm-pair-bad); }
  &.is-fresh { animation: asm-pair-flash 1.6s var(--asm-pair-ease); }
}
.asm-pair .ic { width: 30px; height: 30px; border-radius: 9px; display: grid; place-items: center; flex: none; color: color-mix(in oklab, var(--c) 85%, var(--asm-pair-ink)); background: color-mix(in oklab, var(--c) 13%, var(--asm-pair-card)); }
.asm-pair .bars {
  display: inline-flex; align-items: end; gap: 1.5px; height: 12px; margin-right: 6px; vertical-align: -1px;
  & i { width: 3px; border-radius: 1px; background: var(--asm-pair-line2); }
  & i:nth-child(1) { height: 4px; } & i:nth-child(2) { height: 6.5px; } & i:nth-child(3) { height: 9px; } & i:nth-child(4) { height: 12px; }
  &.q4 i.on, &.q3 i.on { background: var(--asm-pair-good); }
  &.q2 i.on { background: var(--asm-pair-warn); }
  &.q1 i.on { background: var(--asm-pair-bad); }
}
.asm-pair .asm-pair-empty { padding: 16px 6px; color: var(--asm-pair-mute); text-align: center; }
.asm-pair .asm-pair-link { color: var(--asm-pair-accent); font-weight: 650; text-decoration: underline; text-underline-offset: 3px; }

/* mesh */
.asm-pair .asm-pair-mesh { grid-area: mesh; min-width: 0; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); padding: 12px 14px 12px; }
.asm-pair .asm-pair-meshhead { display: flex; justify-content: space-between; align-items: center; gap: 10px; }
.asm-pair .asm-pair-legend {
  display: flex; gap: 12px; font-size: 11.5px; color: var(--asm-pair-mute);
  & span { display: inline-flex; align-items: center; gap: 5px; }
  & i { width: 16px; height: 0; border-top: 2px solid; }
  & .q4 { border-color: color-mix(in oklab, var(--asm-pair-ink) 55%, transparent); }
  & .q2 { border-color: var(--asm-pair-warn); }
  & .q1 { border-color: var(--asm-pair-bad); border-top-style: dotted; }
  & .lan { border-color: var(--asm-pair-ink); border-top-style: dashed; }
}
.asm-pair .asm-pair-mapwrap {
  min-height: 0; border-radius: 14px; margin-top: 8px; background: radial-gradient(circle, var(--asm-pair-line) 1px, transparent 1.2px) 0 0 / 18px 18px, var(--asm-pair-card);
  box-shadow: inset 0 0 0 1px var(--asm-pair-line); position: relative;
}
.asm-pair .asm-pair-map {
  position: absolute; inset: 0; width: 100%; height: 100%; display: block; overflow: visible;
  & .ln { fill: none; stroke-width: 2; stroke-linecap: round; transition: stroke .3s, stroke-width .3s; }
  & .ln.q4, & .ln.q3 { stroke: color-mix(in oklab, var(--asm-pair-ink) 32%, transparent); }
  & .ln.q2 { stroke: color-mix(in oklab, var(--asm-pair-warn) 80%, transparent); }
  & .ln.q1 { stroke: var(--asm-pair-bad); stroke-dasharray: 1 4; }
  & .ln.off { stroke: var(--asm-pair-line2); stroke-dasharray: 4 5; }
  & .ln.lan { stroke: var(--asm-pair-ink); stroke-dasharray: 6 4; stroke-width: 1.5; }
  & .ln.is-route { stroke: var(--asm-pair-accent); stroke-width: 3.5; stroke-dasharray: none; }
  & .fl { fill: none; stroke: color-mix(in oklab, var(--asm-pair-accent) 70%, white); stroke-width: 2.5; stroke-linecap: round; stroke-dasharray: 1.5 22; animation: asm-pair-flow 1.8s linear infinite; animation-delay: calc(var(--i) * -260ms); opacity: .8; }
  & .fl.is-route { stroke: white; opacity: 1; }
  & .nd { cursor: pointer; outline: none; }
  & .nd[aria-current="true"] { cursor: default; }
  & .nd .bg { fill: var(--asm-pair-card); stroke: var(--c, var(--asm-pair-thread)); stroke-width: 1.8; transition: stroke-width .25s; }
  & .nd.is-router .bg { stroke-width: 2.6; }
  & .nd .gl { color: color-mix(in oklab, var(--c, var(--asm-pair-thread)) 85%, var(--asm-pair-ink)); pointer-events: none; }
  & .nd text { fill: var(--asm-pair-mute); font: 550 10px system-ui, sans-serif; text-anchor: middle; stroke: var(--asm-pair-card); stroke-width: 3px; paint-order: stroke; stroke-linejoin: round; pointer-events: none; }
  & .nd .ring { fill: none; stroke: var(--asm-pair-accent); stroke-width: 2; opacity: 0; transition: opacity .25s; }
  & .nd .ping { fill: color-mix(in oklab, var(--asm-pair-accent) 30%, transparent); stroke: none; opacity: 0; transform-box: fill-box; transform-origin: center; }
  & .nd:hover .bg { stroke-width: 3.4; }
  & .nd.is-sel .ring { opacity: 1; }
  & .nd.is-sel text { fill: var(--asm-pair-ink); font-weight: 700; }
  & .nd.is-hub .bg { fill: var(--asm-pair-ink); stroke: var(--asm-pair-ink); }
  & .nd.is-hub .gl { color: var(--asm-pair-paper); }
  & .nd.is-off .bg { stroke: var(--asm-pair-bad); stroke-dasharray: 3 3; }
  & .nd.is-off .gl { color: var(--asm-pair-faint); }
  & .nd.is-ident .ping { animation: asm-pair-ping 1s var(--asm-pair-ease) infinite; }
  & .nd.is-new { animation: asm-pair-pop .6s var(--asm-pair-spring) .55s both; transform-box: fill-box; transform-origin: center; }
}
.asm-pair .asm-pair-fly { position: absolute; z-index: 30; display: grid; place-items: center; border-radius: 50%; color: white; background: var(--c); pointer-events: none; box-shadow: 0 8px 20px -6px color-mix(in oklab, var(--c) 70%, black); }

/* info */
.asm-pair .asm-pair-info { grid-area: info; min-height: 0; overflow: auto; padding: 16px; border-left: 1px solid var(--asm-pair-line); background: var(--asm-pair-side); display: flex; flex-direction: column; gap: 14px; scrollbar-width: thin; }
.asm-pair .asm-pair-ihead {
  display: grid; grid-template-columns: 42px minmax(0, 1fr); gap: 12px; align-items: center;
  & .ic { width: 42px; height: 42px; border-radius: 12px; }
  & .ic svg { width: 22px; height: 22px; }
  & p { font-size: 12px; color: var(--asm-pair-mute); }
}
.asm-pair .asm-pair-name {
  width: 100%; border: 0; background: none; padding: 0; outline: none; border-radius: 4px; font-size: clamp(16px, 1.5cqi, 19px); font-weight: 700; letter-spacing: -.02em; color: var(--asm-pair-ink);
  box-shadow: 0 1.5px 0 transparent; transition: box-shadow .2s;
  &:not([readonly]):hover { box-shadow: 0 1.5px 0 var(--asm-pair-line2); }
  &:focus { box-shadow: 0 2px 0 var(--asm-pair-accent); }
}
.asm-pair .asm-pair-chips {
  display: flex; flex-wrap: wrap; gap: 6px;
  & span { padding: 3px 9px; border-radius: 99px; font-size: 11.5px; font-weight: 600; background: var(--asm-pair-card); box-shadow: inset 0 0 0 1px var(--asm-pair-line2); }
  & .is-good { color: var(--asm-pair-good); box-shadow: inset 0 0 0 1px color-mix(in oklab, var(--asm-pair-good) 45%, transparent); }
  & .is-bad { color: var(--asm-pair-bad); box-shadow: inset 0 0 0 1px color-mix(in oklab, var(--asm-pair-bad) 45%, transparent); }
  & .is-warn { color: color-mix(in oklab, var(--asm-pair-warn) 80%, var(--asm-pair-ink)); }
}
.asm-pair .asm-pair-facts {
  display: grid; gap: 10px;
  & dt { font-size: 10.5px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--asm-pair-faint); margin-bottom: 2px; }
  & dd { font-size: 12.5px; font-variant-numeric: tabular-nums; display: flex; align-items: center; flex-wrap: wrap; gap: 4px; }
  & .route span { padding: 2px 7px; border-radius: 6px; background: var(--asm-pair-card); box-shadow: inset 0 0 0 1px var(--asm-pair-line); font-weight: 560; }
  & .route svg { width: 12px; height: 12px; color: var(--asm-pair-faint); }
  & .route em { font-style: normal; color: var(--asm-pair-mute); margin-left: 4px; }
}
.asm-pair .asm-pair-prog { display: inline-block; width: 120px; height: 6px; border-radius: 4px; background: var(--asm-pair-line); overflow: hidden; margin-right: 6px; vertical-align: middle;
  & i { display: block; height: 100%; background: var(--asm-pair-accent); transform-origin: left; transition: transform .16s linear; }
}
.asm-pair .asm-pair-acts { display: flex; flex-wrap: wrap; gap: 6px; }
.asm-pair .asm-pair-pingres { font-size: 12px; font-weight: 560; padding: 8px 10px; border-radius: 9px; animation: asm-pair-in .3s var(--asm-pair-ease);
  &.is-good { background: color-mix(in oklab, var(--asm-pair-good) 12%, var(--asm-pair-card)); color: color-mix(in oklab, var(--asm-pair-good) 70%, var(--asm-pair-ink)); }
  &.is-bad { background: color-mix(in oklab, var(--asm-pair-bad) 10%, var(--asm-pair-card)); color: var(--asm-pair-bad); }
}
.asm-pair .asm-pair-confirm {
  display: grid; gap: 10px; padding: 12px; border-radius: 12px; background: color-mix(in oklab, var(--asm-pair-bad) 7%, var(--asm-pair-card)); box-shadow: inset 0 0 0 1px color-mix(in oklab, var(--asm-pair-bad) 30%, transparent);
  animation: asm-pair-in .3s var(--asm-pair-ease);
  & p { font-size: 12.5px; text-wrap: pretty; }
  & div { display: flex; gap: 6px; justify-content: flex-end; }
}

/* wizard */
.asm-pair .asm-pair-wiz {
  position: absolute; inset: 0; z-index: 20; display: grid; place-items: center; padding: 16px;
  background: color-mix(in oklab, var(--asm-pair-ink) 28%, transparent); backdrop-filter: blur(5px);
  transition: opacity .25s; @starting-style { opacity: 0; }
}
.asm-pair .asm-pair-wizbox {
  width: min(500px, 100%); max-height: 100%; overflow: auto; border-radius: 18px; background: var(--asm-pair-card); box-shadow: 0 30px 70px -20px color-mix(in oklab, var(--asm-pair-ink) 60%, transparent);
  display: grid; transition: transform .45s var(--asm-pair-spring), opacity .25s; @starting-style { transform: translateY(14px) scale(.97); opacity: 0; }
}
.asm-pair .asm-pair-wizhead {
  display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 10px 8px; padding: 16px 16px 12px; border-bottom: 1px solid var(--asm-pair-line);
  & h2 { font-size: 16px; font-weight: 700; letter-spacing: -.01em; }
}
.asm-pair .asm-pair-x { grid-row: 1; grid-column: 2; width: 28px; height: 28px; border-radius: 8px; display: grid; place-items: center; color: var(--asm-pair-mute); }
.asm-pair .asm-pair-x:hover { background: var(--asm-pair-hover); color: var(--asm-pair-ink); }
.asm-pair .asm-pair-steps {
  grid-column: 1 / -1; display: flex; gap: 6px;
  & li { flex: 1; display: flex; align-items: center; gap: 6px; font-size: 11.5px; font-weight: 600; color: var(--asm-pair-faint); padding-top: 8px; border-top: 2.5px solid var(--asm-pair-line); transition: border-color .4s, color .4s; }
  & i { width: 18px; height: 18px; border-radius: 50%; display: grid; place-items: center; font-style: normal; font-size: 10px; box-shadow: inset 0 0 0 1.5px currentColor; }
  & .is-now { color: var(--asm-pair-accent); border-color: var(--asm-pair-accent); }
  & .is-done { color: var(--asm-pair-ink); border-color: var(--asm-pair-ink); }
  & .is-done i { background: var(--asm-pair-ink); color: var(--asm-pair-card); box-shadow: none; }
}
.asm-pair .asm-pair-wizbody { padding: 16px; display: grid; gap: 12px; min-height: 0; }
.asm-pair .asm-pair-wizfoot { display: flex; justify-content: flex-end; gap: 8px; padding: 12px 16px 16px; }
.asm-pair .asm-pair-wizlead { text-align: center; color: var(--asm-pair-mute); font-size: 12.5px; }
.asm-pair .asm-pair-radar {
  position: relative; width: 168px; height: 168px; margin: 0 auto; border-radius: 50%;
  background: radial-gradient(circle, var(--asm-pair-tint), var(--asm-pair-card) 70%);
  & > i { position: absolute; inset: 0; border-radius: 50%; box-shadow: inset 0 0 0 1px var(--asm-pair-line2); }
  & > i:nth-child(2) { inset: 28px; } & > i:nth-child(3) { inset: 56px; background: var(--asm-pair-accent); box-shadow: 0 0 0 6px color-mix(in oklab, var(--asm-pair-accent) 18%, transparent); }
  & .sweep { position: absolute; inset: 0; border-radius: 50%; background: conic-gradient(from 0deg, color-mix(in oklab, var(--asm-pair-accent) 34%, transparent), transparent 70deg); opacity: 0; transition: opacity .4s; }
  &.is-scan .sweep { opacity: 1; animation: asm-pair-spin 1.6s linear infinite; }
  & b { position: absolute; left: 50%; top: 50%; width: 12px; height: 12px; margin: -6px; border-radius: 50%; background: var(--asm-pair-accent); box-shadow: 0 0 0 4px color-mix(in oklab, var(--asm-pair-accent) 22%, transparent);
    transform: rotate(var(--a)) translateY(calc(var(--r) * -1)); animation: asm-pair-blip .5s var(--asm-pair-spring) both; }
}
.asm-pair .asm-pair-cands { display: grid; gap: 6px; }
.asm-pair .asm-pair-cand {
  display: grid; grid-template-columns: 34px minmax(0, 1fr); align-items: center; gap: 10px; padding: 9px 11px; border-radius: 12px; text-align: left;
  box-shadow: inset 0 0 0 1px var(--asm-pair-line2); animation: asm-pair-in .35s var(--asm-pair-ease) both; transition: box-shadow .2s, background .2s;
  & .ic { width: 34px; height: 34px; }
  & b { display: block; font-weight: 650; }
  & small { display: block; font-size: 11.5px; color: var(--asm-pair-mute); font-variant-numeric: tabular-nums; }
  &:hover { background: var(--asm-pair-hover); }
  &[aria-checked="true"] { box-shadow: inset 0 0 0 2px var(--asm-pair-accent); background: var(--asm-pair-tint); cursor: default; }
  &.is-static { animation: none; }
  &.is-static:hover { background: none; }
  &.is-ok { box-shadow: inset 0 0 0 1.5px var(--asm-pair-good); background: color-mix(in oklab, var(--asm-pair-good) 8%, var(--asm-pair-card)); }
}
.asm-pair .asm-pair-code {
  display: flex; align-items: center; justify-content: center; gap: 6px;
  & input { width: 38px; height: 46px; border: 0; border-radius: 10px; text-align: center; font: 600 20px ui-monospace, Menlo, monospace; background: var(--asm-pair-side); box-shadow: inset 0 0 0 1.5px var(--asm-pair-line2); outline: none; transition: box-shadow .2s; }
  & input:focus { box-shadow: inset 0 0 0 2px var(--asm-pair-accent), 0 0 0 4px color-mix(in oklab, var(--asm-pair-accent) 14%, transparent); }
  & span { color: var(--asm-pair-faint); font-weight: 600; }
  &.is-err input { box-shadow: inset 0 0 0 1.5px var(--asm-pair-bad); }
}
.asm-pair .asm-pair-err { min-height: 1.4em; text-align: center; font-size: 12px; color: var(--asm-pair-bad); text-wrap: balance; }
.asm-pair .asm-pair-join {
  display: grid; gap: 4px;
  & li { display: grid; grid-template-columns: 26px minmax(0, 1fr); gap: 10px; align-items: start; padding: 6px 0; color: var(--asm-pair-faint); transition: color .3s; }
  & i { width: 22px; height: 22px; border-radius: 50%; display: grid; place-items: center; box-shadow: inset 0 0 0 1.5px var(--asm-pair-line2); margin-top: 1px; }
  & i svg { width: 13px; height: 13px; stroke-width: 2.4; }
  & b { display: block; font-weight: 620; }
  & small { display: block; font-size: 11.5px; font-variant-numeric: tabular-nums; }
  & .is-now { color: var(--asm-pair-ink); }
  & .is-now i { box-shadow: inset 0 0 0 2px var(--asm-pair-accent); border-top: 2px solid transparent; animation: asm-pair-spin .9s linear infinite; background: conic-gradient(var(--asm-pair-accent) 0 25%, transparent 25%); -webkit-mask: radial-gradient(circle, transparent 7px, #000 7.5px); mask: radial-gradient(circle, transparent 7px, #000 7.5px); }
  & .is-done { color: var(--asm-pair-ink); }
  & .is-done i { background: var(--asm-pair-good); color: white; box-shadow: none; }
  & .asm-pair-prog { margin-top: 6px; width: 100%; }
}
.asm-pair .asm-pair-field {
  display: grid; gap: 6px;
  & > span { font-size: 10.5px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--asm-pair-faint); }
  & input { height: 36px; padding: 0 10px; border: 0; border-radius: 9px; background: var(--asm-pair-side); box-shadow: inset 0 0 0 1.5px var(--asm-pair-line2); outline: none; font-weight: 600; }
  & input:focus { box-shadow: inset 0 0 0 2px var(--asm-pair-accent); }
}
.asm-pair .asm-pair-rooms {
  display: flex; flex-wrap: wrap; gap: 5px;
  & button { height: 28px; padding: 0 10px; border-radius: 99px; font-size: 12px; font-weight: 580; box-shadow: inset 0 0 0 1px var(--asm-pair-line2); color: var(--asm-pair-mute); }
  & button:hover { color: var(--asm-pair-ink); background: var(--asm-pair-hover); }
  & button[aria-checked="true"] { background: var(--asm-pair-accent); color: white; box-shadow: none; cursor: default; }
}

/* footer + toast */
.asm-pair .asm-pair-keys {
  grid-area: keys; display: flex; flex-wrap: wrap; gap: 4px 16px; padding: 8px 16px; border-top: 1px solid var(--asm-pair-line); font-size: 11.5px; color: var(--asm-pair-mute);
  & span { display: inline-flex; align-items: center; gap: 4px; }
}
.asm-pair .asm-pair-toast {
  position: absolute; left: 50%; bottom: 46px; z-index: 40; display: flex; align-items: center; gap: 12px; max-width: calc(100% - 32px); padding: 8px 8px 8px 14px; border-radius: 12px;
  background: var(--asm-pair-ink); color: var(--asm-pair-paper); font-size: 12.5px; translate: -50% 0; box-shadow: 0 16px 36px -12px color-mix(in oklab, var(--asm-pair-ink) 60%, transparent);
  transition: opacity .3s var(--asm-pair-ease), translate .45s var(--asm-pair-spring);
  @starting-style { opacity: 0; translate: -50% 12px; }
  & span { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  & button { flex: none; height: 26px; padding: 0 10px; border-radius: 7px; font-weight: 650; color: color-mix(in oklab, var(--asm-pair-accent) 45%, white); background: color-mix(in oklab, white 10%, transparent); }
}

@keyframes asm-pair-flow { to { stroke-dashoffset: -47; } }
@keyframes asm-pair-ping { 0% { opacity: .9; transform: scale(.8); } 100% { opacity: 0; transform: scale(2.2); } }
@keyframes asm-pair-pop { 0% { opacity: 0; transform: scale(.3); } 100% { opacity: 1; transform: scale(1); } }
@keyframes asm-pair-spin { to { rotate: 360deg; } }
@keyframes asm-pair-blip { from { opacity: 0; scale: .2; } }
@keyframes asm-pair-in { from { opacity: 0; transform: translateY(5px); } }
@keyframes asm-pair-flash { 0%, 40% { background: color-mix(in oklab, var(--asm-pair-accent) 18%, var(--asm-pair-card)); } }

/* responsive */
@container asm-pair (width < 960px) {
  .asm-pair .asm-pair-app {
    grid-template-columns: 250px minmax(0, 1fr);
    grid-template-rows: auto minmax(0, 1fr) minmax(0, .85fr) auto;
    grid-template-areas: "top top" "list mesh" "list info" "keys keys";
  }
  .asm-pair .asm-pair-info { border-left: 0; border-top: 1px solid var(--asm-pair-line); }
  .asm-pair .asm-pair-nets span:not(.is-off) { display: none; }
  .asm-pair .asm-pair-legend { display: none; }
}
@container asm-pair (width < 760px) {
  .asm-pair .asm-pair-app { grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr) auto; grid-template-areas: "top" "main" "keys"; }
  .asm-pair .asm-pair-top { flex-wrap: wrap; gap: 8px; padding: 10px 12px; }
  .asm-pair .asm-pair-brand small { display: none; }
  .asm-pair .asm-pair-nets { margin-left: auto; }
  .asm-pair .asm-pair-top > .asm-pair-btn span, .asm-pair .asm-pair-top > .asm-pair-btn kbd { display: none; }
  .asm-pair .asm-pair-top > .asm-pair-btn { width: 34px; padding: 0; }
  .asm-pair .asm-pair-tabs {
    display: flex; order: 3; width: 100%; padding: 3px; border-radius: 10px; background: var(--asm-pair-side); box-shadow: inset 0 0 0 1px var(--asm-pair-line);
    & button { flex: 1; height: 28px; border-radius: 7px; font-size: 12.5px; font-weight: 600; color: var(--asm-pair-mute); }
    & button[aria-selected="true"] { background: var(--asm-pair-card); color: var(--asm-pair-ink); cursor: default; box-shadow: 0 1px 2px color-mix(in oklab, var(--asm-pair-ink) 12%, transparent); }
  }
  .asm-pair .asm-pair-list, .asm-pair .asm-pair-mesh, .asm-pair .asm-pair-info { grid-area: main; border: 0; }
  .asm-pair .asm-pair-keys { display: none; }
  .asm-pair .asm-pair-toast { bottom: 12px; }
  .asm-pair[data-view="list"] :is(.asm-pair-mesh, .asm-pair-info),
  .asm-pair[data-view="map"] :is(.asm-pair-list, .asm-pair-info),
  .asm-pair[data-view="info"] :is(.asm-pair-list, .asm-pair-mesh) { display: none; }
}
@container asm-pair (width < 460px) {
  .asm-pair .asm-pair-code input { width: 31px; height: 42px; font-size: 17px; }
  .asm-pair .asm-pair-code { gap: 4px; }
  .asm-pair .asm-pair-steps li { font-size: 0; gap: 0; }
  .asm-pair .asm-pair-steps i { font-size: 10px; }
}

@media (prefers-reduced-motion: reduce) {
  .asm-pair, .asm-pair *, .asm-pair *::before, .asm-pair *::after {
    animation-duration: 1ms !important; animation-delay: 0ms !important; animation-iteration-count: 1 !important; transition-duration: 1ms !important; transition-delay: 0ms !important;
  }
  .asm-pair .asm-pair-map .fl { display: none; }
}

