  contact: '<rect x="4" y="4" width="7" height="16" rx="1.5"/><rect x="14" y="7" width="5" height="10" rx="1.5"/>',
  motion: '<circle cx="12" cy="12" r="3"/><path d="M5.6 5.6a9 9 0 0 0 0 12.8M18.4 5.6a9 9 0 0 1 0 12.8"/>',
  leak: '<path d="M12 3.5c3 4 5.5 7 5.5 10a5.5 5.5 0 0 1-11 0c0-3 2.5-6 5.5-10Z"/>',
  thermo: '<path d="M12 3.5v10"/><circle cx="12" cy="16.5" r="3.5"/><path d="M15.5 6.5h3M15.5 9.5h2"/>',
  button: '<circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="3.5"/>',
  sensor: '<rect x="5" y="5" width="14" height="14" rx="4"/><path d="M9 12h6"/>',
  camera: '<rect x="3.5" y="7" width="13" height="10" rx="2"/><path d="m16.5 10.5 4-2.5v8l-4-2.5"/>',
  speaker: '<rect x="6" y="3" width="12" height="18" rx="2.5"/><circle cx="12" cy="14" r="3"/>',
  tv: '<rect x="3" y="5" width="18" height="12" rx="1.5"/><path d="M9 20h6"/>'
};
const PROTO = { thread: 'Thread', zigbee: 'Zigbee', wifi: 'Wi-Fi', hub: 'Hub', ap: 'LAN' };
const D = (id, name, room, proto, kind, parent, q, x, y, extra) => Object.assign({ id, name, room, proto, kind, parent, q, x, y, router: false, batt: null, fw: '1.4.3', fwNew: null, off: false }, extra || {});
let devs = [
  D('hub', 'Lattice Hub', 'Hallway', 'hub', 'hub', null, 255, 300, 225, { router: true, fw: '3.2.0' }),
  D('ap', 'Access point', 'Study', 'ap', 'ap', 'hub', 255, 300, 92, { router: true, fw: '7.1.4' }),
  D('t1', 'Hall plug', 'Hallway', 'thread', 'plug', 'hub', 238, 405, 175, { router: true }),
  D('t2', 'Kitchen strip', 'Kitchen', 'thread', 'light', 'hub', 214, 415, 300, { router: true, fwNew: '1.4.4', fw: '1.4.2' }),
  D('t3', 'Living lamp', 'Living room', 'thread', 'light', 'hub', 226, 300, 335, { router: true }),
  D('t4', 'Study plug', 'Study', 'thread', 'plug', 't1', 180, 515, 228, { router: true }),
  D('e1', 'Front door contact', 'Hallway', 'thread', 'contact', 't1', 205, 488, 128, { batt: 82 }),
