  D('w2', 'Kitchen speaker', 'Kitchen', 'wifi', 'speaker', 'ap', 214, 395, 40, { fw: '22.3' }),
  D('w3', 'Living room TV', 'Living room', 'wifi', 'tv', 'ap', 236, 300, 22, { fw: '9.0.2' })
];
const CANDS = [
  { id: 'n1', name: 'Contact sensor C3', proto: 'thread', kind: 'contact', code: '34178820', rssi: -58, parent: 't3', x: 372, y: 405, room: 'Living room' },
  { id: 'n2', name: 'Smart plug mini P2', proto: 'zigbee', kind: 'plug', code: '20581147', rssi: -66, parent: 'z1', x: 105, y: 175, room: 'Garage', router: true },
  { id: 'n3', name: 'Leak sensor W1', proto: 'thread', kind: 'leak', code: '77310452', rssi: -71, parent: 't2', x: 470, y: 412, room: 'Kitchen' }
];
const ROOMS = ['Hallway', 'Living room', 'Kitchen', 'Study', 'Bedroom', 'Garage', 'Garden', 'Porch'];
const state = { sel: 't1', filter: 'all', q: '', wiz: null, confirm: false, ping: {}, updating: null, undo: null, view: 'list' };
const byId = (id) => devs.find((d) => d.id === id);
const qual = (d) => d.off ? 0 : d.q >= 200 ? 4 : d.q >= 160 ? 3 : d.q >= 110 ? 2 : 1;
