const dbm = (d) => d.proto === 'wifi' || d.proto === 'ap' ? -Math.round(100 - d.q / 4) : -Math.round(100 - d.q / 4.6);

/* ── map ── */
const map = $('[data-map]');
function renderMap() {
  const sel = byId(state.sel), rt = sel ? route(sel).map((d) => d.id) : [];
