  });
  devs.forEach((d, i) => {
    const r = d.kind === 'hub' ? 21 : d.router ? 14 : 10;
    const isSel = d.id === state.sel;
    nodes += '<g transform="translate(' + d.x + ' ' + d.y + ')"><g class="nd pt-' + d.proto + (d.router ? ' is-router' : '') + (d.off ? ' is-off' : '') + (d.kind === 'hub' ? ' is-hub' : '') + (isSel ? ' is-sel' : '') + (d.isNew ? ' is-new' : '') + (state.identify === d.id ? ' is-ident' : '') +
      '" data-node="' + d.id + '" role="button" tabindex="-1" style="--i:' + i + '"' + (isSel ? ' aria-current="true"' : '') + ' aria-label="' + esc(d.name) + (d.off ? ', offline' : '') + '">' +
